INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(10455, 'plPL', 'Napierająca dzicz', 'Przyspieszamy wzrost Żywego Gaju, ale rysie, które w nim żyją, jakimś sposobem wymknęły się nam spod kontroli.$B$BKiedyś ich liczebność była stała, a teraz rysie tropiciele z gaju zaczynają zapuszczać się aż do Sylvanaar i ostatnio doszło do kilku przykrych incydentów.$B$BPodejrzewam, że w jakiś sposób stoją za tym arakkoa z Zasłony Lashh, ale najpilniejszym problemem są same rysie.$B$BByłabym ogromnie wdzięczna, gdybyś $gpomógł:pomogła; nam uporać się z tą sytuacją.', 'Zabij 12 rysi tropicieli z gaju.', '', 'Wróć do Riny Księżycowe Źródło w Sylvanaar w Górach Klingi.', '', '', '', '', 0),
(10456, 'plPL', 'Grasujące wilki', 'Plugawe rasy Hordy zajęły osadę na wschodzie. Przyprowadziły ze sobą dużą watahę srogich wilków, których najchętniej używają jako wierzchowców i wartowników.$B$BTe wilki grasują na moście, który nas rozdziela. Polują na nasze czarodziejskie smokowce, niezbędne do zapylania Żywego Gaju.$B$BWyjdź wschodnim wyjściem, przejdź przez most nad Parowem Krwawych Młotów, który prowadzi na Poszarpaną Grań na wschodzie, i przynieś mi ich ogony jako dowód!', 'Zbierz 4 ogony srogich wilków Władców Gromu.', '', 'Wróć do Riny Księżycowe Źródło w Sylvanaar w Górach Klingi.', '', '', '', '', 0),
(10457, 'plPL', 'W obronie swoich', 'Choć wiele już $gzrobiłeś:zrobiłaś; w obronie naszego nowego domu, wciąż uważam, że Żywy Gaj potrzebuje więcej ochrony.$B$BProszę, weź tę gałązkę, którą nasyciłam siłą natury. Gdy użyjesz jej na sadzonkach, które posadziłam w gaju, ściągnie burzę, która przyspieszy wzrost drzewca obrońcy.$B$BTe drzewce są niezbędne do obrony gaju, zwłaszcza jeśli nie zamierzasz zostać w Sylvanaar na długo.', 'Użyj Konaru Riny na 5 sadzonkach z gaju, by przyzwać obrońców Żywego Gaju.', '', 'Wróć do Riny Księżycowe Źródło w Sylvanaar w Górach Klingi.', 'Przyzwani obrońcy Żywego Gaju', '', '', '', 0),
(10486, 'plPL', 'Napierająca dzicz', 'Władcy Gromu byli niegdyś dumnym klanem orków, zanim krew Mannorotha przemieniła ich w spaczone orki.$B$BNiedawno odbiliśmy tę orczą warownię z rąk ogrów, którymi roi się parów w dole. Wprowadziły się tu, gdy klan Władców Gromu ją opuścił.$B$BUtrzymamy to miejsce, a ty mi w tym pomożesz.$B$BNa Poszarpanej Grani na południu i zachodzie upuszczacze krwi stały się dla nas prawdziwą plagą. Bez przerwy żrą i się mnożą.$B$BZabij je i wróć do mnie.', 'Zabij 12 ostroskrzydłych upuszczaczy krwi.', '', 'Wróć do Gor\'dreka w Warowni Władców Gromu w Górach Klingi.', '', '', '', '', 0),
(10487, 'plPL', 'Pył ze smokowców', 'Przymierze niedawno osiedliło się na zachodzie i dzięki elfiej magii w krótkim czasie wyhodowało sobie miasto i gaj. Musimy utrzymać ich obronę w słabości, żeby nie wyrósł im przy okazji kręgosłup.$B$BMam plan, który to załatwi, a nawet więcej. Przejdź przez most na południowym zachodzie – wiedzie nad Parowem Krwawych Młotów do Żywego Gaju.$B$BZaatakuj czarodziejskie smokowce, które bronią Żywego Gaju, i przynieś magiczny pył, który czasem można znaleźć na ich skrzydłach.', 'Zbierz 4 porcje pyłu czarodziejskiego smokowca.', '', 'Wróć do Gor\'dreka w Warowni Władców Gromu w Górach Klingi.', '', '', '', '', 0),
(10488, 'plPL', 'W obronie swoich', 'Z magicznego pyłu, który $gzdobyłeś:zdobyłaś;, przygotowałem magiczną maść, która wesprze naszą obronę.$B$BNasze srogie wilki to doskonałe połączenie wierzchowca, wartownika i przyjaciela, ale przymierzowa hołota kłusuje na nie na Poszarpanej Grani.$B$B$N, weź tę maść i natrzyj nią naszych wilczych przyjaciół. Przymierze przeżyje przykrą niespodziankę, gdy następnym razem wyśle swoich myśliwych.$B$BUważaj jednak – niektórym wilkom może się to nie spodobać i rzucą się na ciebie.', 'Użyj Maści Gor\'dreka na 5 srogich wilkach Władców Gromu.', '', 'Wróć do Gor\'dreka w Warowni Władców Gromu w Górach Klingi.', 'Wzmocniony srogi wilk Władców Gromu', '', '', '', 0),
(10489, 'plPL', 'Ścinanie pradawnego drzewa', 'POSZUKIWANY!$B$BSilnokonary głębokorzeń, pradrzewiec wojny i główny obrońca Żywego Gaju na południe od Sylvanaar.$B$BAby go znaleźć, idź na zachód przez most nad Parowem Krwawych Młotów.$B$BJego ścięty pień dostarcz Tor\'chunkowi Dwuszponowi.', 'Zdobądź pień silnokonarego głębokorzenia.', '', 'Wróć do Tor\'chunka Dwuszpona w Warowni Władców Gromu w Górach Klingi.', '', '', '', '', 0),
(10502, 'plPL', 'Ogry Krwawych Młotów', 'Dla Sylvanaar istnieje zagrożenie znacznie groźniejsze niż Horda w Warowni Władców Gromu.$B$BMówię o rdzennych ograch tych gór. Na południowy wschód stąd, w dole parowu, żyje klan Krwawych Młotów. Nie są jedynymi ogrami, które nam tu zagrażają, ale są najbliżej.$B$BIdź na południe przez Żywy Gaj, a potem zejdź ścieżką na wschód, która prowadzi do ich posterunku. Zabij jak najwięcej ogrów Krwawych Młotów w Posterunku Krwawych Młotów.', 'Zabij 30 dowolnych ogrów Krwawych Młotów w Posterunku Krwawych Młotów.', '', 'Wróć do Dowódcy Niebocienia w Sylvanaar w Górach Klingi.', 'Zabite ogry Krwawych Młotów', '', '', '', 0),
(10503, 'plPL', 'Zagrożenie ze strony Klanu Ostrza', 'Dla Warowni Władców Gromu istnieje zagrożenie gorsze niż Przymierze w Sylvanaar.$B$BMówię o ograch tych gór. Na zachód stąd, w dole parowu, siedzi Klan Ostrza. Nie są jedynymi ogrami, ale są najbliżej, a do tego to właśnie ich pokonaliśmy, by zająć to miejsce.$B$BIdź na północ przez Poszarpaną Grań, a potem zejdź ścieżką, która prowadzi do ich warowni. Zabij jak najwięcej ogrów Klanu Ostrza i ich raptorów w Warowni Klanu Ostrza i na Ziemiach Klanu Ostrza.', 'Zabij 30 dowolnych ogrów Klanu Ostrza i 10 raptorów Klanu Ostrza w Warowni Klanu Ostrza i na Ziemiach Klanu Ostrza.', '', 'Wróć do Tor\'chunka Dwuszpona w Warowni Władców Gromu w Górach Klingi.', 'Zabite ogry Klanu Ostrza', '', '', '', 0),
(10504, 'plPL', 'Ogry Klanu Ostrza', 'Na północ od klanu Krwawych Młotów czai się poważniejsze zagrożenie: Warownia Klanu Ostrza.$B$BOgry Klanu Ostrza to najsilniejszy klan w tych górach, cieszą się bowiem łaską gronna zwanego Gruulem Smokobójcą i jego siedmiu synów.$B$BSkoro przerzedziliśmy już Krwawe Młoty, pora zwrócić uwagę na ich rywali.$B$BOd siedziby Krwawych Młotów idź na północ przez parów, aż dotrzesz do Warowni Klanu Ostrza i Ziem Klanu Ostrza. Zabij tam jak najwięcej ogrów Klanu Ostrza.', 'Zabij 30 dowolnych ogrów Klanu Ostrza w Warowni Klanu Ostrza i na Ziemiach Klanu Ostrza.', '', 'Wróć do Dowódcy Niebocienia w Sylvanaar w Górach Klingi.', 'Zabite ogry Klanu Ostrza', '', '', '', 0),
(10505, 'plPL', 'Ogry Krwawych Młotów', 'Na południe od Klanu Ostrza czai się kolejne zagrożenie: Posterunek Krwawych Młotów.$B$BOgry Krwawych Młotów nie są najsilniejszym klanem w tych górach, bo nie cieszą się łaską gronna zwanego Gruulem Smokobójcą, ale niewiele im brakuje.$B$BSkoro przerzedziliśmy już Klan Ostrza, pora zwrócić uwagę na ich rywali.$B$BOd Warowni Klanu Ostrza idź na południe przez parów, aż dotrzesz do Posterunku Krwawych Młotów. Zabij jak najwięcej ogrów Krwawych Młotów w okolicy.', 'Zabij 30 dowolnych ogrów Krwawych Młotów w Posterunku Krwawych Młotów.', '', 'Wróć do Tor\'chunka Dwuszpona w Warowni Władców Gromu w Górach Klingi.', 'Zabite ogry Krwawych Młotów', '', '', '', 0),
(10506, 'plPL', 'Sroga sytuacja', 'Wataha Hordy się przerzedziła, więc szukają nowych wilków. Niestety w pobliżu jest jeszcze jedno źródło.$B$BOgry Krwawych Młotów w parowie na wschodzie trzymają silną watahę jako własnych wartowników. Nie znosiłam wysyłać cię do zabijania wilków Władców Gromu, więc może tym razem zrobimy coś innego?$B$BZ pyłu, który sam opada ze skrzydeł naszych czarodziejskich smokowców, uzyskałam magiczny proszek. Posyp nim srogie wilki Krwawych Młotów, a Horda nie będzie ich chciała.', 'Użyj Proszku pomniejszającego Riny na 5 srogich wilkach Krwawych Młotów w Posterunku Krwawych Młotów i w Parowie Krwawych Młotów.', '', 'Wróć do Riny Księżycowe Źródło w Sylvanaar w Górach Klingi.', 'Osłabiony srogi wilk Krwawych Młotów', '', '', '', 0),
(10510, 'plPL', 'W głąb Kopalni Draenetystu', 'No, dobrze widzieć kogoś, kto chce tu pomóc!$B$BBorgrim i ja należymy do Ligi Odkrywców i przybyliśmy, by dowiedzieć się jak najwięcej o tych górach. Nasłuchaliśmy się przeróżnych opowieści i nie mogę się doczekać, aż się rozgościmy i zabierzemy do pracy.$B$BJedna rzecz szczególnie mnie zaciekawiła. Nocne elfy mówią o miejscu w parowie na wschodzie, zwanym Kopalnią Draenetystu. Leży na południowym krańcu Posterunku Krwawych Młotów. Chciałabym zdobyć trochę kryształów, które tam naturalnie rosną.', 'Zbierz 5 kryształów z Kopalni Draenetystu.', '', 'Wróć do Bronwyn Mocnomłot w Sylvanaar w Górach Klingi.', '', '', '', '', 0),
(10511, 'plPL', 'Dziwne piwo', 'Jeśli ten urlop ma się zacząć jak należy, potrzebuję więcej piwa. Niestety elfy nie mają pojęcia o szlachetnej sztuce fermentacji.$B$BPodsłuchałem, że ogry Krwawych Młotów w dole parowu mają go pod dostatkiem. Gotów jestem spróbować.$B$BZrobisz mi przysługę? Idź na południe przez Żywy Gaj, zejdź pochylnią na wschód do Posterunku Krwawych Młotów i zdobądź mi trochę. Słyszałem, że mają tam poustawiane wielkie beczki, a ich piwowarzy roznoszą piwo wszystkim innym ogrom.', 'Zbierz 11 butelek piwa „Zmora Osiłków” Krwawych Młotów.', '', 'Wróć do Borgrima Mocnomłota w Sylvanaar w Górach Klingi.', '', '', '', '', 0),
(10512, 'plPL', 'Upić Klan Ostrza', 'Nie wezmę już ani łyka tej cuchnącej brei! Ale podsunęła mi pewien pomysł.$B$B<W oczach Borgrima pojawiają się iskierki.>$B$BOto plan. Wiemy, że Krwawe Młoty praktycznie żyją tymi pomyjami. Ciekawe tylko, co myślą o nich ich wrogowie, ogry Klanu Ostrza?$B$B$N, weź resztę tego świństwa i spróbuj upić ogry Klanu Ostrza. Znajdziesz je, idąc od Posterunku Krwawych Młotów na północ przez parów.', 'Użyj Beczki „Zmory Osiłków” Krwawych Młotów, by spróbować upić 5 ogrów Klanu Ostrza.', '', 'Wróć do Borgrima Mocnomłota w Sylvanaar w Górach Klingi.', 'Upite ogry Klanu Ostrza', '', '', '', 0),
(10516, 'plPL', 'Rynsztunek obrończyni', 'Wiem, że to dziwne, ale chcę zostać w tej klatce. To doskonała okazja, by zrobić to, po co tu przybyłam: zebrać informacje o Klanie Ostrza.$B$BMogę odejść w każdej chwili, ale chciałabym odzyskać miecz i tarczę.$B$BMój rynsztunek mają dwaj ich przywódcy. Droggam ma mój miecz, a Mugdorg tarczę.$B$BJeśli trzeba, zdobądź piwo z Posterunku Krwawych Młotów na południu i użyj go, żeby przerzedzić ich pomocników i zwabić tych dwóch. Ale uważaj na trzeźwych strażników, którzy nie piją!', 'Zdobądź Ostrze obrończyni Vuuleen i Tarczę obrończyni Vuuleen.', '', 'Wróć do Obrończyni Vuuleen w Warowni Klanu Ostrza w Górach Klingi.', '', '', '', '', 0),
(10517, 'plPL', 'Gorr\'Dimie, wybiła twoja godzina...', 'Przywódca Warowni Klanu Ostrza nazywa się Gorr\'Dim. Wierz mi... to imię do niego pasuje.$B$BMimo to nie lekceważyłabym go. Jest na tyle sprytny, że wyniósł swój klan do rangi ulubieńców Gruula Smokobójcy, a teraz to oni panują nad tymi górami. Poza tym Gorr\'Dim zawsze ma przy sobie świtę, w tym obrońców zaprzysiężonych, że nie tkną piwa Krwawych Młotów.$B$BDla bezpieczeństwa Sylvanaar proszę cię, żebyś tam $gwrócił:wróciła; i się z nim $grozprawił:rozprawiła;.', 'Zabij Gorr\'Dima, przywódcę ogrów z Warowni Klanu Ostrza.', '', 'Wróć do Obrończyni Vuuleen w Warowni Klanu Ostrza w Górach Klingi.', '', '', '', '', 0),
(10518, 'plPL', 'Zatknięcie sztandaru', 'Ukradnij sztandar Klanu Ostrza jednemu z ich czempionów i zanieś go na południe, do Posterunku Krwawych Młotów. Zatknij go na szczycie ich Wieży Północnej Maczugi.$B$BTo rozwścieczy Krwawe Młoty i będą cię atakować bez wytchnienia. Ale dzięki temu ich nienawiść skupi się na Warowni Klanu Ostrza, a nie na Sylvanaar.$B$BBędziesz wiedzieć, że $gdopełniłeś:dopełniłaś; dzieła, gdy pokonasz Gurna Grubnosha i zabierzesz jego hełm. Przynieś go do Sylvanaar.$B$B$N, to nie będzie łatwe. Weź ze sobą przyjaciela albo dwóch.', 'Użyj sztandaru Klanu Ostrza na szczycie Wieży Północnej Maczugi, by zwabić Gurna Grubnosha. Zdobądź Sztandar Klanu Ostrza i Hełm Gurna Grubnosha.', '', 'Wróć do Dowódcy Niebocienia w Sylvanaar w Górach Klingi.', '', '', '', '', 0),
(10524, 'plPL', 'Artefakty klanu Władców Gromu', 'Znaki na artefakcie wskazują, że wykonali go orkowie z klanu Władców Gromu. Ci orkowie mieszkali niegdyś w Warowni Władców Gromu, zanim zmienili się w spaczone orki.$B$BPrzez pewien czas warownię zajmowały ogry Klanu Ostrza, dopóki niedawno nie wyparła ich Horda.$B$B$GSłyszałeś:Słyszałaś; o innych zaginionych artefaktach. Przychodzą ci na myśl bęben, strzała i tabliczka – wiesz, że ktoś ich szuka.$B$BZnajdź je w Warowni Klanu Ostrza i zanieś Rokgah Krwawy Chwyt.', 'Zdobądź Bęben klanu Władców Gromu, Strzałę klanu Władców Gromu i Tabliczkę klanu Władców Gromu.', '', 'Porozmawiaj z Rokgah Krwawy Chwyt w Warowni Władców Gromu w Górach Klingi.', '', '', '', '', 0),
(10525, 'plPL', 'Przewodnik wizji', 'Głupcze! Omal nie $gzniszczyłeś:zniszczyłaś; bębna!$B$BZbyt ciężko pracowałam, by tu dotrzeć, a dotąd wracałam z pustymi rękami. Przynajmniej tobie się udało tam, gdzie inni ponieśli porażkę albo coś gorszego.$B$BPora przywołać wizję, która zaprowadzi cię do ostatniej relikwii, której szukam.$B$BWeź ten ognisty fragment mojej duszy. Użyj go, by przemienić swoje ciało w płomień, a ducha w przewodnika wizji, który wystrzeli naprzód i wskaże, gdzie leży ostatnia relikwia Władców Gromu.', 'Użyj Ognistego fragmentu duszy, by przemienić swojego ducha w przewodnika wizji, który wskaże, gdzie leży ostatni artefakt Władców Gromu.', 'Odnaleziony ostatni artefakt Władców Gromu', 'Porozmawiaj z Rokgah Krwawy Chwyt w Warowni Władców Gromu w Górach Klingi.', '', '', '', '', 0),
(10526, 'plPL', 'Gromowa Włócznia', 'Jeśli wizja, którą ci dałam, jest prawdziwa, musisz zejść do parowu i udać się na południowy kraniec Parowu Krwawych Młotów. Tam znajdziesz Kopalnię Draenetystu.$B$BIdź w głąb kopalni i zdobądź Gromową Włócznię. Wszystko inne zignoruj! Nie interesują mnie kryształy z kopalni ani ogry, które w niej siedzą.$B$BGdy tylko zdobędziesz włócznię, przynieś mi ją tutaj!$B$BI, $N, obchodź się z nią bardzo ostrożnie... Wolę nie myśleć, co by cię spotkało, gdybyś ją $gzłamał:złamała;.', 'Zdobądź Gromową Włócznię.', '', 'Wróć do Rokgah Krwawy Chwyt w Warowni Władców Gromu w Górach Klingi.', '', '', '', '', 0),
(10542, 'plPL', 'Ukradli mi fajkę i moje piwo!', 'T\'chali był kiedyś całkiem przyjaznym trollem. Ja przyjść tu, żeby nauczyć Krwawe Młoty warzyć piwo. Ale jak tylko to zrobić, Krwawe Młoty zakopać T\'chalego i zostawić go tu, żeby zgnił!$B$BA najgorsze, że ukradli moja fajka!$B$BTo co, chcesz pomóc T\'chalemu? Przynieś mi fajkę z powrotem. T\'chali myśli, że ogry, które ją ukradły, poszły na południowy zachód, koło kopalni.$B$BA jak już tam będziesz, przynieś też trochę piwa!', 'Zdobądź Fajkę wodną T\'chalego i 10 butelek piwa „Zmora Osiłków” Krwawych Młotów.', '', 'Wróć do T\'chalego Znachora w Parowie Krwawych Młotów w Górach Klingi.', '', '', '', '', 0),
(10543, 'plPL', 'Grimnoku i Korgaahu, idę po was!', 'T\'chali czekał na swoją zemstę!$B$BTego dnia, co zakopać T\'chalego i zostawić go na śmierć, prowadził ich Grimnok Zrodzony w Boju. A następnego dnia Korgaah przyjść na południe, żeby grabić i kopnąć T\'chalego w głowę.$B$BChcę ich śmierci!$B$BGrimnoka znajdziesz na szczycie Wieży Południowej Maczugi w Posterunku Krwawych Młotów. Korgaaha znajdziesz na górze budynku w północnej części Warowni Klanu Ostrza. Korgaah ma trzeźwych obrońców, więc użyj piwa, żeby go od nich odciągnąć, bo oni nie pić.', 'Zabij Grimnoka Zrodzonego w Boju i Korgaaha.', '', 'Wróć do T\'chalego Znachora w Parowie Krwawych Młotów w Górach Klingi.', '', '', '', '', 0),
(10544, 'plPL', 'Klątwa na oba wasze klany!', 'T\'chali chce zemsty na wszystkich ograch!$B$BZa życia T\'chali był potężnym znachorem. Jak sięgniesz do mojego grobu, znajdziesz paskudnie mocny fetysz.$B$BUwolnij magię fetysza przy wejściach do budynków i wież w Warowni Klanu Ostrza i w Posterunku Krwawych Młotów. Twoje voodoo przywoła złego ducha, którego musisz pokonać. To z kolei przeklnie budynek.$B$BUważaj, jak spróbujesz przekląć budynek, który już jest przeklęty, przywołasz kolejnego przeklętego ducha!', 'Użyj Paskudnie mocnego fetysza, by przekląć 5 budynków lub wież w Warowni Klanu Ostrza i 2 w Posterunku Krwawych Młotów.', '', 'Wróć do T\'chalego Znachora w Parowie Krwawych Młotów w Górach Klingi.', 'Przeklęty budynek w Warowni Klanu Ostrza', 'Przeklęty budynek w Posterunku Krwawych Młotów', '', '', 0),
(10545, 'plPL', 'Popijawa w Klanie Ostrza', 'Jak T\'chali mówił, pomógł swoim przyjaciołom z Krwawych Młotów zrobić ich piwo. Ale T\'chali nie powiedział, po co.$B$BKrwawe Młoty są w ciężkich tarapatach. Klan Ostrza ich miażdży, a oni potrzebowali nowej broni do tej walki.$B$BI wtedy T\'chali wpadł na świetny pomysł. Czemu nie zrobić idealnego piwa, co wzmacnia ciebie i osłabia wroga? Tylko że T\'chali nie wie, czy to działa.$B$BTo ty zaniesiesz to piwo do Warowni Klanu Ostrza i sprawdzisz, czy działa!', 'Użyj Beczki „Zmory Osiłków” Krwawych Młotów, by upić 5 ogrów Klanu Ostrza.', '', 'Wróć do T\'chalego Znachora w Parowie Krwawych Młotów w Górach Klingi.', 'Upite ogry Klanu Ostrza', '', '', '', 0),
(10555, 'plPL', 'Złe samopoczucie', 'Magia, którą uprawiają arakkoa Lashh\'an, jest nienaturalna. Wyrywają sobie garściami – szponami? – własne pióra jako odczynniki!$b$bNie brzmi mi to na dobrą magię. Przybyłam tu, by dowiedzieć się więcej o ich zaklęciach. Niestety podejście bliżej to dla mnie za dużo.$b$bTobie mogłoby się udać: rzuć jedno z ich zaklęć na siebie, a potem wróć do mnie. Musisz znaleźć jedną z ich ksiąg zaklęć, wysoko w koronach drzew Zasłony Lashh.$b$bA jeśli nie wyrosły ci pióra, których nie widzę, będziesz też potrzebować trochę ich piór.$B', 'Zbierz 18 wyskubanych piór Lashh\'an.', '', 'Otwórz Księgę Lashh\'an w Zasłonie Lashh w Górach Klingi.', '', '', '', '', 0),
(10556, 'plPL', 'Bazgroły', 'Piktogramy pokazują, że zaklęcie rzuca się przy użyciu piór w jednym z kręgów mocy w Zasłonie Lashh.$b$bZagmatwane rysunki zdają się przedstawiać arakkoa, którego przenika duch kaliri.', 'Użyj Garści piór na Kręgu zaklęć Lashh\'an.', '', 'Wróć do Daranelle w Sylvanaar w Górach Klingi.', 'Daj Daranelle zbadać aurę kaliri', '', '', '', 0),
(10557, 'plPL', 'Lot próbny: Kondensatorium zefirium', 'Zbudowałem niesamowite urządzenie, Kondensatorium zefirium, i jestem pewien, że będzie działać bez zarzutu, ale... chcesz mi pomóc je przetestować?$B$BDodatek za pracę w niebezpiecznych warunkach jest spory!$B$BPorozmawiaj z moim bratem bliźniakiem, Rallym, o tam. Powodzenia, $N. Wróć po eksperymencie. A jeśli nie będzie to możliwe z powodu odniesionych obrażeń, po zapłatę może się zgłosić twoja najbliższa rodzina.', 'Porozmawiaj z Rallym Łapiprądem i użyj Kondensatorium zefirium.', 'Przetestuj eksperyment Tally\'ego', 'Wróć do Tally\'ego Łapiprąda w Stacji Toshleya w Górach Klingi.', '', '', '', '', 0),
(10565, 'plPL', 'Kamienie Vekh\'nir', 'Arakkoa Vekh\'nir od wielu lat są dla nas cierniem w boku. Kieruje nimi jakaś dziwna religia, która wprawia ich w gorączkowe działanie. Noszą teraz przy sobie kryształy, które obrócili ku jakiemuś mrocznemu celowi.$b$bWiem to i owo o ich rytuałach. Zanoszą kryształy do swoich kręgów zaklęć, by je nasycić. My w wiosce chcielibyśmy dowiedzieć się więcej. Zaczaj się na kilku arakkoa, aż znajdziesz kryształ, naładuj go, a potem mi go przynieś.', 'Zdobądź Kryształ Vekh\'nir i użyj go w Kręgu zaklęć Vekh\'nir, by uzyskać Naładowany kryształ Vekh\'nir.', '', 'Wróć do Dertroka w Wiosce Mok\'Nathal w Górach Klingi.', '', '', '', '', 0),
(10566, 'plPL', 'Metodą prób i błędów', 'Zrobiłem cztery różdżki, które, jak sądzę, wzmocnią moc kryształów arakkoa. Zanieś je na Działkę Trogmy i wypróbuj na niewolnikach ogrów.$b$bBędziesz potrzebować nasyconego kryształu, który zdobędziesz od arakkoa z okolicy.$b$bGdy ustalisz, która jest najlepsza, wróć do mnie.', 'Wypróbuj każdą z różdżek Dertroka na ogrzym niewolniku arakkoa. Do użycia każdej różdżki potrzebny jest Nasycony kryształ Vekh\'nir.', '', 'Wróć do Dertroka w Wiosce Mok\'Nathal w Górach Klingi.', 'Wypróbuj pierwszą różdżkę', 'Wypróbuj drugą różdżkę', 'Wypróbuj trzecią różdżkę', 'Wypróbuj czwartą różdżkę', 0),
(10567, 'plPL', 'Wykonanie wisioru', 'Arakkoa z Puszczy Ruuan wynoszą spośród swojego stada Zwiastunów Kruka, heroldów swojego boga.$b$bWierzą, że Zwiastuni czuwają nad nimi z nieba, gdzie otrzymują nauki Kruka, i zstępują, by przekazać to przesłanie dalej.$b$bZwiastuni mają ogromną władzę nad duszami arakkoa. Używają magicznych wisiorów, których potrzebujemy.$b$bZwab jednego ze Zwiastunów, zabijając jego stado i zabierając ich szpony. Połóż szpony na ołtarzu, żeby zwrócić jego uwagę.', 'Zbierz 6 szponów Ruuan\'ok i użyj ich w Kręgu wyroczni Ruuan\'ok, by przyzwać Zwiastuna Kruka. Zabij go i zdobądź jego Wisior zwiastuna.', '', 'Wróć do Timeona w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10580, 'plPL', 'Gdzie się podziały te przeklęte gnomy?', 'Mimo wszystkiego dobrego, co tu zdziałaliśmy, jednej rzeczy żałuję: że przegoniliśmy Toshleya i jego gnomich przyjaciół.$B$BNie mieliśmy wyboru – swoją techniką i eksperymentami rujnowali naszą pracę w gaju.$B$BByłbym wdzięczny, gdybyś $gsprawdził:sprawdziła;, co się z nimi stało. Ostatnio słyszeliśmy, że ruszyli przez most na wschód. Jestem pewien, że musieli skręcić na południe, z dala od Warowni Władców Gromu.$B$BPoszukaj wskazówek, gdzie się podziali, w południowej części Poszarpanej Grani.', 'Przeszukaj południową część Poszarpanej Grani w Górach Klingi w poszukiwaniu wskazówek, gdzie podziali się Toshley i pozostałe gnomy.', '', '', '', '', '', '', 0),
(10581, 'plPL', 'Śladem okruszków', 'DOBRZE, NINIEJSZYM OSTRZEGAM CIĘ, ŻE NA GRANI NIC NIE ZNAJDZIESZ.$B$BNIE IDŹ ŚLADEM CZĘŚCI ZAMIENNYCH, KTÓRY PROWADZI DO STACJI TOSHLEYA! NIE ZNAJDZIESZ TAM TOSHLEYA ANI ŻADNEGO INNEGO GNOMA.', 'Idź śladem części zamiennych w górę pochylni na Brzytwową Grań. Porozmawiaj z Toshleyem w Stacji Toshleya w Górach Klingi.', '', '', '', '', '', '', 0),
(10584, 'plPL', 'Zbieranie przetworników mocy', 'Te tępe ogry z Posterunku Klanu Ostrza na północy podkradają nam przetworniki mocy! A ty mi je odzyskasz, w pewnym sensie.$B$BOgry na pewno uszkodziły przetworniki tymi swoimi wielkimi, niezdarnymi łapskami. Chcę więc, żebyś $guwolnił:uwolniła; z nich energię, a potem $gzamknął:zamknęła; powstałego elektromentala za pomocą tego protowoltaicznego kolektora magnetycznego.$B$BPewnie będzie na ciebie wściekły, więc trzeba go będzie „zabić”, póki jest zamknięty w sferze magnetycznej.', 'Użyj Protowoltaicznego kolektora magnetycznego, by zebrać 5 elektromentali.', '', 'Wróć do Toshleya w Stacji Toshleya w Górach Klingi.', 'Zebrane elektromentale', '', '', '', 0),
(10594, 'plPL', 'Pomiar częstotliwości rezonansowej', 'Zanieś te skanery na Śpiewającą Grań. Rozłóż je na ziemi według wzoru, a utworzą nakładające się pola, które odczytają amplitudę kryształów. Stań między nimi tak, żeby znaleźć się w pięciu polach oscylacji, a będę mieć potrzebne informacje!$B$BTwoje skanery zadziałają nawet z tymi, które rozłożą inni.$B$BA, i pewnie otworzy się szczelina! Nie mam pojęcia, co z niej wyjdzie, jeśli w ogóle coś, ale przygotuj się na najgorsze.', 'Rozmieść Oscylujące skanery częstotliwości tak, by stojąc między nimi, znaleźć się w 5 nakładających się polach oscylacji.', 'Zmierzona częstotliwość rezonansowa śpiewającego kryształu', 'Wróć do Nickwinkle\'a Metrognoma w Stacji Toshleya w Górach Klingi.', '', '', '', '', 0),
(10607, 'plPL', 'Szepty Boga Kruków', 'W Grishnath totemy pozostawione przez Wyrocznie Kruka pozwalają arakkoa słyszeć Słowo Kruka. Niestety język arakkoa jest dla nas niezrozumiały.$b$bDzięki wisiorowi Zwiastuna możemy go zrozumieć. Będziesz w stanie przejmować dusze arakkoa, by pojąć ich język. Gdy przenika cię duch arakkoa, możesz odwiedzić totemy i zrozumieć ich przesłanie.$b$bDowiedz się tego dla nas, $n.', 'Zabijaj arakkoa Grishna, by na 2 minuty uzyskać Rozumienie mowy kruków. Pod wpływem tego zaklęcia możesz odnaleźć cztery kapliczki i otrzymać od nich przepowiednię.', '', 'Wróć do Timeona w Wiecznym Gaju w Górach Klingi.', 'Otrzymaj Pierwszą przepowiednię', 'Otrzymaj Drugą przepowiednię', 'Otrzymaj Trzecią przepowiednię', 'Otrzymaj Czwartą przepowiednię', 0),
(10608, 'plPL', 'Kryształowo czysto', 'Te przeklęte skalne oprawce nie dają mi prowadzić badań w dole, na Śpiewającej Grani! Rozkopują tamtejsze kryształy, a każde ich zadrapanie niweczy moje szanse na zbadanie harmonii śpiewających kryształów.$B$BWyglądasz na kogoś, kto może mi pomóc rozwiązać ten problem. Idź na południe i oczyść teren z tych kryształowych oprawców.', 'Zabij 10 kryształowych oprawców.', '', 'Wróć do Nickwinkle\'a Metrognoma w Stacji Toshleya w Górach Klingi.', '', '', '', '', 0),
(10609, 'plPL', 'Co było pierwsze: smokowiec czy jajo?', 'Badam, jak esencje smokowców mogą się przydać w mojej pracy lekarza. Myślę, że mogą być panaceum na mnóstwo przypadłości!$B$BPotrzebuję kogoś, kto pójdzie na południe, na Śpiewającą Grań, i mi ich trochę przyniesie.$B$BZechcesz wziąć mój czasowy modulator fazy i użyć go na pisklętach Otchłani, które wylęgają się z jaj smokowców Otchłani? Zdobądź esencje z tego, w co się zmienią.$B$BA w co się zmienią, tego, dodam, nie jestem pewien, bo używamy tu dość ryzykownej techniki modyfikującej czas i przestrzeń.', 'Zbierz 3 esencje protosmokowca Otchłani, 3 esencje młodocianego smokowca i 3 esencje dorosłego smokowca.', '', 'Wróć do Fizita „Doktorka” Tykozegara w Stacji Toshleya w Górach Klingi.', '', '', '', '', 0),
(10614, 'plPL', 'Szepty na wietrze', 'Ścigałem pogłoski o Mok\'Nathalach po całej Rubieży i nic z tego nie miałem. Wreszcie chyba znaleźliśmy ich dom.$b$bAle teraz, gdy ta chwila nadeszła, ogarnia mnie niepokój. Niepokój, który podczas poszukiwań nie dawał mi spać do późnej nocy. Czy mnie przyjmą?$b$bZnam... imię ich przywódcy: Leoroxx. Odszukaj go. Musisz być w tej sprawie moimi oczami.', 'Porozmawiaj z Leoroxxem w Wiosce Mok\'Nathal w Górach Klingi.', '', '', '', '', '', '', 0),
(10615, 'plPL', 'Puszcza Ruuan', 'Informacje o naturze tutejszych arakkoa, które $gpomogłeś:pomogłaś; mi odkryć, bardzo zainteresują kogoś innego.$b$bOdwiedzili nas członkowie Ekspedycji Cenariońskiej, których także zaniepokoiły zamiary arakkoa tu, w Górach Klingi.$b$bOdszukaj go. Nazywa się Timeon, znajdziesz go w Wiecznym Gaju w Puszczy Ruuan. Idź stąd drogą na zachód, potem na północ, gdzie droga rozwidla się na Brzytwowej Grani. Na koniec, gdy droga rozdzieli się w Wąwozie Ostrzy, skręć na zachód.', 'Porozmawiaj z Timeonem w Wiecznym Gaju w Puszczy Ruuan w Górach Klingi.', '', '', '', '', '', '', 0),
(10617, 'plPL', 'Kokony jedwabnoskrzydłych', 'Jedwab z kokonów jedwabnoskrzydłych przydaje się w wiosce do wszelkiego rodzaju rzeczy. Nigdy nie możemy go zdobyć dość i zawsze go brakuje.$b$bTrudno pozyskać kokony z larw, gdy te zaczną przeobrażenie.$b$bNasi wojownicy są zajęci odpieraniem ataku na wioskę. Gdybyś $gzebrał:zebrała; je dla nas, bardzo by nam to pomogło.', 'Zbierz 8 kokonów jedwabnoskrzydłych z larw jedwabnoskrzydłych.$b$bZabijaj larwy szybko, bo inaczej zmienią się w jedwabnoskrzydłe i zniszczą swoje kokony.', '', 'Wróć do Taereka w Wiosce Mok\'Nathal w Górach Klingi.', '', '', '', '', 0),
(10618, 'plPL', 'Najdelikatniejsze skrzydła', 'Polowanie na larwy jedwabnoskrzydłych to trudne wyzwanie dla naszych młodych wojowników, ale na szczęście, nawet jeśli nie zdołają pozyskać kokonu z larwy, wciąż możemy wykorzystać skrzydła wyklutych jedwabnoskrzydłych.$b$bSkrzydeł używamy nawet do dużo większej liczby rzeczy niż kokonów i nigdy nie mamy ich za dużo.$b$bJeśli będziesz w okolicy, bardzo byś mi $gpomógł:pomogła;, przynosząc kilka.', 'Zbierz 12 opalizujących skrzydeł.', '', 'Wróć do Silmary w Wiosce Mok\'Nathal w Górach Klingi.', '', '', '', '', 0),
(10620, 'plPL', 'Kolcogrzbiete zagrożenie', 'Zatrudniliśmy się do pomocy Toshleyowi, kiedy postanowił przenieść się do Rubieży, i od tamtej pory ciągle jesteśmy w drodze.$B$BTeraz wygląda na to, że wreszcie zapuściliśmy korzenie. Wszyscy szaleni naukowcy mają swoje projekty, a my, Zawadiacy, jesteśmy tu po to, żeby ich chronić.$B$BPotrzebujemy teraz, żebyś $gposzedł:poszła; na północ, na Brzytwową Grań, albo na wschód, na Półkę Łuskoskrzydłych, i $goczyścił:oczyściła; je, zabijając tropicieli. To skryte pająki, które żyją wśród skalnych występów i skaczą na niczego niepodejrzewających przechodniów.', 'Zabij 10 kolcogrzbietych tropicieli.', '', 'Wróć do Oszołomionej Diny w Stacji Toshleya w Górach Klingi.', '', '', '', '', 0),
(10632, 'plPL', 'Ząbkowanie', 'Miło, że pomagasz Toshleyowi i jego naukowcom. Ja jednak nie mogę sobie pozwolić na luksus zajmowania się „prywatnymi” zainteresowaniami.$B$BJeśli chcesz coś tu zmienić, zrobisz to, o co cię proszę, a teraz potrzebuję broni.$B$BNasze strzelby są skuteczne na odległość, ale gdy robale podejdą blisko, potrzebujemy mocnej broni do walki wręcz na zapas.$B$BZęby sztyletopaszczy biczoogonów z północnej części Brzytwowej Grani świetnie nadają się na ostrza wibrobroni. Załatw mi trochę.', 'Zbierz 5 wyjątkowo ostrych zębów sztyletopaszczy.', '', 'Wróć do Razaka Żelaznobokiego w Stacji Toshleya w Górach Klingi.', '', '', '', '', 0),
(10657, 'plPL', 'Jazda na błyskawicy', 'Nie zmieściliśmy się w budżecie na zasilanie Kondensatorium zefirium. Ale przyszło mi do głowy, że węże z Półki Łuskoskrzydłych na wschodzie zieją błyskawicami i mają gruczoły, które możemy wykorzystać.$B$BPrzebiegunowałem kolektor magnetyczny tak, żeby pochłaniał uderzenia piorunów. Chcę, żebyś $gposzedł:poszła; tam, $gaktywował:aktywowała; go na sobie i $gzdobył:zdobyła; dla nas od tych węży trochę taniego paliwa.', 'Użyj Przebiegunowanej sfery magnetycznej, by pochłonąć 25 uderzeń piorunów łuskoskrzydłych węży. Zbierz też 5 gruczołów błyskawic łuskoskrzydłych.', '', 'Wróć do Toshleya w Stacji Toshleya w Górach Klingi.', 'Pochłonięte uderzenia piorunów', '', '', '', 0),
(10671, 'plPL', 'Więcej niż funt ciała', '$N, mam dla ciebie kolejne zadanie. Jeden z jajogłowych chce zbadać diablęce bestie z mięsa, które można znaleźć przy Przystani Razaana, na północ od Brzytwowej Grani.$B$BŚciślej mówiąc, chce zbadać mięso tych bestii z mięsa.$B$B<Dizzy robi zdegustowaną minę.>$B$BAle oczywiście nie chcą sobie brudzić rąk, a do tego interesuje ich tylko mięso nasycone eterem, którego pewnie nie mają wszystkie.$B$BJa tam mówię, że żebrak nie wybiera, ale co zrobić?', 'Zbierz 5 kawałków mięsa nasyconego eterem.', '', 'Wróć do Oszołomionej Diny w Stacji Toshleya w Górach Klingi.', '', '', '', '', 0),
(10674, 'plPL', 'Pułapka na świetlne pląsy', 'Eteryczni Razaani na Przystani Razaana na północy bawią się jakąś ciekawą techniką.$B$BNa pewno nie będą mieli nic przeciwko, jeśli użyjesz tej pułapki, żeby pobrać kilka próbek ich małych, różowych, unoszących się kul świetlnych? Pewnie są tylko dla ozdoby.$B$BPułapka ma tę szczególną właściwość, że po otwarciu powinna przyciągnąć do siebie jedną z unoszących się kul. Oczywiście pewnie przy okazji zaalarmuje Razaani, że tam jesteś.', 'Użyj Pułapki świetlnej, by złapać 15 świetlnych kul Razaani.', '', 'Wróć do Toshleya w Stacji Toshleya w Górach Klingi.', 'Złapane świetlne kule Razaani', '', '', '', 0),
(10675, 'plPL', 'Bez gnomiej litości!', '<Toshley blednie jak ściana.>$B$BTe kule składają się z energii Otchłani i z dusz, a niektóre z nich to dusze gnomów!$B$BJak oni śmią! Czy to oni zabijali naszych, którzy wyruszali na północ?!$B$B$N, musisz to powstrzymać, a jedynym sposobem jest wykończenie ich przywódcy, księcia Nexusa Razaana.$B$BMusisz go jednak wywabić z kryjówki. Zgaduję, że zrobisz to, zabijając wielu jego eterycznych Razaani.$B$BPrzynieś mi zbiór dusz, który z pewnością ma przy sobie.', 'Zdobądź Zbiór dusz.', '', 'Wróć do Toshleya w Stacji Toshleya w Górach Klingi.', '', '', '', '', 0),
(10682, 'plPL', 'Czas na negocjacje...', 'Kiedy przybyliśmy do Puszczy Ruuan, kultyści Żmija trzymali się Sabatu Czarnoskrzydłych, za tunelem na zachodzie. Ale teraz podchodzą coraz bliżej nas.$B$BMusisz znaleźć nadzorcę kultystów Żmija. Wiadomo, że regularnie patroluje drogę między ich obozami w Puszczy Ruuan.$B$BWynegocjuj coś z nim. Daj mu znać, że jest miejsce na kompromis, ale nie pozwolimy na wybijanie całej zwierzyny ani na wycinkę wszystkich drzew.', 'Negocjuj z Nadzorcą Nuaarem.', 'Zakończone negocjacje z Nadzorcą Nuaarem', 'Wróć do Strażnika drzew Chawna w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10690, 'plPL', 'Matka legowiska', 'POSZUKIWANA!$B$BRema, matka legowiska i główna obrończyni Poszarpanej Grani na południe od Warowni Władców Gromu.$B$BAby ją znaleźć, wyjdź z miasta na wschód i przejdź przez most nad Parowem Krwawych Młotów. Ukrywa się w tunelu na południowym skraju grani.$B$BWieść o jej śmierci zanieś Dowódcy Niebocieniowi w Sylvanaar.', 'Zabij Remę.', '', 'Wróć do Dowódcy Niebocienia w Sylvanaar w Górach Klingi.', '', '', '', '', 0),
(10709, 'plPL', 'Spotkanie po latach', 'A więc przybywasz ze świata po drugiej stronie Portalu? I znasz Rexxara. O tak, znam go bardzo dobrze.$b$bWidzisz, to mój syn.$b$bAle dokonał wyboru całe życie temu. Nie jest jednym z nas i nie jest tu mile widziany. Mamy dość kłopotów z ogrami Krwawych Młotów.$b$bWiedz jedno: kto urodził się mieszańcem, nie staje się przez to Mok\'Nathalem.', 'Porozmawiaj z Rexxarem w Warowni Władców Gromu w Górach Klingi.', '', '', '', '', '', '', 0),
(10710, 'plPL', 'Lot próbny: Śpiewająca Grań', 'Pomajstrowałem przy Kondensatorium zefirium i jestem gotów na kolejny test! Chcesz pomóc?$B$BTen lot powinien być krótki, ale szybki!$B$BEee... i choć jestem pewien, że nie ma żadnego niebezpieczeństwa... mam tu, eee, zrzeczenie, które chciałbym, żebyś $gpodpisał:podpisała;. To tylko formalność, zapewniam!$B$BPowodzenia! Porozmawiaj z Rallym, żeby cię wystrzelił, i wróć do mnie, gdy eksperyment się skończy!', 'Podpisz Zrzeczenie Tally\'ego, a potem porozmawiaj z Rallym Łapiprądem, by użyć Kondensatorium zefirium.', 'Rzuć ostrożność na wiatr.', 'Wróć do Tally\'ego Łapiprąda w Stacji Toshleya w Górach Klingi.', '', '', '', '', 0),
(10711, 'plPL', 'Lot próbny: Przystań Razaana', '$n, podniosłem wydajność Kondensatorium zefirium o 30 procent. Wyniesie obiekt doświadczalny o twojej wadze i współczynniku oporu powietrza na nowe wyżyny! Chcesz sprawdzić moją teorię? Ten eksperyment powinien wysłać cię w okolice Przystani Razaana.$B$BPorozmawiaj z Rallym... przygotuje cię do startu.', 'Porozmawiaj z Rallym Łapiprądem, by użyć Kondensatorium zefirium.', 'Sięgnij granic nieba.', 'Wróć do Tally\'ego Łapiprąda w Stacji Toshleya w Górach Klingi.', '', '', '', '', 0),
(10712, 'plPL', 'Lot próbny: Puszcza Ruuan', 'Hej, $N. Dobrze, że cię złapałem! Mam bardzo ważną misję!$B$BOto wiatrowskaz Otchłani. Musisz zrobić dla mnie kilka odczytów w locie i dostarczyć je mojemu kuzynowi w Puszczy Ruuan.$B$BPorozmawiaj z Rallym i poleć Kondensatorium zefirium do Puszczy Ruuan. W trakcie lotu zakręć wiatrowskazem!$B$BPo wylądowaniu zanieś wirujący wiatrowskaz O\'Mally\'emu Łapiprądowi.$B$BPowodzenia, $n. I nie zwlekaj!', 'Porozmawiaj z Rallym Łapiprądem, by użyć Kondensatorium zefirium. W trakcie lotu do Puszczy Ruuan zakręć Wiatrowskazem Otchłani. Dostarcz Wirujący wiatrowskaz Otchłani O\'Mally\'emu Łapiprądowi w Wiecznym Gaju.', 'Wystrzel się do Puszczy Ruuan.', 'Porozmawiaj z O\'Mallym Łapiprądem w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10713, 'plPL', '...i czas na działanie', 'Nie będziemy biernie patrzeć, jak dziesiątkują wokół nas Puszczę Ruuan. Przede wszystkim musimy zadbać o drzewa.$B$BChcę, żebyś $gwrócił:wróciła; do Puszczy i $gprzekazał:przekazała; im od nas zupełnie inną wiadomość. Zabij każdego ich rębacza, na którego się natkniesz!$B$BSkoro nie chcą słuchać głosu rozsądku, może posłuchają bardziej stanowczej metody perswazji!', 'Zabij 10 rębaczy Kultu Żmija.', '', 'Wróć do Strażnika drzew Chawna w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10714, 'plPL', 'Na skrzydłach Ducha', 'Jeśli Mok\'Nathalów dręczą ogry Krwawych Młotów, powstrzymam je i ich popleczników. Ogry to proste stworzenia i niewiele by zyskały na nękaniu Mok\'Nathalów.$b$bMusi się za tym kryć coś więcej. $n, weź Ducha, mojego jastrzębia, i podsłuchaj rozmowy przywódców Krwawych Młotów. On może przejść niezauważony tam, gdzie my nie możemy.', 'Znajdź rozmawiających ze sobą Poganiacza Krwawych Młotów i Wróżbitę Krwawych Młotów, a potem użyj Gwizdka Rexxara, by przywołać Ducha i ich podsłuchać.', '', 'Wróć do Rexxara w Warowni Władców Gromu w Górach Klingi.', 'Podsłuchaj plany ogrów Krwawych Młotów', '', '', '', 0),
(10715, 'plPL', 'W głąb Wąwozu Wirów', 'A więc twój Rexxar chce, żebym przygotował dla niego truciznę? Dam mu to, czego pragnie, ale za swoją cenę. Nawet przyjaciele muszą płacić. Rzeczy za darmo niszczą przyjaźnie.$B$BNajpierw musisz się wybrać kawałek na południowy zachód, do Wąwozu Wirów.$B$BKłębią się tam jedne z najbardziej jadowitych stworzeń w całej Rubieży, a może i gdziekolwiek. Mówię o kruszycielach skorupy, a do tej trucizny musisz zebrać dla mnie ich gruczoły.', 'Zbierz 7 gruczołów jadowych kruszycieli skorupy.', '', 'Wróć do Barona Sablemane\'a w Krwawym Kręgu w Górach Klingi.', '', '', '', '', 0),
(10716, 'plPL', 'Lot próbny: Kruczy Las <brak nagrody>', 'Kondensatorium zefirium jest gotowe do najdłuższego startu w historii! Co ty na to, $N? Chcesz polecieć jeszcze raz?$B$BPodkręcałem układ napędowy, ale dopóki nie dopracuję wszystkich zmiennych, kondensatorium będzie potrzebować dodatkowego paliwa, żeby dostać odpowiedniego kopa! Przed lotem porozmawiaj z Rallym – on zna szczegóły.$B$BPowodzenia, $N. Ten lot zabierze cię do odległego Kruczego Lasu. Jeśli przeżyjesz lot – i tamtejsze ogry oraz arakkoa – wróć, to będziemy świętować!', 'Porozmawiaj z Rallym Łapiprądem, by użyć Kondensatorium zefirium. Wróć do Tally\'ego Łapiprąda w Stacji Toshleya.', 'Rzuć się w wir niebezpieczeństwa.', 'Wróć do Tally\'ego Łapiprąda w Stacji Toshleya w Górach Klingi.', '', '', '', '', 0),
(10717, 'plPL', 'Kłusownicy okradzeni', 'Wybacz, ale mimowolnie podsłuchałam twoją rozmowę z Chawnem. Chętnie pomogę.$B$BBadam Sabat Czarnoskrzydłych i pomagam druidom w kontaktach z nim.$B$BBardzo chciałabym zdobyć kilka ich smoczych piskląt. Gdybyśmy zrozumieli to, co czczą, łatwiej ocenilibyśmy, z czym dokładnie mamy do czynienia.$B$BAle najpierw musimy zdobyć trochę sieci. Zauważyłam, że kłusownicy Kultu Żmija w Puszczy Ruuan mają ich pod dostatkiem.', 'Zbierz 5 sieci Kultu Żmija.', '', 'Wróć do Samii Inkling w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10718, 'plPL', 'Duchy mają głos', '$N, skoro mnie widzisz, musisz coś przekazać Rexxarowi. Wiem, że szuka swojego ludu, i wiem, gdzie on jest.$B$BMok\'Nathalowie, bo tak się ich nazywa, mają wioskę na wschodzie, za Brzytwową Granią.$B$BIdź i przekaż Rexxarowi tę wiadomość. Jego lud jest w niebezpieczeństwie, a wiem, że zechce mu pomóc.', 'Porozmawiaj z Rexxarem w Warowni Władców Gromu w Górach Klingi.', '', '', '', '', '', '', 0),
(10719, 'plPL', 'Doszła do ciebie notatka?', 'Kultysta upuścił tę notatkę, która najwyraźniej miała trafić do Nadzorcy Nuaara. Podpisał ją ktoś o imieniu Kolphis Mroczna Łuska.$B$BStrażnik drzew Chawn zapewne chętnie się jej przyjrzy.', 'Dostarcz Notatkę ze spotkania Strażnikowi drzew Chawnowi w Wiecznym Gaju w Górach Klingi.', '', '', '', '', '', '', 0),
(10720, 'plPL', 'Najmniejsze stworzenia', 'Ogry, choć prostackie, zauważyłyby, że rozsiewasz tę truciznę po ich obozie. Dlatego nauczę cię, jak zjednać sobie do tego zadania pomoc jednego z najmniejszych stworzeń natury.$b$bGdy wybijesz na tym bębnie prosty rytm, skłonisz świstaka, by wykonywał twoje polecenia.$b$bW pobliżu Obozu Krwawych Młotów jest nora świstaków – na północy, w dole Kanionu Sztyletopaszczy, za Krwawym Kręgiem.$B$BGdy świstak już ci pomoże, użyj go, by zatruć beczki Krwawych Młotów.', 'Użyj Bębna ze skóry kodo przy Norze świstaków. Kierując świstakiem, zatruj trzy beczki w Obozie Krwawych Młotów.', '', 'Wróć do Rexxara w Warowni Władców Gromu w Górach Klingi.', 'Zatruj beczkę grogu „Zielona Plamka”', 'Zatruj beczkę dojrzałego bimbru', 'Zatruj beczkę sfermentowanego piwa z nasion', '', 0),
(10721, 'plPL', 'Dzika zabawa dla Grulloca', '$N, mam oswojonego dzika imieniem Huffer. Chce ci pomóc trochę się zabawić z jednym z pobliskich synów Gruula.$B$BGrulloc mieszka w miejscu zwanym Przeklętą Kotliną. Gdy tam dotrzesz, wypuść Huffera. Gronn będzie miał świetną zabawę, uganiając się za nim, a ty zabierzesz wór, którego pilnuje, i dostarczysz go Baronowi Sablemane\'owi.$B$BAby dotrzeć do Przeklętej Kotliny, zejdź północną pochylnią i idź na wschód przez Kres Smoków. Kotlina leży na wschodnim skraju.', 'Zdobądź Wór Grulloca.', '', 'Wróć do Barona Sablemane\'a w Krwawym Kręgu w Górach Klingi.', '', '', '', '', 0),
(10722, 'plPL', 'Spotkanie w Sabacie Czarnoskrzydłych', 'Wiem, co trzeba zrobić! $N, musisz podszyć się pod Nadzorcę Nuaara i pójść na to spotkanie!$B$BWszyscy kultyści Żmija w sabacie noszą jednakowe stroje, więc zbierz od nich skrawki, a gdy będziesz mieć ich dość, zrób z nich przebranie.$B$BPodszyj się pod Nadzorcę Nuaara i porozmawiaj z Kolphisem Mroczną Łuską, żeby usłyszeć, co ma do powiedzenia, a potem wróć do Strażnika drzew Chawna.$B$BDo sabatu dotrzesz, przechodząc przez Tunel Czaszki Żmija i idąc ścieżką obok Kruczego Lasu i Grishnath aż do samego końca.', 'Zbierz od kultystów Żmija dość Skrawków przebrania, by zrobić Przebranie nadzorcy. W przebraniu weź udział w spotkaniu z Kolphisem Mroczną Łuską.', 'Udział w spotkaniu z Kolphisem Mroczną Łuską', 'Wróć do Strażnika drzew Chawna w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10723, 'plPL', 'Gorgrom Smokożerca', 'Gronn, którego szukamy, to Gorgrom Smokożerca. Z pułapką Sablemane\'a szybko się z nim uporasz. Znajdziesz go, gdy będzie przyjmował ofiary od ogrów z Boulder\'mok.$b$bIdź drogą na północ od Krwawego Kręgu, a potem na zachód przy Puszczy Ruuan. Przejdź tunelem na północny zachód.$b$bNajpierw zabij ogry dla ich głów. Wyślemy wiadomość. Zastaw pułapkę przy jego ołtarzu. Gdy zginie, postaw obok niego makabryczne totemy – nikt nie pomyli się co do tej wiadomości.$b$bWeź niedźwiedzicę.$b$b<Misha warczy.>', 'Zdobądź 3 Makabryczne totemy od ogrów z Boulder\'mok. Następnie użyj Pułapki Sablemane\'a przy Ołtarzu Gorgroma, by zastawić pułapkę, przyzwać Gorgroma Smokożercę i go zabić.$b$bGdy Gorgrom zginie, postaw 3 Makabryczne totemy przy jego zwłokach.', '', 'Wróć do Rexxara w Warowni Władców Gromu w Górach Klingi.', 'Postaw Makabryczny totem', '', '', '', 0),
(10724, 'plPL', 'Więzień Klanu Ostrza', 'Wkrótce po moim przybyciu w te góry zaatakowała mnie grupa ogrów Klanu Ostrza.$b$bWyrwałem się im i wielu zabiłem, ale pojmali Leokka, moją wiwernę. Duch go odnalazł – jest zamknięty w klatce w samym sercu obozowiska Klanu Ostrza przed Leżem Gruula.$b$bKtóryś z ogrów musi mieć klucz. Znajdź go, a Duch otworzy nim klatkę Leokka.$B$BObozowisko znajdziesz na północnym krańcu Kanionu Sztyletopaszczy w dole.', 'Zabijaj ogry Klanu Ostrza, by zdobyć Klucz do klatki wiwerny. Gdy go zdobędziesz, idź do klatki wiwerny i użyj Gwizdka ducha, by przywołać Ducha, który otworzy klatkę i uwolni Leokka.', '', 'Wróć do Rexxara w Wiosce Władców Gromu w Górach Klingi.', '', '', 'Uwolnij Leokka', '', 0),
(10742, 'plPL', 'Ostateczna rozgrywka', 'Doszło więc do tego. Wywabimy Goca z jego leża i zniszczymy go. Gdy Goc zginie, ogry Klanu Ostrza przestaną zagrażać Mok\'Nathalom. Idź do ołtarza Goca przed Leżem Gruula i zadmij w mój róg. Przybędę i razem stawimy czoła synowi Gruula.', 'Użyj Rogu bojowego Rexxara przy Ołtarzu Goca, a potem zabij Goca.', '', 'Wróć do Rexxara w Warowni Władców Gromu w Górach Klingi.', '', '', '', '', 0),
(10743, 'plPL', '[DEPRECATED]<txt>Bohater Mok\'Nathalów', '', '', '', '', '', '', '', '', 0),
(10747, 'plPL', 'Pisklęta Kultu Żmija', 'Muszę zbadać pisklęta, które hodują w Sabacie Czarnoskrzydłych.$B$BW ich jaskiniowej siedzibie powinno latać ich mnóstwo, a do tego jest tam sporo jaj, z których pisklęta pewnie się wyklują, gdy podejdziesz bliżej.$B$BProszę, $N, weź tę sieć i złap dla mnie kilka z nich żywcem.$B$BDotrzesz tam, idąc na zachód przez Most Czaszki Żmija i dalej przez Tunel Czaszki Żmija. Idź ścieżką do samego końca, obok Grishnath i Kruczego Lasu.', 'Użyj Sieci na czarne pisklęta, by złapać 10 czarnych piskląt Kultu Żmija.', '', 'Wróć do Samii Inkling w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10748, 'plPL', 'Maxnar musi zginąć!', 'Nie zostawili nam wyboru, $N. Pora położyć kres zagrożeniu ze strony Sabatu Czarnoskrzydłych, eliminując ich przywódcę, Maxnara Popielną Paszczę.$B$BNie wiem, czy $gmiałeś:miałaś; okazję go zobaczyć, gdy tam $gbyłeś:byłaś;, ale to drakanin, pół człowiek, pół smok. I jest twardy, więc go nie lekceważ!$B$BZałatw to szybko, a przy odrobinie szczęścia zapewnisz bezpieczeństwo Wiecznemu Gajowi i Puszczy Ruuan.', 'Zabij Maxnara Popielną Paszczę.', '', 'Wróć do Strażnika drzew Chawna w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10749, 'plPL', 'Trucizna barona Sablemane\'a', 'Proszę, zanieś to swojemu panu. Jestem pewien, że bez względu na powód Rexxar zrobi z tego dobry użytek.$B$BAch, i koniecznie przypomnij mu, że jest mi winien.$B$BWie, czego chcę, i jestem pewien, że jakkolwiek zamierza mi to zdobyć, zobaczymy się szybciej, niż myślisz.$B$BA teraz bądź $ggrzecznym chłopcem:grzeczną dziewczynką; i zanieś to szybko Rexxarowi.', 'Dostarcz Truciznę barona Sablemane\'a Rexxarowi w Warowni Władców Gromu w Górach Klingi.', '', '', '', '', '', '', 0),
(10753, 'plPL', 'Przetrzebienie dziczy', 'Zbrodni popełnionych przez Płonący Legion nie da się zliczyć. Nawet teraz, gdy rozmawiamy, wysyłają swoje legiony przeciw stworzeniom tej krainy. Bezbronne wobec ich potęgi, padają jedno po drugim. $N, pomóż mi powstrzymać te zbrodnie przeciw naturze i zniszczyć wszystko, co splugawili.$B$BZa wzgórzem, na wschód stąd, zobaczysz skażenie rozprzestrzeniające się po Wąwozie Ostrzy. Zabij tych, którzy dopuszczają się tej zbrodni, Plugawicieli Spaczenia, oraz jak najwięcej zaprzysiężonych Spaczeniu.', 'Zabij 4 łuskoskrzydłych zaprzysiężonych Spaczeniu, 4 sztyletopaszcze zaprzysiężone Spaczeniu i 2 Plugawicieli Spaczenia.', '', 'Wróć do Faradrelli w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10770, 'plPL', 'Małe żarzątka', 'Na północny wschód stąd, na płaskowyżu nad nami, leżą spalone zgliszcza mojego pradawnego domu. Kwitł tam kiedyś wielki las, zanim Płonący Legion nasłał swoje chochliki, by nas spalić. Zginęło tak wielu, że nawet po stuleciach moje zmęczone stare serce łaknie zemsty. Jest ich zbyt wiele, byśmy kiedykolwiek odzyskali tę ziemię, ale ty $gmógłbyś:mogłabyś; napędzić im strachu.$B$BPomożesz mi, prawda?', 'Mchodrzew Pradawny chce, żebyś $gzabił:zabiła; 8 parzących chochlików, a potem do niego $gwrócił:wróciła; w Puszczy Ruuan.', '', 'Wróć do Mchodrzewa Pradawnego w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10771, 'plPL', 'Z popiołów', 'Jeśli pójdziesz drogą na wschód, w górę zbocza, a potem skręcisz na północ, dotrzesz do mojego dawno utraconego domu.$b$bKiedyś rósł tam las. Jego nazwa poszła w zapomnienie. Dawno temu Płonący Legion przywołał parzące chochliki i inne ogniste stworzenia. Mój dom został zniszczony, a mój lud uciekł. Zostałem tylko ja.$B$BZachowałem trochę nasion żelaznego korzenia, które można zasadzić w żyznej glebie wulkanicznej. Ich magia jest silna. Zrób to dla mnie, a podzielę się z tobą skarbami zapomnianej epoki.', 'Mchodrzew Pradawny chce, żebyś $gwybrał:wybrała; się do Skaldu, $gzasadził:zasadziła; Nasiona żelaznego korzenia w trzech różnych kopcach Żyznej gleby wulkanicznej, a potem do niego $gwrócił:wróciła; w Puszczy Ruuan.', '', 'Wróć do Mchodrzewa Pradawnego w Wiecznym Gaju w Górach Klingi.', 'Południowa gleba wulkaniczna', 'Środkowa gleba wulkaniczna', 'Północna gleba wulkaniczna', '', 0),
(10783, 'plPL', 'Baron Sablemane', 'Oto mój plan. Otrujemy ogry, a potem zniszczymy ich pana, gronna.$b$bPodczas wędrówek po tych górach spotkałem człowieka zwanego Baronem Sablemane\'em. To mistrz sztuki alchemicznej i może da się go przekonać, by nam pomógł.$b$bZnajdziesz go w Krwawym Kręgu, w kanionie na północ stąd. Jakiejkolwiek ceny zażąda, pozostawiam tobie decyzję, czy ją przyjąć.', 'Porozmawiaj z Baronem Sablemane\'em w Krwawym Kręgu w Górach Klingi.', '', '', '', '', '', '', 0),
(10784, 'plPL', 'Zmiażdżyć Obóz Krwawych Młotów', '<Tor\'chunk nachyla się, by szeptać.>$B$B$N, jak dotąd w walce z ogrami $gspisałeś:spisałaś; się nad wyraz dobrze. I choć w pełni ufam planowi Rexxara, poproszę cię jeszcze, żebyś przed powrotem $gzmiażdżył:zmiażdżyła; ogry w Obozie Krwawych Młotów.$B$BWtedy będziemy podwójnie pewni wyniku.$B$BAby tam dotrzeć, zejdź pochylnią na północ z Warowni Władców Gromu. U jej stóp skręć na zachód przez Kres Smoków, a potem na północ przez Wąwóz Wirów i Kanion Sztyletopaszczy.', 'Zabij 10 mocarzy Krwawych Młotów i 5 czarnoksiężników Krwawych Młotów.', '', 'Wróć do Tor\'chunka Dwuszpona w Warowni Władców Gromu w Górach Klingi.', '', '', '', '', 0),
(10785, 'plPL', 'To pułapka!', 'Nie ma na tym świecie większego powodu do furii niż Gruul i jego synowie. Wyrżnęli mój lud – moje dzieci – a teraz się zemszczę.$B$BZrobiłem pułapkę ze smoczego ognia i jeśli masz dość sprytu, możesz nią zabić nawet gronna.$B$BTylko się pospiesz, zanieś pułapkę Rexxarowi. Moje pragnienie zemsty musi zostać ugaszone.', 'Dostarcz Pułapkę smoczego ognia Rexxarowi w Warowni Władców Gromu w Górach Klingi.', '', '', '', '', '', '', 0),
(10786, 'plPL', 'Rzeź w Boulder\'mok', 'Wiem, że Rexxar chce cię wysłać do Boulder\'mok. Mam coś, co chciałbym, żebyś tam przy okazji $gzrobił:zrobiła;.$B$BMusimy wykorzystać każdą okazję, by uderzyć w ogry z tych gór, bo inaczej nas zaleją, a wszystko, za co przelewaliśmy krew i ginęliśmy, pójdzie na marne!$B$BBoulder\'mok leży daleko na północnym zachodzie. Idź na północ do Puszczy Ruuan, a stamtąd na zachód przez tunel i dalej, za Kruczy Las.$B$B$N, chcę, żebyś $gwybił:wybiła; ogry Klanu Ostrza z Boulder\'mok. Wytęp je do nogi!', 'Zabij 5 osiłków Boulder\'mok i 3 szamanów Boulder\'mok, a potem wróć do Tor\'chunka Dwuszpona w Warowni Władców Gromu w Górach Klingi.', '', 'Wróć do Tor\'chunka Dwuszpona w Warowni Władców Gromu w Górach Klingi.', '', '', '', '', 0),
(10787, 'plPL', '[DEPRECATED]<txt><nyi>Smoki z Kresu Smoków', 'Jeśli mamy stawić czoła Gocowi, musimy zrobić coś, co go rozwścieczy.$B$BA skoro dzięki tobie &&& jest już na wolności, chyba wiem, co się nada!$B$BGdy będziesz $ggotów:gotowa;, daj mi znać, a poproszę &&& o przelot z tobą do jednego ze smoczych trucheł nadzianych na skały przy Kresie Smoków.$B$BZabierz truchło i przynieś mi je tutaj, żebyśmy mogli stworzyć coś, co na pewno wywabi Goca z kryjówki!', 'Rexxar poprosił cię o rozmowę w sprawie lotu na &&& do Kresu Smoków po truchło czarnego smoka. Gdy je zdobędziesz, wróć do Rexxara w Warowni Władców Gromu w Górach Klingi.', '', 'Wróć do Rexxara na Ziemiach Klanu Ostrza w Górach Klingi.', '', '', '', '', 0),
(10795, 'plPL', 'Randka z Dorgokiem', 'Dobrze, że jesteś. Widywałem cię w okolicy i od dawna zamierzałem porozmawiać z tobą o pewnej ważnej sprawie.$B$BDocierają do nas meldunki, że z jakiegoś powodu ogry Krwawych Młotów szykują natarcie na Sylvanaar i Puszczę Ruuan. Nie wiemy, kto ani co je do tego popycha, ale zamierzam zdusić ten plan w zarodku!$B$BAtaki mają wyjść z Obozu Krwawych Młotów. Zejdź z Puszczy Ruuan pochylnią na północny zachód, a go znajdziesz. Chcę, żebyś $gzabił:zabiła; ich przywódcę, Dorgoka!', 'Zabij Dorgoka w Obozie Krwawych Młotów.', '', 'Wróć do Dowódcy Haephusa Kamiennego Muru w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10796, 'plPL', 'Zmiażdż Obóz Krwawych Młotów!', 'Słyszałam, że jak dotąd w walce z ogrami $gspisałeś:spisałaś; się nad wyraz dobrze. Teraz prosiłabym, żebyś znów $gstawił:stawiła; im czoła. Chcę, żebyś $gzmiażdżył:zmiażdżyła; ogry w Obozie Krwawych Młotów!$B$BAby się tam dostać, zejdź z Puszczy Ruuan pochylnią na północny zachód. Znajdziesz je u jej podnóża.$B$BPowodzenia, $N!', 'Zabij 10 mocarzy Krwawych Młotów i 5 czarnoksiężników Krwawych Młotów.', '', 'Wróć do Porucznik Fairweather w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10797, 'plPL', 'Łaska gronna', 'Z martwej dłoni Dorgoka wypada talizman w kształcie niewielkiej figurki. Jest uderzająco podobny do jednego z gronnów.$B$BTo z pewnością zainteresuje Dowódcę Haephusa Kamienny Mur w Wiecznym Gaju w Puszczy Ruuan, na górze pochylni na wschodzie!', 'Dostarcz Łaskę Gorgroma Dowódcy Haephusowi Kamiennemu Murowi w Wiecznym Gaju w Górach Klingi.', '', '', '', '', '', '', 0),
(10798, 'plPL', 'Złóż wizytę Baronowi', 'Złe wieści. To Gorgrom Smokożerca stoi za ostatnimi planami Krwawych Młotów przeciwko Sylvanaar!$B$BNie wiem, czemu manipuluje nimi, zamiast po prostu posłużyć się Klanem Ostrza. Ale jeśli mamy się rozprawić z gronnem, będziemy potrzebować pomocy.$B$BZnam człowieka biegłego we wszelkich egzotycznych rodzajach magii. Nazywa się Baron Sablemane, a znajdziesz go w Krwawym Kręgu – zejdź z powrotem pochylnią na północny zachód, a potem idź kanionem na południowy zachód.$B$BPoproś go, by sporządził dla nas pułapkę na gronna.', 'Porozmawiaj z Baronem Sablemane\'em w Krwawym Kręgu w Górach Klingi.', '', '', '', '', '', '', 0),
(10799, 'plPL', 'W głąb Wąwozu Wirów', 'Dobrze, zrobię tę pułapkę, ale najpierw chcę czegoś w zamian.$B$BTak się składa, że w pobliżu żyje gronn, który ma pewien przedmiot, na którym mi zależy, ale ty nie dasz mu rady – przynajmniej jeszcze nie.$B$BDlatego ty i ja sporządzimy proszek usypiający z jadu okolicznych kruszycieli skorupy.$B$BZnajdziesz je w Wąwozie Wirów na południowym zachodzie. Przynieś mi trochę ich gruczołów, tylko się pospiesz!', 'Zbierz 7 gruczołów jadowych kruszycieli skorupy.', '', 'Wróć do Barona Sablemane\'a w Krwawym Kręgu w Górach Klingi.', '', '', '', '', 0),
(10800, 'plPL', 'Dobranoc, gronnie', 'Znów przeszedłem samego siebie. Sporządziłem proszek usypiający, którego użyjesz na Grullocu – gronnie, o którym mówiłem, tym, który strzeże tego, czego pragnę.$B$BGrulloc przesiaduje w Przeklętej Kotlinie, na wschodnim skraju Kresu Smoków, po drugiej stronie Krwawego Kręgu.$B$BNa twoim miejscu nie zwlekałbym długo, gdy już zdobędziesz jego wór. Pył nie działa długo.', 'Zdobądź Wór Grulloca.', '', 'Wróć do Barona Sablemane\'a w Krwawym Kręgu w Górach Klingi.', '', '', '', '', 0),
(10801, 'plPL', 'To pułapka!', 'Niczego na tym świecie nie nienawidzę bardziej niż synów Gruula i ich ojca! Wyrżnęli mój lud i moje dzieci, a teraz zakosztuję zemsty!$B$BZrobiłem pułapkę ze smoczego ognia i jeśli masz dość sprytu, może zdołasz jej użyć, by zabić gronna.$B$BNa pewno masz na myśli jakiegoś konkretnego gronna – mnie jest wszystko jedno, którego zabijesz. Tylko się pospiesz i zanieś pułapkę twojemu Dowódcy Kamiennemu Murowi.$B$BMoje pragnienie zemsty musi zostać ugaszone!', 'Dostarcz Pułapkę smoczego ognia Dowódcy Haephusowi Kamiennemu Murowi w Wiecznym Gaju w Górach Klingi.', '', '', '', '', '', '', 0),
(10802, 'plPL', 'Gorgrom Smokożerca', 'Musimy pokazać ogrom, że nie należy z nami zadzierać. Musimy przekazać im wiadomość.$b$bUdaj się do Boulder\'mok i zabij tamtejsze ogry. Pamiętaj, żeby zachować ich głowy.$b$bPotem idź do ołtarza Gorgroma i zastaw na niego pułapkę. Gorgrom się pojawi, a ty musisz go w nią zwabić. Gdy zginie, postaw swoje makabryczne totemy przy jego zwłokach, żeby ogry patrzyły na swojego poległego pana i poległych braci i wiedziały, jaka jest cena za próbę zniszczenia nas.', 'Zdobądź 3 Makabryczne totemy od ogrów z Boulder\'mok. Następnie użyj Pułapki Sablemane\'a przy Ołtarzu Gorgroma, by przyzwać Gorgroma Smokożercę i go zabić.$b$bGdy Gorgrom zginie, postaw 3 Makabryczne totemy przy jego zwłokach.', '', 'Wróć do Dowódcy Haephusa Kamiennego Muru w Wiecznym Gaju w Górach Klingi.', 'Postaw Makabryczny totem', '', '', '', 0),
(10803, 'plPL', 'Rzeź w Boulder\'mok', 'Wiem, że mamy wobec ciebie plany i wyślemy cię do Boulder\'mok. Mam coś, co chciałabym, żebyś tam przy okazji $gzrobił:zrobiła;.$B$BMusimy wykorzystać każdą okazję, by uderzyć w ogry z tych gór, bo inaczej nas zaleją, a wszystko, za co przelewaliśmy krew i ginęliśmy, pójdzie na marne!$B$BBoulder\'mok leży na zachodzie. Idź na południowy zachód, przejdź przez most i dalej tunelem. Znajdziesz je po zachodniej stronie Kruczego Lasu.$B$B$N, chcę, żebyś $gwytępił:wytępiła; ogry Klanu Ostrza z Boulder\'mok.', 'Zabij 5 osiłków Boulder\'mok i 3 szamanów Boulder\'mok.', '', 'Wróć do Porucznik Fairweather w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10805, 'plPL', 'Masakra pod Leżem Gruula', 'Okazało się, że jesteś $gzaradny:zaradna;, więc chyba wykorzystam cię osobiście w mojej własnej walce z Gruulem i jego synami.$B$BKlan Ostrza cieszy się względami gronnów i choć gdzie indziej $gprzetrzebiłeś:przetrzebiłaś; jego szeregi, z najsilniejszymi jeszcze się nie $gzmierzyłeś:zmierzyłaś;.$B$BGruul powierza ochronę okolic swojego leża tylko najtwardszym ogrom i to je musisz zabić. Idź na północ przez Kanion Sztyletopaszczy, a na jego końcu znajdziesz Leże Gruula.', 'Zabij 10 nadzorców Klanu Ostrza, 5 magów bojowych Klanu Ostrza, 5 pustoszycieli Klanu Ostrza i ich przywódcę, Fingroma.', '', 'Wróć do Barona Sablemane\'a w Krwawym Kręgu w Górach Klingi.', '', '', '', '', 0),
(10806, 'plPL', 'Ostateczna rozgrywka', 'Nadszedł czas, byśmy stawili czoła Gocowi, panu ogrów Klanu Ostrza. Nadszedł też czas, bym sam wkroczył do akcji i ujrzał kres życia tego gronna.$b$bWeź mój sygnet. Gdy dotrzesz do Ołtarza Goca, użyj go, a ja do ciebie dołączę.$b$bRazem zniszczymy Goca.', 'Użyj Sygnetu Sablemane\'a przy Ołtarzu Goca, a potem zabij Goca.', '', 'Wróć do Barona Sablemane\'a w Krwawym Kręgu w Górach Klingi.', '', '', '', '', 0),
(10810, 'plPL', 'Uszkodzona maska', 'Gdy oglądasz uszkodzoną maskę, słyszysz dobiegające z jej wnętrza dziwne dźwięki. Gdyby maska nie była uszkodzona, może dałoby się usłyszeć je wyraźniej.$B$BO\'Mally Łapiprąd w Puszczy Ruuan może zdoła naprawić maskę.', 'Dostarcz Uszkodzoną maskę O\'Mally\'emu Łapiprądowi w Wiecznym Gaju w Górach Klingi.', '', '', '', '', '', '', 0),
(10812, 'plPL', 'Tajemnicza maska', 'No, teraz powinna działać. Co to jest, pytasz? Ależ to urządzenie do porozumiewania się – pozwala tym tępakom rozmawiać ze sobą. No wiesz, Płonącemu Legionowi! Radziłbym ci oddać tę maskę Władcy dziczy Antelarionowi. Chodzi tam w tę i z powrotem. Ciągle jest w ruchu.$B$BNo, ruszaj się, od dłuższego czasu próbuje dostać coś takiego w swoje ręce.', 'Dostarcz Tajemniczą maskę Władcy dziczy Antelarionowi w Wiecznym Gaju w Górach Klingi.', '', '', '', '', '', '', 0),
(10818, 'plPL', 'Baron Sablemane wzywa cię do siebie', '$N, gdy $gbyłeś:byłaś; w terenie i $gspisywałeś:spisywałaś; się na medal, Baron Sablemane przysłał tu swojego smoka z wiadomością.$B$BPoprosił o ciebie osobiście. Z tego, co rozumiem, chce, żebyś $gpoprowadził:poprowadziła; jego własną walkę z gronnami.$B$BChyba jesteś najlepiej przygotowaną osobą w całej Rubieży, by mu pomóc, ale na twoim miejscu najpierw skontaktowałbym się z kilkoma przyjaciółmi i poprosił ich, żeby dołączyli do ciebie w Krwawym Kręgu.', 'Porozmawiaj z Baronem Sablemane\'em w Krwawym Kręgu w Górach Klingi.', '', '', '', '', '', '', 0),
(10819, 'plPL', 'Maska gazowa zaprzysiężonych Spaczeniu', 'Mam dla ciebie bardzo szczególną misję, $N. Musisz przeniknąć do Obozu Kuźniczego Złość na wschód stąd. Gdy wejdziesz do obozu, załóż maskę gazową zaprzysiężonych Spaczeniu i odszukaj komunikator Legionu. Gdy już go znajdziesz, porozmawiaj z tym, kto jest po drugiej stronie urządzenia.$B$BJeśli wszystko pójdzie dobrze, zdołasz podstępem nakłonić demona do czegoś niecnego! Spróbuj mu powiedzieć, że w Obozie Złość wybuchł bunt.$B$BPowodzenia.', 'Załóż Maskę gazową zaprzysiężonych Spaczeniu i użyj Komunikatora Legionu w Obozie Kuźniczym Złość w Górach Klingi.', '', '', '', '', '', '', 0),
(10820, 'plPL', 'Zwiedź swego wroga', 'Z każdą chwilą ciszy zbliżasz się do śmierci! MÓW!$B$BCo? Obóz się zbuntował? To niemożliwe! Moje sługi nie ośmieliłyby się podważać mojej władzy.$B$BA więc co do jednego zapłacą za tę zdradę, zapłacą słono. Ucisz ich wszystkich i skończ z tym! Zamelduj mi się, gdy wykonasz mój rozkaz, albo spotka cię kara.', 'Zabij 4 sługi Kuźni Zagłady i 4 inżynierów Kuźni Zagłady.', '', 'Wróć do Komunikatora Legionu w Obozie Kuźniczym Złość w Górach Klingi.', '', '', '', '', 0),
(10821, 'plPL', 'Zwolnienie dyscyplinarne', 'Głosicielka zagłady nic nie zrobiła, by powstrzymać bunt? Jak śmiała! Od pewnego czasu próbuje podważać moją władzę. Ale to był ostatni raz. Musisz ją przywołać i osobiście się z nią rozprawić.$B$BJej strażnicy złości mają klucze, które przywołują ją do Obozu Kuźniczego Złość. Zdobądź pięć kluczy i uaktywnij pięć obelisków Legionu. Obeliski działają krótko, więc dopilnuj, by wszystkie zostały uaktywnione jednocześnie. Pamiętaj, strażnicy złości mają przy sobie więcej kluczy.', 'Zabij Głosicielkę zagłady.', '', 'Wróć do Władcy dziczy Antelariona w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10825, 'plPL', 'Prawda zaklęta w kuli', 'Spod piór arakkoa wypada dziwna, magiczna kula.$B$BSpowita niesamowitą purpurową poświatą, pulsuje w rytm niesłyszalnego bicia. Trzymanie jej w dłoni budzi w tobie lekki niepokój, więc szybko chowasz ją do plecaka.$B$BMoże Strażnik drzew Chawn w Puszczy Ruuan na zachodzie – przez tunel i Most Czaszki Żmija – chciałby ją zbadać?', 'Dostarcz Kulę Grishna Strażnikowi drzew Chawnowi w Wiecznym Gaju w Górach Klingi.', '', '', '', '', '', '', 0),
(10829, 'plPL', 'Pniak musi się dowiedzieć', 'To niepokojące! Arakkoa sprawiają, że pradrzewców i obrońców lasu opętują złe duchy!$B$BJest jednak jeden pradrzewiec, którego to na pewno nie dotknęło. Nazywa się Pniak i musisz natychmiast do niego iść, jeśli mamy ocalić drzewa Kruczego Lasu!$B$BWróć do Kruczego Lasu. Znajdziesz go na rozwidleniu ścieżki tuż za Grishnath.', 'Porozmawiaj z Pniakiem, pradrzewcem wiedzy, który mieszka w Kruczym Lesie w Górach Klingi.', '', '', '', '', '', '', 0),
(10830, 'plPL', 'Egzorcyzmy drzew', 'Grishna sprawiły, że w liściobrodych i kamiennokorych zamieszkały złe duchy koi-koi.$B$BMusimy ocalić drzewa, bo inaczej cały Kruczy Las wkrótce przepadnie na zawsze!$B$BPołącz magię kuli z Grishnath – znajdziesz je w całym Grishnath – ze straszliwym piórem straszliwego kruka.$B$BUżyj powstałego pióra egzorcyzmu, by wywabić ducha koi-koi, i jak najszybciej go zabij. Kamiennokorzy są zbyt potężni na ten rytuał, ale jeśli ocalisz dość liściobrodych, oni także zostaną uwolnieni.', 'Zbierz 5 Kul z Grishnath i 5 Straszliwych piór, a następnie połącz je w Pióra egzorcyzmu. Użyj tych piór, by wypędzić z liściobrodych z Kruczego Lasu 5 duchów Koi-Koi i je zabić.', '', 'Wróć do Pniaka w Kruczym Lesie w Górach Klingi.', 'Egzorcyzm liściobrodego', '', '', '', 0),
(10843, 'plPL', 'Od niepamiętnych czasów...', 'Od niepamiętnych czasów walczymy z ogrami Klanu Ostrza.$B$BZdołaliśmy zepchnąć ich tak daleko, że teraz ledwie utrzymują się w Posterunku Klanu Ostrza. Leży on tam, skąd $gprzyszedłeś:przyszłaś;, na południowo-zachodnim skraju Brzytwowej Grani.$B$BUdowodnij mi swoją wartość, zabijając ich przywódcę, Gnosha Brognata.$B$BZobaczmy, z jakiej gliny cię ulepiono, gdy przyjdzie ci walczyć z ogrami.', 'Zabij Gnosha Brognata, przywódcę ogrów w Posterunku Klanu Ostrza.', '', 'Wróć do Leoroxxa w Wiosce Mok\'Nathal w Górach Klingi.', '', '', '', '', 0),
(10844, 'plPL', 'Obóz Kuźniczy: Złość', '', '', '', '', '', '', '', '', 0),
(10845, 'plPL', 'Zabij matkę miotu', 'Moi łowcy właśnie wrócili ze zwiadu na Śpiewającej Grani. Wygląda na to, że smokowców Otchłani, które roją się tam wśród kryształów, bardzo przybyło i grożą, że wyleją się nam na głowy.$B$BSkoro $gokazałeś:okazałaś; się $gsprawnym zabójcą:sprawną zabójczynią;, zobaczmy, czy twoje umiejętności dorównają dorosłemu smokowcowi.$B$BŚpiewającą Grań znajdziesz, idąc na południe przez Półkę Łuskoskrzydłych. Wejdź tam i zabij ich matkę miotu, Trwogoskrzydłą.', 'Zabij Trwogoskrzydłą.', '', 'Wróć do Leoroxxa w Wiosce Mok\'Nathal w Górach Klingi.', '', '', '', '', 0),
(10846, 'plPL', 'Zrozumieć Mok\'Nathalów', '<Leoroxx patrzy ci w oczy wzrokiem, który mrozi duszę.>$B$BPrzychodzisz do Mok\'Nathalów, ale nas nie rozumiesz. Nie rozumiesz naszej walki o przetrwanie.$B$BJeśli chcesz nas zrozumieć, musisz zakosztować tej walki.$B$BNa południu żyją arakkoa Vekh\'nir. Zniewolili grupę ogrów w jaskiniach zwanych Działką Trogmy, a ich przywódca, Vekh, jest w środku.$B$BZabij go!', 'Zabij Vekha, przywódcę arakkoa Vekh\'nir.', '', 'Wróć do Leoroxxa w Wiosce Mok\'Nathal w Górach Klingi.', '', '', '', '', 0),
(10851, 'plPL', 'Totemy mego wroga', 'Jest właściwy sposób oddawania czci przodkom i jest niewłaściwy.$B$BOgry Klanu Ostrza noszą ze sobą totemy, ale nie używają ich, by okazywać szacunek. Zamiast tego chcą za ich pomocą manipulować i sprawować kontrolę.$B$BPowinniśmy ukraść im totemy, bo są ich niegodni! Wtedy zrobimy z nich lepszy użytek.$B$BIdź do Posterunku Klanu Ostrza na zachodzie, tuż na południowy zachód od Brzytwowej Grani. Zabijaj mistyków i miażdżycieli Klanu Ostrza i odbierz im totemy!', 'Zbierz 5 Totemów Klanu Ostrza.', '', 'Wróć do Przywoływacza duchów Dohgara w Wiosce Mok\'Nathal w Górach Klingi.', '', '', '', '', 0),
(10853, 'plPL', 'Wzywanie duchów', 'Duchy smokowców Otchłani ze Śpiewającej Grani potrzebują wyzwolenia.$B$BSmokowce Otchłani nie zawsze były smokowcami Otchłani. Kiedyś były czarnymi smokowcami.$B$BAle potem, gdy ten świat uległ zniszczeniu, wszystko zalała fala energii Otchłani, która przy okazji odmieniła jaja młodych smokowców.$B$BTeraz wszystkie są wypaczonymi wersjami tego, czym były. Musimy pomóc im odnaleźć spokój.$B$BZrób to, zabijając smokowca w pobliżu totemu wzywania duchów, a potem odbierz mu jego ducha.', 'Użyj Totemów wzywania duchów, by zebrać 8 Duchów pomniejszego smokowca Otchłani.', '', 'Wróć do Przywoływacza duchów Dohgara w Wiosce Mok\'Nathal w Górach Klingi.', '', '', '', '', 0),
(10859, 'plPL', 'Zbierz kule', 'Eteryczni Razaani mają dziwne urządzenia, które wypuszczają małe, różowe, unoszące się w powietrzu kule światła. Przypominają mi dusze.$B$BNie należy ich mylić z dużymi żółtymi kulami, które wyrywają się z eterycznych, gdy giną – to coś zupełnie innego.$B$BChciałbym, żebyś $gposzedł:poszła; na północ do Przystani Razaana i $gpostawił:postawiła; tam kilka totemów, które przyciągną różowe świetlne kule.$B$BPrzynieś mi je, żebym mógł ustalić, czym dokładnie są.', 'Użyj Totemu zbierania kul, by zebrać 15 świetlnych kul Razaani.', '', 'Wróć do Przywoływacza duchów Dohgara w Wiosce Mok\'Nathal w Górach Klingi.', 'Zebrane świetlne kule Razaani', '', '', '', 0),
(10860, 'plPL', 'Przysmaki Mok\'Nathalów', '$GGłodny:Głodna;? Wielki Duch pomaga tym, którzy sami sobie pomagają. Jeśli chcesz zasłużyć na posiłek, radzę ci dobrze słuchać, bo Braagor niczego ci nie da za darmo, a już na pewno nic tak smacznego!$B$BRaptory i łuskoskrzydłe węże z Brzytwowej Grani i Półki Łuskoskrzydłych mają wszystko, czego trzeba do dwóch najpyszniejszych potraw, jakich kiedykolwiek skosztujesz. Przynieś mi żeberka raptorów i mięso węży, a przyrządzę ci po porcji każdej z nich.$B$BMoże nawet nauczę cię je przyrządzać, jeśli się pospieszysz.', 'Zbierz 3 Żeberka raptora i 3 kawałki Mięsa węża.', '', 'Wróć do Matrony Varah w Wiosce Mok\'Nathal w Górach Klingi.', '', '', '', '', 0),
(10865, 'plPL', 'Powiadom Leoroxxa!', 'Szybko, musisz powiadomić Leoroxxa o tym, co dzieje się na Przystani Razaana!$B$BTe kule składały się z dusz, a niektóre z nich należały do Mok\'Nathalów!', 'Porozmawiaj z Leoroxxem o tym, co knują eteryczni Razaani. Znajdziesz go w Wiosce Mok\'Nathal w Górach Klingi.', '', '', '', '', '', '', 0),
(10867, 'plPL', 'Odpowiedź może być tylko jedna', 'Na to... na to ZBEZCZESZCZENIE dusz naszych przodków odpowiedź może być tylko jedna!$B$B$N, jeśli chcesz nam pomóc przywrócić dusze naszych czcigodnych zmarłych na należne im miejsce, wróć na Przystań Razaana.$B$BIdź tam i zabijaj Razaani, aż ich przywódca, Książę Nexusa Razaan, pokaże swoją tchórzliwą twarz. Zabij go, odzyskaj te dusze i przekaż je Przywoływaczowi duchów Dohgarowi!', 'Zdobądź Zbiór dusz.', '', 'Wróć do Przywoływacza duchów Dohgara w Wiosce Mok\'Nathal w Górach Klingi.', '', '', '', '', 0),
(10893, 'plPL', 'Wszystko zależy od Długiego Ogona', 'Kultyści Żmija z Sabatu Czarnoskrzydłych gromadzą się w tunelu i ledwie dajemy sobie radę z sytuacją. Mówiąc szczerze, mają przewagę liczebną.$B$BI choć udaje nam się rozprawiać z każdym, kto podejdzie za blisko, faktem pozostaje, że jeśli zaatakują na serio, zaleją nas.$B$BSytuacja wymaga, by ktoś przedarł się na drugi koniec tunelu i zlikwidował ich przywódczynię, Draacę Długi Ogon. Masz ochotę na odrobinę zabawy?', 'Zabij Draacę Długi Ogon, przywódczynię kultystów Żmija w Tunelu Czaszki Żmija.', '', 'Wróć do Wartownika Księżycowego Cienia przy Tunelu Czaszki Żmija w Górach Klingi.', '', '', '', '', 0),
(10894, 'plPL', 'Wartownik z Czaszki Żmija', 'Hmm, nie jestem pewien, co powinniśmy zrobić. Nie jestem wielkim strategiem.$B$BWartownik Księżycowy Cień będzie wiedział, co robić. Kieruje naszą obroną przy Tunelu Czaszki Żmija na zachodzie, na końcu Mostu Czaszki Żmija. Mamy tam oddział na wypadek, gdyby kultyści próbowali jakichś sztuczek.$B$BProszę, zanieś mu tę notatkę z największym pośpiechem.', 'Dostarcz Notatkę ze spotkania Wartownikowi Księżycowemu Cieniowi u wejścia do Tunelu Czaszki Żmija w Górach Klingi.', '', '', '', '', '', '', 0),
(10904, 'plPL', 'Zbieranie spaczonej amunicji', 'Musimy odciąć Płonącemu Legionowi dostęp do Wrót Śmierci, ale najpierw zniszczysz ich dwie bramy wypaczenia!$B$BKłopot w tym, że nie potrafimy nawet ich zadrapać, więc będziesz $gmusiał:musiała; obrócić przeciwko nim ich własną broń.$B$BPotęgi Śmierci, Straże Śmierci, nadkowale Kuźni Śmierci i technicy Kuźni Śmierci noszą amunicję do spaczonych dział.$B$BZwykle nie zrobiłaby żadnemu z nich krzywdy, ale jeśli przyniesiesz mi kule armatnie, nasycę je nieokiełznanym gniewem Natury!', 'Zbierz 5 Spaczonych kul armatnich.', '', 'Użyj Sygnału druida, by przywołać Druida z Wiecznego Gaju u Wrót Śmierci w Górach Klingi.', '', '', '', '', 0),
(10910, 'plPL', 'Wrota Śmierci', 'Teraz Płonący Legion stanowi jeszcze większe zagrożenie. Na południu znajduje się portal zwany Wrotami Śmierci, który otwiera się na przerażający świat, gdzie Legion hoduje swoje zabójcze ogary.$B$BAby tam dotrzeć, wyjdź z Wiecznego Gaju pochylnią na wschód. Idź ścieżką na południe przez Wąwóz Ostrzy, Przystań Razaana, Brzytwową Grań i Półkę Łuskoskrzydłych. Potem zejdź pochylnią do Reduty Vekhaar i wejdź do Wrót Śmierci przez tunel na południe od wioski Mok\'Nathal.$B$BGdy już tam dotrzesz, użyj tego sygnału druida.', 'Użyj Sygnału druida u Wrót Śmierci, by przywołać Druida z Wiecznego Gaju, i porozmawiaj z nim.', '', '', '', '', '', '', 0),
(10911, 'plPL', 'Ogień dowolny!', 'Teraz, gdy amunicja może zaszkodzić Płonącemu Legionowi, pora jej użyć.$B$BSą tu dwie bramy wypaczenia, służące do teleportacji i wzmacniania postrachów Pustki. Jedna jest na południu, druga na północy, i każda znajduje się w zasięgu spaczonego działa.$B$BUżyj znaturalizowanej amunicji, by przejąć kontrolę nad każdym spaczonym działem i zniszczyć bramy wypaczenia.$B$BZacznij od ostrzału bramy z działa i bądź $ggotów:gotowa; w razie potrzeby zabijać jej obrońców, by działo przetrwało.', 'Użyj Znaturalizowanej amunicji, by przejąć kontrolę nad Spaczonymi działami z Wrót Śmierci. Zniszcz z ich pomocą Południową Bramę Wypaczenia i Północną Bramę Wypaczenia.', '', 'Użyj Sygnału druida, by przywołać Druida z Wiecznego Gaju u Wrót Śmierci w Górach Klingi.', 'Zniszczona Południowa Brama Wypaczenia', 'Zniszczona Północna Brama Wypaczenia', '', '', 0),
(10912, 'plPL', 'Treser Ogarów', 'Baelmon Treser Ogarów musi zginąć! To on podtrzymuje rytuał, dzięki któremu działa portal.$B$BPortal Wrót Śmierci znajduje się na północnym końcu kanionu. Gdy go znajdziesz, znajdziesz też Baelmona.$B$BBędziesz potrzebować pomocy, więc weź tę różdżkę. Gdy będziesz walczyć z Treserem Ogarów, użyj jej, a kilku moich przyjaciół przybędzie ci z pomocą.$B$BGdy pokonasz Baelmona, wróć do Władcy dziczy Antelariona.$B$BI, $N, dziękuję ci za wszystko, przez co dla nas tu $gprzeszedłeś:przeszłaś;.', 'Zabij Baelmona Tresera Ogarów.', '', 'Wróć do Władcy dziczy Antelariona w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10927, 'plPL', 'Tępienie pełzaczy', 'Dowódca Niebocień chce, żeby ten tunel został oczyszczony, byśmy mogli usprawnić handel z Przystanią. Nie mogę opuścić tu posterunku, więc zostawiam to zadanie w twoich rękach. Oczyść tunel i natychmiast zamelduj się u Dowódcy Niebocienia!$B', 'Zabij 6 jaskiniowych pełzaczy.', '', 'Zamelduj się u Dowódcy Niebocienia w Sylvanaar w Górach Klingi.', '', '', '', '', 0),
(10928, 'plPL', 'Tępienie pełzaczy', 'Tor\'chunk Dwuszpon chce, żeby ten tunel został oczyszczony, byśmy mogli usprawnić handel z Posterunkiem Bagiennego Szczura. Nie mogę opuścić tu posterunku, więc zostawiam to zadanie w twoich rękach. Oczyść tunel i natychmiast zamelduj się u Tor\'chunka Dwuszpona!$B', 'Zabij 6 jaskiniowych pełzaczy.', '', 'Zamelduj się u Tor\'chunka Dwuszpona w Warowni Władców Gromu w Górach Klingi.', '', '', '', '', 0),
(10974, 'plPL', 'Komory stazy Bash\'ira', 'Eterium ma osadę na najdalej wysuniętej na północ półce Gór Klingi, zwaną Przystanią Bash\'ira. Według tabliczki-klucza w Przystani Bash\'ira przetrzymywane są znacznie większe wersje więzień. Warto też zauważyć, że Eterium nazywa te więzienia komorami stazy.$B$BTabliczka-klucz daje dostęp do jednej, bardzo konkretnej komory stazy w przystani, znanej jako Komora stazy Alfa. Weź klucz i zbadaj sprawę.$B$BMój wizerunek będzie czekał na twój powrót w Przystani Bash\'ira. Tam ze mną porozmawiaj.', 'Użyj Tabliczki-klucza Eterium – Alfa, by otworzyć Komorę stazy Alfa w Przystani Bash\'ira w Górach Klingi.$B$BZanieś Dowody z Alfy Wizerunkowi dowódcy Ameera w Przystani Bash\'ira.', '', 'Porozmawiaj z Wizerunkiem dowódcy Ameera w Przystani Bash\'ira w Górach Klingi.', '', '', '', '', 0),
(10975, 'plPL', 'Oczyszczanie komór Bash\'ira', '', '', '', 'Wróć do Wizerunku dowódcy Ameera w Przystani Bash\'ira w Górach Klingi.', '', '', '', '', 0),
(10976, 'plPL', 'Znak Króla Nexusa', 'Teraz muszę się dowiedzieć, co Eterium przetrzymuje w Grobowcach Many w Auchindoun.$B$BW walkach z bestiami z komór stazy Bash\'ira możesz natrafić na przedmiot zwany Znakiem Króla Nexusa. Jeśli go znajdziesz, natychmiast mi go przynieś! To ostatni element potrzebny do wykonania klucza, który otworzy dostęp do komory stazy w Grobowcach Many.', 'Wizerunek dowódcy Ameera na Przystani Bash\'ira w Górach Klingi chce, żebyś $gprzyniósł:przyniosła; mu Znak Króla Nexusa.', '', 'Wróć do Wizerunku dowódcy Ameera w Przystani Bash\'ira w Górach Klingi.', '', '', '', '', 0),
(10977, 'plPL', 'Komory stazy w Grobowcach Many', 'Znak Króla Nexusa, który $godzyskałeś:odzyskałaś;, pozwolił mi wykuć nowy klucz do komór stazy w Grobowcach Many.$B$BWedług glifów na znaku są dwie: jedna blisko wejścia, a druga w pobliżu księcia Nexusa Shaffara. Klucz, który zaraz ci dam, otworzy komorę stazy przy wejściu.$B$BIdź do Grobowców Many w Auchindoun i otwórz tamtejszą komorę stazy.', 'Wizerunek dowódcy Ameera na Przystani Bash\'ira w Górach Klingi chce, żebyś $gużył:użyła; Klucza do komory stazy w Grobowcach Many na komorze stazy wewnątrz Grobowców Many w Auchindoun.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', 'Komora stazy w Grobowcach Many zbadana', 'Wróć do Wizerunku dowódcy Ameera w Przystani Bash\'ira w Górach Klingi.', '', '', '', '', 0),
(10980, 'plPL', 'Księga Kruka', 'Z tego, co mi $gpowiedziałeś:powiedziałaś;, podejrzenia Morthisa wydają się wiarygodne, ale potrzebujemy potwierdzenia.$B$BTimeon natrafił w swoich badaniach na wskazówki, że „księga kruka” była dawnym pismem świętym tego kultu.$B$BDuchy arakkoa nie ukażą się twoim oczom. Zabierz ten kamień na wysokie szczyty w zachodniej części Gór Klingi, na południe od Kruczego Lasu, zdobądź oko płaszczki eteru i połącz je, by wyostrzyć wzrok. Odszukaj ducha, którego Timeon rozpoznał jako Sai\'kkala Starszego.', 'Użyj Oka płaszczki eteru z Kamieniem jasnowidza, by ujrzeć duchy kultu kruka. Odszukaj na Szczycie Wiru ducha Sai\'kkala Starszego, wypytaj go o księgę kruka, a potem wróć do Arthorn Pieśni Wiatru.', '', 'Wróć do Arthorn Pieśni Wiatru w Wiecznym Gaju w Górach Klingi.', 'Dowiedz się czegoś o Księdze Kruka', '', '', '', 0),
(10981, 'plPL', 'Prywatna komora księcia Nexusa Shaffara', '', '', '', 'Wróć do Wizerunku dowódcy Ameera w Przystani Bash\'ira w Górach Klingi.', '', '', '', '', 0),
(10982, 'plPL', 'Oko Haramada', '', '', '', '', '', '', '', '', 0),
(10989, 'plPL', 'Mog\'dorg Sędziwy', 'Mog\'dorg Sędziwy czekać na ciebie na szczycie wieży. On kazać mi szukać kogoś takiego jak ty. Ty iść gadać z nim o mądrych rzeczach.$B$BIdź teraz, ale nikomu nie mówić. To tajemnica!', 'Porozmawiaj z Mog\'dorgiem Sędziwym na szczycie wieży, przy której stoi Chort, tuż za Krwawym Kręgiem w Górach Klingi.', '', '', '', '', '', '', 0),
(10990, 'plPL', 'Esencja orła', 'Księga Kruka mówi, że wyznawcy kruka pojmali duchy jego rywali i uwięzili je w kamiennych kapliczkach. Przy każdej postawiono strażnika, by wrogowie kruka nie próbowali ich uwolnić.$B$BPierwsza z kapliczek należy do orła; znajdziesz ją na wzgórzach na południe od Jeziora Jorune i na zachód od Warowni Kamieniołamaczy w Puszczy Terokkar.$B$BTablica mówi, że orzeł walczył dzielnie, ale uległ chmarze wrogów. Pancerz i wytrzymałość twojej postaci niedźwiedzia świetnie się nadają do tej walki.', 'Pokonaj Strażnika orła i zdobądź Esencję orła. Użyj Gwizdka na krogulca Arthorna, by przywołać Krogulca Arthorna i przekazać wieść o swoim sukcesie.$B$BJeśli zgubisz Gwizdek na krogulca Arthorna, wróć po nowy do Arthorn Pieśni Wiatru w Wiecznym Gaju.', '', 'Wróć do Krogulca Arthorna.', '', '', '', '', 0),
(10991, 'plPL', 'Esencja sokoła', '<Ptak mówi głosem Arthorn.>$B$BDrugim duchem spętanym przez wyznawców kruka był sokół.$B$BUjarzmiono go i uwięziono niedaleko Skettis, by w czasach swojej władzy kruczy kapłani mieli go stale przed oczami.$B$BKapliczkę sokoła znajdziesz na brzegu Jeziora Ere\'Noru, na północny zachód od Skettis.$B$BAby pokonać strażnika sokoła, musisz wykorzystać atuty samego sokoła. Dzięki szybkości i zwinności swojej kociej postaci pokonaj strażnika, zanim osiągnie pełnię sił!', 'Pokonaj Strażnika Sokoła i zdobądź Esencję sokoła. Użyj Gwizdka na krogulca Arthorna, by przywołać Krogulca Arthorna i przekazać wieść o swoim sukcesie.$B$BJeśli zgubisz Gwizdek na krogulca Arthorna, wróć po nowy do Arthorn Pieśni Wiatru w Wiecznym Gaju.', '', 'Wróć do Krogulca Arthorna.', '', '', '', '', 0),
(10992, 'plPL', 'Esencja jastrzębia', '<Zwraca się do ciebie głos Arthorn.>$B$BOstatnim i najsilniejszym z duchów, o których mówi Księga Kruka, jest duch jastrzębia. Uwięziono go daleko od Skettis, w kapliczce na odległej wyspie na południowy wschód od Auchindoun.$B$BSądzę, że ten opis najlepiej pasuje do wyspy, którą znamy jako Cypel Skrzydła Smutku.$B$BTablica opisuje strażnika jastrzębia jako niemal niewrażliwego na ptasie szpony. Porzuć ataki fizyczne i ściągnij na tego wroga gniew gwiazd. Nie powtórz błędu jastrzębia.', 'Pokonaj Strażnika jastrzębia i zanieś Esencję jastrzębia Arthorn Pieśni Wiatru w Wiecznym Gaju.', '', 'Wróć do Arthorn Pieśni Wiatru w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(10995, 'plPL', 'Grulloc ma dwie czaszki', 'Na wschodzie, na krańcu Kresu Smoków, leży Przeklęta Kotlina. Tam Grulloc, syn Gruula, snuje swoje tępe intrygi.$B$BSłyszałem, że podstępem skradziono mu jedną z jego rzeczy. Czy to twoja sprawka? Szkoda, że przy okazji nie zginął.$B$BJeśli mamy odzyskać wolność, musisz odebrać mu jego najcenniejszy skarb: smoczą czaszkę z czasów, gdy radował się, że jego ojciec wyrżnął Czarne Stado. Czaszkę zdobędziesz tylko w jeden sposób – pokonując go.', 'Zdobądź Smoczą czaszkę Grulloca.', '', 'Wróć do Mog\'dorga Sędziwego na szczycie wieży w Krwawym Kręgu w Górach Klingi.$B', '', '', '', '', 0),
(10996, 'plPL', 'Skrzynia skarbów Maggoca', 'Na Brzytwowej Grani, wyżej, na południowym wschodzie, patroluje Maggoc. Ojciec mianował go strażnikiem wschodniego pasma gór, a on uwielbia terroryzować każde stworzenie, które stanie mu na drodze.$B$BJako syn Gruula musi zniknąć, jeśli mój klan ma przetrwać. I tu wkraczasz ty.$B$BMaggoc zawsze nosi przy sobie skrzynię ze skarbami. Udowodnij mi, że zginął – przynieś mi jego cenną skrzynię. Cokolwiek w niej znajdziesz, możesz zatrzymać.', 'Zdobądź Skrzynię skarbów Maggoca.', '', 'Wróć do Mog\'dorga Sędziwego na szczycie wieży w Krwawym Kręgu w Górach Klingi.$B', '', '', '', '', 0),
(10998, 'plPL', 'Ponury grimoire', 'Został jeszcze jeden gronn do zabicia: Skulloc Młyn Dusz. Ukrywa się, ale jest sposób, by go wywabić.$B$BSzkolił go ogrzy czarnoksiężnik znany jako Vim\'gol Plugawy, a ty musisz zdobyć jego grimoire!$B$BVim\'gola przyzywa się, stając w jednym z ognistych pierścieni w jego kręgu. Kręgu Vim\'gola szukaj w górach na północnym wschodzie, niedaleko Strzaskanych Ostępów.$B$B$N, jeśli usłyszysz, że Vim\'gol mówi o tym, że rośnie, dopilnuj, by ktoś znów stanął w każdym z pięciu ognistych pierścieni i przerwał jego zaklęcie!', 'Zdobądź Plugawy grimoire Vim\'gola.', '', 'Wróć do Mog\'dorga Sędziwego na szczycie wieży przy Krwawym Kręgu w Górach Klingi.', '', '', '', '', 0),
(11000, 'plPL', 'Do Młyna Dusz', 'Grimoire jest kluczem do upadku Skulloca.$B$BOdczytaj na głos fragment księgi przy Kurhanie Młyna Dusz, by rozpocząć rytuał. Pojawi się przedmiot zwany Młynem Dusz, a także upiorne ofiary Skulloca, które będą próbowały go zniszczyć. Musisz je powstrzymywać na tyle długo, by zmusić Skulloca do pełnego wejścia w nasz świat.$B$BKurhan znajdziesz, idąc na północ przez Kanion Sztyletopaszczy po drugiej stronie Krwawego Kręgu. Leży po prawej stronie, przed Leżem Gruula.$B$BPrzynieś mi duszę Skulloca.', 'Zdobądź Duszę Skulloca.', '', 'Wróć do Mog\'dorga Sędziwego na szczycie wieży przy Krwawym Kręgu w Górach Klingi.', '', '', '', '', 0),
(11009, 'plPL', 'Ogrzy raj', 'Teraz, gdy $gwyzwoliłeś:wyzwoliłaś; nas z niewoli, możemy zacząć na nowo jednoczyć klany. To potrwa; stare urazy trudno przezwyciężyć.$B$BAle sprawa pilniejsza: musisz udać się do Ogri\'la, w niebiosach nad nami, na zachodzie. Musisz bronić tego miejsca, a także nas, przed siłami z góry, przed którymi dawniej chronili nas gronnowie: eterykami, demonami, a przede wszystkim Czarnym Stadem.$B$BGdy odnajdziesz ogrzy raj, zasięgnij rady Chu\'a\'lora, jak najlepiej postąpić.', 'Porozmawiaj z Chu\'a\'lorem w Ogri\'la w Górach Klingi.', '', '', '', '', '', '', 0),
(11010, 'plPL', 'Bombardowanie', 'Masz latającego wierzchowca... i co z tego! Myślisz, że potrafisz porządnie go wykorzystać?$B$BObóz Kuźniczy: Gniew i Obóz Kuźniczy: Groza, na północy i na południu, to dla mnie wrzód na tyłku, a do tego zagrożenie dla spokojnego Ogri\'la. Te wszystkie spaczone działa zestrzeliwują Podniebną Straż jak leci, więc nie możemy się tamtędy przedostać i załatwić sprawy.$B$BChcesz się wykazać? Weź te bomby i rozwal ich stosy amunicji. Tylko nie daj się przy tym zestrzelić!', 'Użyj Bomb Podniebnej Straży, by zniszczyć 15 stosów spaczonych kul armatnich.', '', 'Wróć do podniebnej sierżant Vanderlip w Posterunku Podniebnej Straży w Górach Klingi.', 'Zniszczone stosy spaczonych kul armatnich', '', '', '', 0),
(11022, 'plPL', 'Porozmawiaj z Mog\'dorgiem', '$GKrólu:Królowo; $N! Ty pogadać z Mog\'dorgiem Sędziwym, zanim ty odejść do Ogri\'la!', 'Porozmawiaj z Mog\'dorgiem Sędziwym. Stoi na szczycie wieży po wschodniej stronie Krwawego Kręgu w Górach Klingi.', '', '', '', '', '', '', 0),
(11023, 'plPL', 'Zbombarduj ich znowu!', 'Wciąż mamy kłopoty z tymi działami przeciwlotniczymi, $N.$B$BNie zrozum mnie źle – uważam, że ostatnim razem $gspisałeś:spisałaś; się znakomicie – ale to nie zmienia faktu, że te przeklęte demony uzupełniają zapasy amunicji szybciej, niż zdążymy je wysadzić. A to znaczy, że mamy piekielny kłopot z przerzuceniem tamtędy naszych ludzi, nie wspominając o zagrożeniu, jakie te demony stanowią dla Ogri\'la.$B$BCo ty na to? Chcesz spróbować jeszcze raz?', 'Użyj Bomb Podniebnej Straży, by zniszczyć 15 stosów spaczonych kul armatnich.', '', 'Wróć do podniebnej sierżant Vanderlip w Posterunku Podniebnej Straży w Górach Klingi.', 'Zniszczone stosy spaczonych kul armatnich', '', '', '', 0),
(11025, 'plPL', 'Kryształy', 'Odpowiednio przygotowane kryształy z tych gór przejawiają dziwne moce, na przykład jasność umysłu, którą odnaleźliśmy tu, w Ogri\'la.$B$BWszystkie stworzenia na szczytach gór pożądają kryształowych odłamków i wykorzystują je do własnych celów. Wokół nich wyrosła nawet cała gospodarka.$B$BAby nam pomóc, musisz najpierw poznać odłamki apeksisu. Przynieś mi kilka. Mają je tutejsze stworzenia, ale czasem można je też znaleźć tam, gdzie oprawcy wydobywają większe kryształy.', 'Zbierz 5 odłamków apeksisu.', '', 'Wróć do Chu\'a\'lora w Ogri\'la w Górach Klingi.', '', '', '', '', 0),
(11026, 'plPL', 'Wygnaj demony', 'Przybywasz w idealnym momencie, przyjacielu! Potrzebujemy pomocy. W zamian dostaniesz coś bardzo rzadkiego, co w ostatecznym rozrachunku pomoże nam obu.$B$BNie jesteśmy już brutalnym ogrem, ale pobliskie demony grożą, że zaleją nas i Podniebną Straż. Kłopot z demonami polega na tym, że po zabiciu od razu wracają w nowych ciałach!$B$BAle jeśli użyjesz tego kryształu, by przyzwać portal wygnania, to gdy zginą w jego pobliżu, ich esencje zostaną wciągnięte i odesłane tam, skąd przyszły!', 'Użyj Kryształu wygnania, by wygnać 15 demonów w Obozie Kuźniczym Gniew lub w Obozie Kuźniczym Groza.', '', 'Wróć do Kronka w Ogri\'la w Górach Klingi.', 'Wygnane demony', '', '', '', 0),
(11027, 'plPL', 'Ty mieć mroczna runa?', '', '', '', 'Wróć do Gahka w Górach Klingi.', '', '', '', '', 0),
(11030, 'plPL', 'Nasz chłopak chce być tropicielem Podniebnej Straży', '$N, mamy problem – mamy mnóstwo synów. A odkąd w pobliżu osiedliła się Podniebna Straż, nasi synowie mówią tylko o tym, żeby do niej wstąpić.$B$BJako dumny ojciec chcemy, żeby mieli wszelkie atuty, gdy będą się zgłaszać. Czy $gposzedłbyś:poszłabyś; do spaczonej kuźni kryształów w którymś z obozów kuźniczych na północy lub na południu i $gzdobył:zdobyła; magiczną flaszkę dla naszych synów? Nie przeoczysz ich zielonego dymu.$B$BChyba do jej zrobienia potrzeba dziesięciu odłamków apeksisu. Dalibyśmy ci odłamki, ale w tej chwili nie mamy żadnych.', 'Zdobądź Niestabilną flaszkę bestii.', '', 'Wróć do Torkusa w Ogri\'la w Górach Klingi.', '', '', '', '', 0),
(11036, 'plPL', 'Nieziemskie plony!', 'Pierwszy przyznam, że nie bardzo wiem, do czego ma służyć to zamówienie, ale instrukcje Rakietowodza Kadłubka były bardzo konkretne – tylko najlepsze owoce, zakonserwowane tak, by przetrwały długą podróż, i szczelnie zabezpieczone przed żywiołami.$B$BByły też inne wymagania: coś tam w stanie nieważkości, coś tam przy niskim ciśnieniu. Nie udaję, że to rozumiem, ale cena jest dobra, więc dostanie swoje superjedzenie. Zanieś mu tę skrzynkę do Strefy 52. Gdy przekroczysz granicę Burzy Otchłani, idź dalej drogą, aż zobaczysz miasto.', 'Zanieś Zakonserwowane owoce Rakietowodzowi Kadłubkowi w Strefie 52 w Burzy Otchłani.', '', '', '', '', '', '', 0),
(11040, 'plPL', 'Części dla Rakietowodza', 'Na palcach jednej ręki mogę policzyć, ile razy współpracowałam z goblinem. Znacznie częściej z nimi konkurujemy, ale gdy dostałam prośbę Rakietowodza Kadłubka, po prostu nie mogłam mu odmówić.$B$BTa skrzynia jest pełna części, których tu nie używam, a które rakietowódz może wykorzystać w swoim projekcie. Czy $gbyłbyś tak miły:byłabyś tak miła;, by je dostarczyć, jeśli idziesz do Strefy 52?$B$BKto wie, może porządne gnomie części uchronią jego dzieło przed wybuchem!', 'Zanieś Części zamienne Bossi Rakietowodzowi Kadłubkowi w Strefie 52 w Burzy Otchłani.', '', '', '', '', '', '', 0),
(11043, 'plPL', 'Lepszy gryf', 'Słyszałem, że krasnoludy z Dzikiego Młota utrzymują gniazdo gryfów w swojej warowni na południu Doliny Cienistego Księżyca. Jeśli się tam wybierasz, porozmawiasz z nimi w moim imieniu? Mam kilka pomysłów, jak ulepszyć ich gryfy!$B$BPo co poprzestawać na opancerzeniu, skoro można dołożyć wysokościomierz, lusterko wsteczne i rakietę? Wyobraź sobie, jak szybko można by lecieć z takim cackiem przypiętym do grzbietu gryfa! Nazwę to TurboGryf 8000!', 'Porozmawiaj z Brunnem Płomiennobrodym w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(11047, 'plPL', 'Prośba ucznia', 'Jako uczeń mistrza wiwern muszę między innymi dbać o zwierzęta, gdy nie latają. Kłopot w tym, że mamy ich tu tak mało, że prawie żadne nie ma chwili odpoczynku.$B$BBoję się, że zajeździmy je wszystkie na śmierć, jeśli nie dostaniemy nowych. W Wiosce Cienistego Księżyca, w zachodniej części Doliny Cienistego Księżyca, jest duża stajnia. Dama Dzikogrzywa nadzoruje tam opiekę nad wiwernami i ich szkolenie.$B$BCzy porozmawiasz z nią w naszym imieniu i opowiesz jej o naszym położeniu?', 'Porozmawiaj z Damą Dzikogrzywą w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(11051, 'plPL', 'Wygnaj więcej demonów', 'Jeśli znamy demony – a znamy, bo dokładnie je zbadaliśmy – to już w pocie czoła naprawiają wszelkie szkody wyrządzone ich cennemu transporterowi.$B$BJeśli więc chcesz mieć szansę na kolejną mroczną runę, zabierz tam znowu nasz kryształ wygnania i wybij więcej demonów. Poza tym chcesz nam pomóc zmniejszyć zagrożenie ze strony demonów, prawda?$B$BPowiedzieliśmy „szansę”, bo nasz sposób daje różne wyniki. Możesz dostać mroczną runę, a możesz dostać coś zupełnie innego.', 'Użyj Kryształu wygnania, by wygnać 15 demonów w Obozie Kuźniczym Gniew lub w Obozie Kuźniczym Groza.', '', 'Wróć do Kronka w Ogri\'la w Górach Klingi.', 'Wygnane demony', '', '', '', 0),
(11057, 'plPL', 'Kłopoty na dole', 'Doceniamy twój zapał do pomocy tu, w Ogri\'la, $N. Zanim jednak przyjmiemy twoją pomoc, mamy do ciebie prośbę.$B$BNa dole nasi bracia są niewolnikami Synów Gruula. Proszę, porozmawiaj z Mog\'dorgiem Sędziwym, który przewodzi ogrzemu ruchowi oporu przeciw ich panom, gronnom.$B$BSzukaj go na szczycie wieży po wschodniej stronie areny Krwawego Kręgu.', 'Porozmawiaj z Mog\'dorgiem Sędziwym na szczycie jednej z wież tuż za Krwawym Kręgiem w Górach Klingi.$B', '', '', '', '', '', '', 0),
(11058, 'plPL', 'Relikt apeksisu', 'Dawno temu żyła tu wymarła już sekta arakkoa zwana Apeksis. Pozostałości jej cywilizacji wciąż tu są. Nazywamy je reliktami apeksisu.$B$BWiemy o nich tyle, że odpowiednio użyte zsyłają dobrodziejstwo. Każdy relikt pokazuje sekwencję kolorów; gdy wciska się kryształy we właściwej kolejności, prowadzi ona przez serię poziomów, z których każdy jest trudniejszy od poprzedniego.$B$BDo zasilenia reliktu potrzebny jest odłamek apeksisu. Wróć, gdy dostąpisz wglądu, jaki dają wibracje apeksisu.', 'Uzyskaj Wibracje apeksisu dzięki reliktowi apeksisu.', 'Wibracje apeksisu uzyskane', 'Wróć do Chu\'a\'lora w Ogri\'la w Górach Klingi.', '', '', '', '', 0),
(11059, 'plPL', 'Strażnik monumentu', '$GOdkryłeś:Odkryłaś;, jak używać reliktów dla jednej osoby, ale jak być może $gzauważyłeś:zauważyłaś;, istnieją też większe, wokół których tamte stoją.$B$BTe większe monumenty apeksisu działają bardzo podobnie, ale do aktywacji potrzebują znacznie więcej odłamków apeksisu, a do obsługi – czterech osób.$B$BBardziej niepokoją nas strażnicy, których przyzywa się przy ich użyciu. Te kryształowe konstrukty dawno temu zwróciły się przeciw swoim panom arakkoa, a teraz zagrażają Ogri\'la.$B$BProsimy, zniszcz jednego i przynieś nam dowód.', 'Zdobądź Głowę strażnika apeksisu.', '', 'Wróć do Chu\'a\'lora w Ogri\'la w Górach Klingi.', '', '', '', '', 0),
(11060, 'plPL', 'Mroczna runa z kryształowej kuźni', '', '', '', 'Wróć do Gahka w Górach Klingi.', '', '', '', '', 0),
(11061, 'plPL', 'Ojcowski obowiązek', 'Co do tej drugiej magicznej flaszki, można ją zdobyć tylko w jednym miejscu: na Przystani Bash\'ira. To baza eteryków, a oni nie przepadają za obcymi, więc może być trochę niebezpiecznie.$B$BPytasz, gdzie jest Przystań Bash\'ira? Jeśli wsiądziesz na latającego wierzchowca i polecisz na północ, lekko na północny wschód, daleko za Obóz Kuźniczy Gniew, w końcu ją zobaczysz. Sama kuźnia kryształów Bash\'ira stoi w północno-wschodnim rogu przystani.$B$BDziękujemy, że to dla nas robisz, $N. Dla naszych synów to będzie znaczyło cały świat!', 'Zdobądź dla niego Niestabilną flaszkę czarownika.', '', 'Wróć do Torkusa w Ogri\'la w Górach Klingi.', '', '', '', '', 0),
(11062, 'plPL', 'Posterunek Podniebnej Straży', '$N, zastanawialiśmy się, czy nie zechcesz odwiedzić naszych przyjaciół w Posterunku Podniebnej Straży, tuż na północ stąd?$B$BPodniebny dowódca Keller i jego Podniebna Straż prowadzą tu misje dla naszego wspólnego bezpieczeństwa, a on poprosił nas, byśmy przysyłali mu każdego, kto naszym zdaniem świetnie się sprawdzi w pomocy.$B$BA to właśnie ty!$B$BUdaj się tam jak najszybciej i proszę, przekaż mu nasze pozdrowienia.', 'Porozmawiaj z podniebnym dowódcą Kellerem w Posterunku Podniebnej Straży w Górach Klingi.', '', '', '', '', '', '', 0),
(11065, 'plPL', 'Złap kilka płaszczek eteru!', 'Chcesz pomóc Podniebnej Straży i Ogri\'la?$B$BTylko mnie wysłuchaj, zanim sobie pójdziesz, $gprzystojniaku:ślicznotko;. Potrzebujemy nowych wierzchowców! Bombardowania i misje na Przystań Bash\'ira dały się naszym wierzchowcom mocno we znaki.$B$BPłaszczki eteru, które latają wokół Szczytu Wiru i Kryształowego Grzbietu na północnym wschodzie, wyglądają na całkiem odpowiednie. Nie musisz ich nawet tu przyprowadzać, choć byłoby miło. Wystarczy je ujeździć i spętać, a my potem je wytropimy.$B$BMyślisz, że złapiesz mi kilka?', 'Użyj Lassa, by schwytać 5 płaszczek eteru.', '', 'Wróć do Khatie z Podniebnej Straży w Posterunku Podniebnej Straży w Górach Klingi.', 'Schwytane płaszczki eteru', '', '', '', 0),
(11066, 'plPL', 'Złap więcej płaszczek eteru!', 'Mam nadzieję, że $gjesteś gotów:jesteś gotowa; pomóc nam złapać jeszcze więcej płaszczek eteru! Z tego, co widzę, masz do liny wrodzony talent! I to w dobrej sprawie, bo nie tylko dostajemy świeże wierzchowce, ale też łatwiej nam chronić Ogri\'la, co ogry bardzo doceniają.$B$BPamiętaj, płaszczki eteru latają wokół Szczytu Wiru i Kryształowego Grzbietu na północnym wschodzie.$B$BMyślisz, że złapiesz mi jeszcze kilka?', 'Użyj Lassa, by schwytać 5 płaszczek eteru.', '', 'Wróć do Khatie z Podniebnej Straży w Posterunku Podniebnej Straży w Górach Klingi.', 'Schwytane płaszczki eteru', '', '', '', 0),
(11078, 'plPL', 'Władać przestworzami', 'Latając tu i tam, na pewno $gzauważyłeś:zauważyłaś; smoki w górze. Mam nadzieję, że nie $gpadłeś:padłaś; ofiarą ich wściekłości. Pomóż nam z tym skończyć, $N!$B$BNad tym tarasem panują Rivendark i Obsidia, a nad tamtym tarasem na północnym wschodzie niebo należy do Insidiona i Furioskrzydłego. Każde z nich ma grzędę na swoim terytorium. Zastanawiam się, czy ty i twoi przyjaciele wybierzecie się do jednej z nich, $gchłopcze:dziewczyno;, rozbijecie jajo i zwabicie smoka na dół.$B$BPrzynieś mi kilka zębów na dowód. Tu chodzi o panowanie w przestworzach – albo oni, albo my.', 'Zdobądź Smocze zęby.', '', 'Wróć do podniebnego dowódcy Kellera w Posterunku Podniebnej Straży w Górach Klingi.', '', '', '', '', 0),
(11079, 'plPL', 'Spaczony bicz dla Gahka', 'Gahk myśleć, że czasem być mądrym to głupie. Gahk nie chcieć myśleć. Ja chcieć, żeby $r rozwalić duże demony!$B$BOne mieć wodzów, a wszyscy wodzowie mieć bicze, żeby bić małe demony. Ty przynieść Gahk bicz!$B$BTy wyzwać wodza demonów w obozach kuźniczych przy płonący, zielony pryzmat spaczonego kryształu. Użyć dużo odłamków apeksisu, żeby oni przyjść. Oni nazywać się Galvanoth, Braxxus, Zarcsin i Spopielacz Mo\'arg.', 'Zdobądź Spaczony bicz.', '', 'Wróć do Gahka w Ogri\'la w Górach Klingi.', '', '', '', '', 0),
(11080, 'plPL', 'Emanacja reliktu', 'Skoro już $gpoczułeś:poczułaś; oświecające wibracje reliktów apeksisu, pora, byś $gpogłębił:pogłębiła; wiedzę o ich działaniu. Bardzo chcemy skorzystać z twoich obserwacji!$B$BW miarę jak będziesz coraz lepiej dostrajać się do reliktów, osiągniesz wyższy poziom wiedzy. To uznanie przyjdzie w postaci emanacji z reliktu.$B$BWróć do nas, gdy uzyskasz taką emanację.', 'Uzyskaj Emanacje apeksisu dzięki reliktowi apeksisu.', 'Emanacje apeksisu uzyskane', 'Wróć do Chu\'a\'lora w Ogri\'la w Górach Klingi.', '', '', '', '', 0),
(11091, 'plPL', 'Specjalne podziękowanie', 'Zaszczycasz nas swoimi staraniami na naszą rzecz. A teraz jest ktoś, kogo chcielibyśmy ci przedstawić.$B$BJho\'nass to nasz najbardziej zaufany kwatermistrz. Prowadzi zapas towarów, które sprzedajemy tylko najbardziej oddanym przyjaciołom Ogri\'la.$B$BTy jesteś $gjednym:jedną; z nich, $N.$B$BGdy znajdziesz chwilę, idź z nim porozmawiać. O ile wiemy, przygotował dla ciebie drobiazg w dowód naszej wdzięczności.', 'Porozmawiaj z Jho\'nassem w Ogri\'la w Górach Klingi.', '', '', '', '', '', '', 0),
(11102, 'plPL', 'Bombardowanie', 'Umiesz latać jako wrona... i co z tego! $GZniszczyłeś:Zniszczyłaś; kiedyś coś na ziemi w trakcie lotu? Chcesz spróbować?$B$BObóz Kuźniczy: Gniew i Obóz Kuźniczy: Groza, na północy i na południu, to dla mnie wrzód na tyłku, a do tego zagrożenie dla spokojnego Ogri\'la. Te wszystkie spaczone działa zestrzeliwują Podniebną Straż jak leci, więc nie możemy się tamtędy przedostać i załatwić sprawy.$B$BChcesz się wykazać? Weź te bomby i rozwal ich stosy amunicji. Tylko nie daj się przy tym zestrzelić!', 'Użyj Bomb Podniebnej Straży, by zniszczyć 15 stosów spaczonych kul armatnich.', '', 'Wróć do podniebnej sierżant Vanderlip w Posterunku Podniebnej Straży w Górach Klingi.', 'Zniszczone stosy spaczonych kul armatnich', '', '', '', 0),
(11119, 'plPL', 'Szturm na Przystań Bash\'ira!', 'Siemasz, $gchłopaczku:dziewczyno;! Masz ochotę na trochę zabawy?$B$BCo parę godzin moi eterotechnicy przypuszczają szturm na Przystań Bash\'ira, daleko na północnym wschodzie Gór Klingi. Mówią, że tylko „badają” kuźnię kryształów Bash\'ira, ale to szturm i nie ma co do tego dwóch zdań. Korzystamy z kuźni kryształów, żeby uzupełniać zapasy, a nadwyżki zawsze da się sprzedać.$B$BZejdź na lądowisko i porozmawiaj z uczniem eterotechnika. Powie ci, kiedy wyrusza następna misja.', 'Porozmawiaj z uczniem eterotechnika w Posterunku Podniebnej Straży w Górach Klingi.', '', '', '', '', '', '', 0),
(11513, 'plPL', 'Przechwycenie ogniw many', 'Mam plan, jak zdobyć źródło energii dość silne, by stworzyć nasz portal.$B$BSiły eteryków z Przystani Bash\'ira, na szczytach północno-zachodnich Gór Klingi, przemycają ogniwa many z Twierdzy Burz i przewożą je do Słonecznej Studni dla Kael\'thasa.$B$BUkryli ogniwa, ale jest sposób, by je odnaleźć: eterycy noszą urządzenia fazowe, dzięki którym zobaczysz przemycane towary.$B$BStrzeż się tylko fazowych żmijów, którymi strzegą ogniw many.', 'Zdobądź 10 przemycanych ogniw many i zanieś je egzarsze Nasuunowi na Tarasie Światła w Shattrath.', '', 'Wróć do egzarchy Nasuuna w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(11514, 'plPL', 'Podtrzymanie portalu do Słonecznej Studni', 'Musimy podtrzymywać zasilanie naszego portalu, inaczej się zawali. Ogniwa many ukryte przez eteryków z Przystani Bash\'ira wciąż będą nam służyć. Przystań leży na szczytach północno-zachodniego krańca Gór Klingi, daleko na północy.$B$BPamiętaj: zdobądź urządzenie fazowe od któregoś z eteryków, a potem użyj go, by odnaleźć przemycane towary.$B$BStrzeż się tylko fazowych żmijów, którymi strzegą ogniw many.', 'Zdobądź 10 przemycanych ogniw many i zanieś je egzarsze Nasuunowi na Tarasie Światła w Shattrath.', '', 'Wróć do egzarchy Nasuuna w Dolnym Mieście w Shattrath.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(10455, 'plPL', 'Szybko ci poszło. Na pewno $gzabiłeś:zabiłaś; tyle, ile trzeba było?$B$BŚwietnie. Jest jeszcze coś, w czym możesz nam pomóc, jeśli zechcesz.', 0),
(10456, 'plPL', 'Dobrze. Zobaczę, czy uda mi się zrobić z tych ogonów coś pożytecznego.$B$BHorda na pewno znajdzie sposób, by uzupełnić swoją watahę, ale na razie możemy odetchnąć nieco swobodniej.$B$B$N, jeśli zechcesz, jest jeszcze coś, o co chciałabym cię poprosić w obronie Sylvanaar i Żywego Gaju.', 0),
(10457, 'plPL', 'Teraz, gdy $gwzmocniłeś:wzmocniłaś; obronę gaju, czuję się dużo bezpieczniej.$B$B$gZasłużyłeś:Zasłużyłaś; na naszą wdzięczność i uznanie, $N.$B$BAle właśnie przyszło mi do głowy, że jest jeszcze coś, czym musimy się zająć!', 0),
(10486, 'plPL', 'Poszło szybciej, niż myślałem. Na pewno $gzabiłeś:zabiłaś; tyle, ile trzeba było?$B$BNiech będzie. Jest jeszcze coś, w czym masz nam pomóc. Coś znacznie ważniejszego.', 0),
(10487, 'plPL', 'Nie tylko $gosłabiłeś:osłabiłaś; ich obronę, ale jeszcze użyjemy tego pyłu, by wzmocnić naszą własną obronę przed Przymierzem.', 0),
(10488, 'plPL', 'Teraz, gdy $gwzmocniłeś:wzmocniłaś; wilki i obronę Poszarpanej Grani, może zdołamy znów skupić uwagę na groźniejszych sprawach, na przykład na ograch?$B$BDobrze się tu $gspisałeś:spisałaś;. Przydałby się nam ktoś tak zdolny jak ty, jeśli zdecydujesz się zostać.$B$BCokolwiek postanowisz, $gzasłużyłeś:zasłużyłaś; na mój szacunek i wdzięczność.', 0),
(10489, 'plPL', 'Pień silnokonarego głębokorzenia! $gŚciąłeś:Ścięłaś; go w pojedynkę?$B$BZałożę się, że tak. Wiesz, razem z Rexxarem szukamy $gmłodego, silnego:młodej, silnej; osoby takiej jak ty, żeby pomogła nam tutaj, zwłaszcza z ogrami, z którymi ciągle mamy kłopoty. Pamiętaj, żeby jeszcze do mnie wrócić w tej sprawie.$B$BTen pień to niezbity dowód, a więc $gprzyszedłeś:przyszłaś; po nagrodę, a nie słuchać mojego gadania. Proszę, wybierz sobie coś.', 0),
(10502, 'plPL', 'To dobry pierwszy krok, by zabezpieczyć Sylvanaar i gaj.$B$BGdy ich ogrów jest mniej, Krwawe Młoty dwa razy się zastanowią, zanim nas zaatakują.$B$BGdyby tylko był to jedyny klan ogrów, którym musimy się przejmować.', 0),
(10503, 'plPL', 'To dobry pierwszy krok, by umocnić naszą pozycję wobec ogrów.$B$BGdy ich szeregi się przerzedziły, Klan Ostrza dwa razy się zastanowi, zanim spróbuje odbić Warownię Władców Gromu.$B$BGdyby tylko był to jedyny klan ogrów, którym musimy się przejmować.', 0),
(10504, 'plPL', 'Twoje działania przeciw obu klanom ogrów, Krwawym Młotom i Klanowi Ostrza, bardzo przysłużyły się przyszłości Sylvanaar. Nie zamierzamy sięgać dalej niż ten skrawek ziemi, który zastaliśmy pusty, ale nie będziemy też tolerować tych, którzy chcą nas zniszczyć.$B$BDobrze nam $gsłużyłeś:służyłaś;, więc chcę cię za to nagrodzić uznaniem Przymierza.', 0),
(10505, 'plPL', 'Twoje działania przeciw obu klanom ogrów, Klanowi Ostrza i Krwawym Młotom, bardzo przysłużyły się przyszłości Warowni Władców Gromu. Nie będziemy tolerować tych, którzy stają na drodze naszemu przeznaczeniu.$B$BDobrze się $gspisałeś:spisałaś;, niszcząc te ogry, więc chcę cię nagrodzić uznaniem Hordy.', 0),
(10506, 'plPL', 'Cieszę się, że zadziałało. Im mniej stworzeń Natury musi zginąć, tym lepiej.$B$BTyle już dla nas $gzrobiłeś:zrobiłaś;, że muszę przyznać, iż coraz bardziej lubię twoje towarzystwo.$B$BUważaj na siebie, $N.', 0),
(10510, 'plPL', 'Och, na oko to piękne okazy. Nie mogę się doczekać, aż rozpakuję narzędzia i porządnie im się przyjrzę!$B$BDziękuję!', 0),
(10511, 'plPL', 'Co to za smród? O nie, tylko mi nie mów, że to to ogrze piwo?!$B$BAż się boję tego spróbować. A, co mi tam! Do dna!', 0),
(10512, 'plPL', 'Ha, ha, ha! Tak myślałem. Ogry chyba wypiją wszystko.$B$BGłupie jak but, co do jednego!$B$BCóż, muszę przyznać, że choć nie dostałem swojego piwa, dzięki tobie mój urlop zaczął się wspaniale.$B$BWiesz co... mamy tu mnóstwo rzeczy, których tak naprawdę nie potrzebujemy. Mogę ci coś zaproponować?', 0),
(10516, 'plPL', 'Mam teraz wobec ciebie wielki dług, bo $gpomogłeś:pomogłaś; mi odzyskać honor. Ale nasza praca tutaj jeszcze się nie skończyła.', 0),
(10517, 'plPL', 'Doskonale. Z pewnością nie brakuje ci pomysłowości.$B$BCiekawe więc, czy $gmógłbyś:mogłabyś; zrobić jeszcze jedną rzecz dla mnie i dla Sylvanaar?', 0),
(10518, 'plPL', 'Hełm Gurna Grubnosha i sztandar Klanu Ostrza?$B$BBardzo sprytny plan wymyśliliście z obrończynią.$B$BSkupiając uwagę klanu Krwawych Młotów na Warowni Klanu Ostrza, zdjęliśmy z nas presję, którą zaczynali tu na nas wywierać.$B$BProszę, $N, przyjmij skromny dar od Sylvanaar.', 0),
(10524, 'plPL', 'Nie wierzę własnym oczom! Jeśli to jakaś sztuczka, zedrę ci mięso z kości!$B$BSzybko, daj mi obejrzeć te bezcenne artefakty, zanim połamiesz je swoimi niezdarnymi łapami.', 0),
(10525, 'plPL', 'W głębi Kopalni Draenetystu? Klan Krwawych Młotów musiał go ukraść ogrom Klanu Ostrza.$B$BPfff! To za daleko... zbyt głęboko na ziemiach Krwawych Młotów, żebym mogła się tam wybrać.$B$BAle ty. Ty znasz drogę. Pójdziesz tam zamiast mnie!', 0),
(10526, 'plPL', 'Teraz jestem pod wrażeniem! Masz pojęcie, ilu innych zginęło, próbując odzyskać te wszystkie relikwie?$B$BMamy szczęście, że z nami pracujesz, $N. Nawet jeśli jesteś trochę $gpowolny:powolna;.$B$BPozwól, że nagrodzę twoje oddanie naszej sprawie. Wybierz, ale wybierz mądrze. Gdy skończysz, przekażę artefakty, by ułagodzić duchy Warowni Władców Gromu.', 0),
(10542, 'plPL', 'Tak, o tym właśnie mówi T\'chali! Chociaż ja nie wiedzieć, co te ogry tam włożyły – to nie jest tytoń T\'chalego, co ja czuć w fajce.$B$BNieważne, T\'chali jest szczęśliwy. Tak szczęśliwy, że nawet poprosi cię o coś jeszcze.', 0),
(10543, 'plPL', 'T\'chali się cieszy, że Korgaah i Grimnok Zrodzony w Boju wąchają kwiatki od spodu, tak samo jak on.$B$BAle pragnienie zemsty T\'chalego nie jest ugaszone. Musisz zrobić jeszcze jedną rzecz!', 0),
(10544, 'plPL', 'Ha, ha, ha, zemsta jest słodka!$B$BAle T\'chali widzi, że ty chcesz ruszać dalej, jak już pomóc mu się zemścić. Rozumiem cię, mon... życie jest dla żywych.$B$BWiesz co? T\'chali ma jeszcze w swoim grobie dużo różnych skarbów. Wybierz sobie, co ci się najbardziej podoba!', 0),
(10545, 'plPL', 'To dobre wieści! To piwo się przyda przy tym, o co T\'chali cię zaraz poprosi.', 0),
(10555, 'plPL', 'Kartkując porysowane notatki i pajęcze pismo arakkoa Lashh\'an, znajdujesz stronę z piktogramem przedstawiającym kręgi mocy, które $gwidziałeś:widziałaś; w Zasłonie Lashh.', 0),
(10556, 'plPL', 'Nie wiem, co powiedzieć. To zaklęcie jest bardzo dziwne. To nie zwykłe przyzwanie ani zaklęcie, tylko coś w rodzaju zaklęcia obcowania albo porozumiewania się.$B$BNie wiem, co o tym myśleć, $N. Będę musiała to jeszcze przemyśleć.$B$BW każdym razie dziękuję za pomoc! Prędzej czy później na pewno to rozgryzę.$B', 0),
(10557, 'plPL', 'Łał, udało ci się! I ani jednego siniaka czy otwartego złamania! Widzisz, mówiłem, że wszystko się uda!$B$BOto twoja zapłata, $N. Uwzględniłem w niej koszty leczenia, a ich nie potrzebujesz... więc to premia dla ciebie!', 0),
(10565, 'plPL', 'Ach, patrz, jak lśni! Muszę to natychmiast wypróbować.', 0),
(10566, 'plPL', 'Te informacje bardzo się przydadzą, $N. Dopracuję ten projekt i zobaczę, czy nie da się rozszerzyć jego zastosowań.', 0),
(10567, 'plPL', 'Masz go!$B$BDzięki temu wisiorowi będę mógł dostroić cię do arakkoa z Grishnath tak, byś $grozumiał:rozumiała; ich mowę.$B$BW ten sposób możemy lepiej poznać arakkoa i naturę Kruka. Będę potrzebował do tego twojej pomocy.', 0),
(10580, 'plPL', 'SYLVANAAR? DOWÓDCA NIEBOCIEŃ?$B$BNIE DA SIĘ TEGO OBLICZYĆ!$B$BODSUŃ SIĘ, BO PUSZCZĘ CI GŁOŚNE DŹWIĘKI!', 0),
(10581, 'plPL', 'No dobrze, chcesz się na coś przydać? Świetnie, mam w sam raz zadanie, w którym możesz się wykazać.$B$BChyba ci się spodoba.', 0),
(10584, 'plPL', 'Świetnie! Z całą tą odzyskaną mocą utrzymamy maszyny w ruchu przynajmniej przez jakiś czas.$B$BKondensatorium zefirium pożera prąd jak smok!$B$BMam nadzieję, że te elektromentale nie sprawiły ci zbyt wielu kłopotów. Mam dla ciebie jeszcze jedno zadanie i przeczuwam, że będzie trochę bardziej niebezpieczne.', 0),
(10594, 'plPL', 'Och, to niezwykłe! Nie miałem pojęcia... zupełnie jakby te kryształy były żywe.$B$BCiekawe, czy łączy je jakiś rodzaj symbiozy ze smokowcami Otchłani?$B$BDziękuję, dziękuję! Musisz przyjąć coś z mojej kolekcji drobiazgów, w których za nic w świecie bym się nie pokazał.$B$BAle na tobie któryś może dobrze wyglądać.', 0),
(10607, 'plPL', 'To naprawdę niepokojące. Arakkoa długo żyli w pokoju. Ten kult Kruka był niczym więcej niż zbiorowiskiem odmieńców i szaleńców.$B$BAle ich moc wzrosła, tego nie możemy lekceważyć. Może w tym Kruku kryje się coś więcej, niż wiemy.', 0),
(10608, 'plPL', 'I dobrze, że się ich pozbyliśmy, ot co. Obrzydliwe stworzenia!$B$BSkoro więc na pewno $gwytępiłeś:wytępiłaś; te szkodniki, mam dla ciebie mały projekt badawczy. Chyba ci się spodoba.', 0),
(10609, 'plPL', 'Nie masz pojęcia, jak ważne mogą być te badania. Dziękuję!$B$BCiekawie będzie zgłębić te esencje. Szczególnie chcę sprawdzić, czy działanie Otchłani, które zmieniło jaja czarnych smoków w jaja smoków Otchłani, przyniosło jakieś dodatkowe korzyści dla moich badań.$B$BWłaściwie myślę, że to ty $gpowinieneś:powinnaś; pierwszy wypróbować zalety mojej małej mikstury. Proszę, weź te wstępne próbki i użyj ich, kiedy zajdzie potrzeba.', 0),
(10614, 'plPL', 'Co cię sprowadza do naszej wioski?', 0),
(10615, 'plPL', 'Ach tak, Dertrok. Krótko rozmawialiśmy o arakkoa. Muszę przyznać, że nasze... zainteresowania nimi znacznie się różnią.', 0),
(10617, 'plPL', 'Dobre kokony. Widzę, że $gnabrałeś:nabrałaś; wprawy w ich zbieraniu.$B$BPróbowaliśmy hodować własne larwy jedwabnoskrzydłych, ale niestety małe nie dają dość jedwabiu, żeby się nam przydał.', 0),
(10618, 'plPL', 'Dziękuję, $N. Wykorzystamy je szybciej, niż myślisz.', 0),
(10620, 'plPL', 'Całkiem nieźle jak na żółtodzioba. Okazuje się, że mamy małą grupkę jajogłowych, którzy chcą iść na północ i „poobserwować” eteryczne istoty i ich technikę. Będą zachwyceni, gdy się dowiedzą, że $goczyściłeś:oczyściłaś; im drogę.$B$BMasz, weź trochę tego. Nie mamy tego wiele, ale może kiedyś ci się przydadzą.', 0),
(10632, 'plPL', 'Dobra robota, $gmłody:młoda;. Cały ten trud jest wart zachodu, jeśli dzięki tobie ocaleje choćby jeden z moich żołnierzy.$B$BMyślę, że i ty $gpowinieneś:powinnaś; coś mieć z twojego potu i łez. Skoro niedługo dostaniemy nową partię broni, może weźmiesz jedną z moich?', 0),
(10657, 'plPL', 'Hura, zadziałało! Szczerze mówiąc, nie byłem pewien... Wyliczyłem dwadzieścia trzy przecinek siedemdziesiąt dwa procent szans, że przy trzecim uderzeniu się zapadniesz.$B$B<Toshley uśmiecha się niewinnie.>$B$BSkoro już wiemy, że sfera działa, nie powinniśmy mieć kłopotu z zaspokojeniem potrzeb energetycznych Kondensatorium zefirium. No, o ile znajdziemy więcej ochotników, którzy pójdą tam dać się porazić.$B$BTak czy inaczej, $gprzetarłeś:przetarłaś; nam szlak i należy ci się coś w zamian!', 0),
(10671, 'plPL', 'Powinny się nadać. Ale śmierdzą, co?$B$BMam nadzieję, że było warto... Cieszę się tylko, że to ty to $gzbierałeś:zbierałaś;, a nie ja!', 0),
(10674, 'plPL', 'Hej! Chwileczkę, do licha!!$B$BTo nie wygląda dobrze...', 0),
(10675, 'plPL', 'Dobrze mu tak! Dziękuję, że $gpołożyłeś:położyłaś; kres temu makabrycznemu wypaczaniu magii i techniki.$B$BJako prawdziwemu bohaterowi wszystkich gnomów niniejszym przekazuję ci nasz najwyższy zaszczyt... kilka przetworników mocy i dowolną rzecz spośród tych do wyboru.$B$BWiem, że zrobisz z nich dobry użytek!', 0),
(10682, 'plPL', 'CO?! Odprawili cię i odrzucili nasze propozycje bez zastanowienia?$B$BTo oburzające! Przychodzimy do nich w dobrej wierze, a oni cię odsyłają, nawet nie próbując dojść do kompromisu?$B$BNo, to się jeszcze okaże!', 0),
(10690, 'plPL', 'Niewiarygodne. $GZabiłeś:Zabiłaś; Remę w pojedynkę?$B$BPo twoim wyglądzie powiedziałbym, że $gdałbyś:dałabyś; radę. Wiesz, szukamy $gmłodego, silnego:młodej, silnej; osoby takiej jak ty, żeby pomogła nam tutaj, zwłaszcza z ogrami, z którymi ciągle mamy kłopoty. Pamiętaj, żeby jeszcze do mnie wrócić w tej sprawie.$B$BCóż, bez wątpienia $gzasłużyłeś:zasłużyłaś; na nagrodę, którą wyznaczyłem na tym liście gończym.$B$BProszę, wybierz sobie coś.', 0),
(10709, 'plPL', 'A więc mój ojciec jednak żyje. Nie spodziewałem się, że mi wybaczy – nigdy nie było to w jego stylu. Ale miałem nadzieję, że lata przytępiły gniew, który musiał czuć, gdy odszedłem.$B$BTrzydzieści lat temu opuściłem Mok\'Nathalów, by podążyć za Hordą do Azeroth. Leoroxx był temu stanowczo przeciwny, ale przecież nigdy nie dał mi powodu, żebym został. Mimo to liczyłem na lepsze powitanie.$B$BChciał mieć za syna Mok\'Nathala i ma go teraz, nawet jeśli nie chce tego przyznać.$B$BMuszę otworzyć mu oczy.', 0),
(10710, 'plPL', 'Łał! Znowu $gprzeżyłeś:przeżyłaś;! Jestem o wiele lepszym inżynierem, niż sam myślałem!$B$BOto twoja zapłata! I zajrzyj do mnie później... Będę mieć kolejne eksperymenty, do których będą potrzebne kolejne króliki doświadczalne!', 0),
(10711, 'plPL', 'O rany! Już $gwróciłeś:wróciłaś;! Widziałem, jak startujesz – $gwystrzeliłeś:wystrzeliłaś; w górę jak rakieta! Byłem pewien, że po takim locie zrośnięcie połamanych nóg zajmie co najmniej miesiąc rekonwalescencji! Jesteś $gtwardy, odważny i lekkomyślny:twarda, odważna i lekkomyślna;! Ale przede wszystkim... $godważny:odważna;!', 0),
(10712, 'plPL', 'Och, $gzrobiłeś:zrobiłaś; odczyty wiatrowskazem Otchłani? Wspaniale! Dane z tego instrumentu – w połączeniu z moimi pomiarami magii druidów – przyniosą obfite owoce!$B$BOch, zastosowania przejdą najśmielsze wyobrażenia, zapewniam cię!', 0),
(10713, 'plPL', 'Dziękuję, $N.$B$BZadbamy o to, by zwierzyna szybko się odrodziła, ale odrastanie drzew, zwłaszcza w naturalny sposób, to proces o wiele bardziej czasochłonny.', 0),
(10714, 'plPL', '<Duch siada na ramieniu Rexxara, a Rexxar uważnie słucha.>$B$BA więc za poczynaniami ogrów stoją synowie Gruula. Rozkazują ogrom Krwawych Młotów zniszczyć Mok\'Nathalów, by zyskać ich łaskę.', 0),
(10715, 'plPL', 'Doskonale. Proste, choć przyziemne zadanie zostało wykonane. A teraz daj mi gruczoły, a ja zajmę się trudniejszą częścią.', 0),
(10716, 'plPL', 'Cieszę się, że $gprzeżyłeś:przeżyłaś;! Jesteś $gpierwszy:pierwsza;!', 0),
(10717, 'plPL', 'Och, wyglądają wspaniale. Ci kultyści naprawdę mają oko do rzemiosła.$B$BSzkoda tylko, że źle je wykorzystują.$B$BA skoro mamy już sieci, czy zechcesz pomóc takiej staruszce jak ja w paru sprawach?', 0),
(10718, 'plPL', 'O czym ty mówisz?$B$BGarm Wilczy Brat? To był ostatni wódz klanu Władców Gromu. Jeśli $grozmawiałeś:rozmawiałaś; z jego duchem, to musi być prawda.', 0),
(10719, 'plPL', 'To ciekawe, ale niepokojące. Ciekawe, czy Samia wie, kim jest ten Kolphis Mroczna Łuska?', 0),
(10720, 'plPL', 'Przez długie lata skupiałem się na doskonaleniu sposobów porozumiewania się z naturą. To tylko drobna cząstka niewykorzystanego potencjału, jaki mogą ci dać zwierzęta.', 0),
(10721, 'plPL', '<Baron Sablemane zagląda do woru gronna i wydaje się zadowolony.>$B$BDoskonale, $gdotrzymałeś:dotrzymałaś; swojej części umowy. Skoro cena została zapłacona, dam Rexxarowi to, czego szuka.', 0),
(10722, 'plPL', 'Zaatakować nas? Wybić nas? Nie sądzę!$B$BTen Sabat Czarnoskrzydłych musi się jeszcze wiele nauczyć, jeśli myśli, że z Ekspedycją Cenariońską pójdzie tak łatwo!$B$BJak to mówią? Kto mieczem wojuje, od miecza ginie!', 0),
(10723, 'plPL', 'Ogry Krwawych Młotów i ich pan, Gorgrom, nie będą już nękać Mok\'Nathalów.$B$BMartwię się jednak, jak nasze działania wpłyną na pozostałych gronnów. Myślę, że musimy zakończyć tę walkę raz na zawsze.', 0),
(10724, 'plPL', 'Leokk przyniósł nam głowę jednego z czarnych smoków z Kresu Smoków. Dzięki niej rozwścieczymy Goca, gronna, który go pojmał, i zwabimy go do walki.', 0),
(10742, 'plPL', 'Bitwa była ciężka, a ty dzielnie $gwalczyłeś:walczyłaś;, $N. To dla mnie zaszczyt, że stałem u twego boku w walce z Gocem. Brak mi słów, by wyrazić wdzięczność.$B$BMok\'Nathalowie powinni się dowiedzieć o tych wielkich zwycięstwach, ale nie jestem jeszcze gotów stanąć przed nimi. Znam umysł mojego ojca i znam swoje serce. Wciąż wiele mogę się nauczyć i zrobić, by stać się silniejszym i pokazać mu, że jestem jego prawdziwym synem.', 0),
(10747, 'plPL', 'O rety, jest ich więcej, niż się spodziewałam! Twoje bohaterstwo zasługuje na pochwałę!$B$BTo wspaniały miot czarnych piskląt na początek. Na początek badań, oczywiście.$B$BProszę, przyjmij to jako zapłatę. Nalegam!', 0),
(10748, 'plPL', 'Teraz, gdy wiemy, że przywódca naszych wrogów został pokonany, możemy odetchnąć swobodniej. Co więcej, $gocaliłeś:ocaliłaś; całe pasmo gór przed ich grabieżą.$B$BJakiekolwiek były ich ostateczne cele, $gpokrzyżowałeś:pokrzyżowałaś; je!$B$BMasz naszą wdzięczność, $N. Przyjmij, proszę, ten znak naszego szacunku, a także naszą nieustającą gościnność.', 0),
(10749, 'plPL', 'Paskudna to sprawa, to używanie trucizn. Ale zrobi to, czego chcemy.', 0),
(10753, 'plPL', 'Nie jestem dumna z tego, że zniszczyliśmy to, co stworzyła Elune, ale skażenie trzeba było powstrzymać. Dobrze się $gspisałeś:spisałaś;, $N.', 0),
(10770, 'plPL', 'Jest ich tak wiele, że nigdy nie zabijemy wszystkich, ale $gdałeś:dałaś; mi nadzieję. Może przez kolejnych kilka stuleci postaram się bardziej, by przywrócić do życia mój ukochany las.', 0),
(10771, 'plPL', '$GZniszczyłeś:Zniszczyłaś; wiele tych plugawych stworzonek. Spokojniej mi, gdy wiem, że tyle ich zginęło.', 0),
(10783, 'plPL', 'Witaj. Jestem Baron Sablemane. Przyjaciel Rexxara jest moim przyjacielem.', 0),
(10784, 'plPL', '<Tor\'chunk kiwa głową, wyraźnie pochwalając twoją zabójczą sprawność.>$B$BWciąż mi imponujesz, $N. Za każdym razem, gdy pada któryś z tych śmierdzących ogrów, jesteśmy o krok bliżej pozbycia się niegodnego wroga.', 0),
(10785, 'plPL', 'Hm, pułapka ze smoczego ognia? Ciekawe, skąd Sablemane bierze tak rzadkie substancje?$B$BNieważne. Ważne, że użyjemy jej, by zabić syna Gruula.', 0),
(10786, 'plPL', '<Tor\'chunk szczerzy zęby, słuchając twojej opowieści o przygodach w Boulder\'mok.>$B$BAch, szkoda, że nie mogłem tam być razem z tobą. Powiem ci coś, $N: nigdy nie przyjmuj obowiązków, które odciągają cię od chwały bitwy!$B$BHa! Po tym, ile ogrów $gwybiłeś:wybiłaś;, zostały w tych górach jeszcze jakieś dla mnie?!', 0),
(10795, 'plPL', 'Po śmierci Dorgoka ogry Krwawych Młotów zostały bez przywództwa i powinny pogrążyć się w chaosie, dopóki z ich szeregów nie wyłoni się nowy wódz.$B$BDziękuję ci, $N. Chyba możemy teraz odetchnąć nieco swobodniej.', 0),
(10796, 'plPL', '<Porucznik kiwa głową, wyraźnie pochwalając twoją zabójczą sprawność.>$B$BJestem pod wrażeniem, $N. Wygląda na to, że na swoją reputację w pełni $gzasłużyłeś:zasłużyłaś;.$B$BZa każdym razem, gdy pada któryś z ogrów, jesteśmy o krok bliżej pozbycia się zagrożenia, które wcale nie zamierza zostawić nas w spokoju.', 0),
(10797, 'plPL', 'O, ależ to ładne. Bardzo przypomina tych gronnów, którzy wiecznie rządzą się ogrami Klanu Ostrza.$B$BDziwne, że $gznalazłeś:znalazłaś; to w rękach jednego z przywódców Krwawych Młotów.', 0),
(10798, 'plPL', 'Ach, wysłannik osławionego Przymierza. Powiedz mi, sługusie, czemu to ty tu jesteś i błagasz mnie o tę rzecz, a nie twój znamienity dowódca?$B$BCzyżby się mnie bał? To, że ty się nie boisz, coś o tobie mówi, tylko jeszcze nie zdecydowałem, co takiego.', 0),
(10799, 'plPL', 'Dobrze. Proste, choć przyziemne zadanie zostało wykonane. A teraz oddaj mi gruczoły, a ja zajmę się trudniejszą częścią.', 0),
(10800, 'plPL', '<Baron Sablemane zagląda do woru gronna i wydaje się zadowolony.>$B$BDobrze, $gdotrzymałeś:dotrzymałaś; swojej części umowy. A teraz podaruję pułapkę twojemu Dowódcy Kamiennemu Murowi.', 0),
(10801, 'plPL', 'Hmm, pułapka sporządzona z esencji smoczego płomienia? Ciekawe, skąd Sablemane bierze tak wyszukane substancje?$B$BNieważne. Ważne, że użyjemy jej, by zabić syna Gruula!', 0),
(10802, 'plPL', 'Dobra robota, $N. Doskonała robota!$B$BPodejrzewam, że niewiele już usłyszymy o ograch i ich panu.', 0),
(10803, 'plPL', '<Porucznik Fairweather szczerzy zęby, słuchając twojej opowieści o przygodach w Boulder\'mok.>$B$BAch, szkoda, że nie mogłam tam być razem z tobą. Powiem ci coś, $N: nigdy nie przyjmuj obowiązków, które odciągają cię od chwały pola bitwy!$B$BHa! Po tym, ile ogrów $gwybiłeś:wybiłaś;, zostały w tych górach jeszcze jakieś dla mnie?!', 0),
(10805, 'plPL', 'Doskonale. Wybrałem mądrze, gdy uczyniłem cię ostrzem mojej walki. Myślę, że pora wejść na zupełnie nowy poziom.$B$BPamiętasz ten mały smakołyk, który $gukradłeś:ukradłaś; dla mnie sprzed samego nosa Grulloca? Będziesz mieć okazję zrobić z niego dobry użytek.', 0),
(10806, 'plPL', 'Walczysz zaskakująco dobrze i zaszczytem było mieć cię u swego boku. Moja przemiana musiała być dla ciebie sporym zaskoczeniem. Ufam, że nie za bardzo cię przestraszyła?$B$BZachowajmy na razie moją prawdziwą tożsamość między nami, dobrze? W zamian, a także za twoją biegłą służbę, pozwolę ci wybrać którąkolwiek z tych błyskotek.', 0),
(10810, 'plPL', 'A co ty tam masz? Daj no przyjrzeć się z bliska, $N. Tak, tak... to dokładnie to, co myślałem. No, pozwól, że naprawię ci tę maskę.', 0),
(10812, 'plPL', 'Maska, którą trzymasz w rękach, to maska gazowa zaprzysiężonych Spaczeniu i sądząc po wyglądzie, jest nieuszkodzona. Kłopoty, jakich możemy narobić w Obozie Kuźniczym Złość, są bezgraniczne. Chcesz nam pomóc, $N?', 0),
(10818, 'plPL', 'Ach, widzę, że $gpostanowiłeś:postanowiłaś; nie spieszyć się z odpowiedzią na moje wezwanie.$B$BNieważne, mam mnóstwo czasu, by dokonać zemsty, i zamierzam uczynić cię moim zastępcą w nadchodzącej bitwie!', 0),
(10819, 'plPL', 'Co to ma znaczyć?! Nikt mnie nie wzywa! Mów albo uciszę cię na zawsze!', 0),
(10820, 'plPL', 'To z pewnością nauczy tych, którzy nie robią, co każę...$B$BA przy okazji... gdzie jest Głosicielka zagłady? Czemu to ty meldujesz mi o tym buncie, a nie ona?', 0),
(10821, 'plPL', 'To świetna wiadomość, naprawdę świetna, $N. Nie mogłem prosić o lepszy wynik. Twoja służba dla naszego ludu jest niezwykle ceniona. Wybierz jeden z tych bohaterskich przedmiotów.$B$BTwoje imię na zawsze pozostanie w sercach naszego ludu.', 0),
(10825, 'plPL', 'Tak, to ta kula, którą masz! Dziwne, wygląda na dzieło arakkoa. $GByłeś:Byłaś; ostatnio w Grishnath?$B$BNo dobrze, to wszystko wyjaśnia, ale zastanawiam się, jakiemu diabolicznemu celowi służy ten przedmiot. Choć bije od niego zło, w jakiś sposób wydaje się również związany ze światem natury.$B$BDaj, spróbuję ją uaktywnić. Zło jest w niej tak silne... jest tu jakiś szczątkowy ślad wspomnień...', 0),
(10829, 'plPL', 'Witaj, maleńka istoto. Ptaki w moich konarach szeptały mi, że należy się ciebie spodziewać.$B$BPrzybywasz, by pomóc uwolnić drzewa tego lasu od opętania?', 0),
(10830, 'plPL', 'Zło opuszcza Kruczy Las! Czujesz to, $N?$B$B$GOcaliłeś:Ocaliłaś; nas i całą okoliczną dziką przyrodę przed pewną zagładą, maleńka istoto!$B$BNa takie okazje jak ta, gdy pojawia się bohater, by dokonać wielkiego czynu, trzymam w swoich konarach cztery magiczne pierścienie.$B$BA ty jesteś takim bohaterem! W imieniu całego Kruczego Lasu dziękujemy ci.', 0),
(10843, 'plPL', '<Leoroxx przygląda ci się bystrym okiem, jakby próbował cię ocenić.>$B$BŚmierć Gnosha Brognata to dobrodziejstwo dla wszystkich Mok\'Nathalów. To dobrze dla ciebie.$B$BZobaczmy, czy zdołamy jeszcze trochę przesunąć granice twojej sprawności.', 0),
(10845, 'plPL', 'Nie? $GZabiłeś:Zabiłaś; Trwogoskrzydłą? Może się co do ciebie myliłem, $N.$B$BMoże.$B$BTak czy inaczej, $gzabiłeś:zabiłaś; wodzów trzech największych zagrożeń, z jakimi się mierzymy. To powód do dumy.$B$BDaję ci wyraz mojego uznania, ale niech ci się nie przewróci w głowie. Wciąż nie rozumiesz w pełni, co znaczy być Mok\'Nathalem, a my wciąż możemy potrzebować twoich umiejętności.', 0),
(10846, 'plPL', 'Vekh\'nir to najmniejsi z naszych wrogów.$B$BA więc umiesz zabić przerośniętego ptaka. To nie czyni cię prawdziwym wojownikiem. To nie daje ci pełnego zrozumienia naszych obyczajów.$B$BAle to jakiś początek.', 0),
(10851, 'plPL', 'To wygląda na niezły zestaw. Powinniśmy znaleźć godne zastosowanie dla jednego czy dwóch z nich.$B$BWłaściwie mam już pomysł, jak to zrobić!', 0),
(10853, 'plPL', 'Dobrze się dziś $gspisałeś:spisałaś;, $N. Duchy smokowców, teraz uwolnione, naprawdę znów będą śpiewać. A to, co z ich duchów zostaje, to potężne lekarstwo.$B$BCiekawe, czy $gbyłbyś gotów:byłabyś gotowa; na wyprawę na północ? Zastanawia mnie pewna sprawa związana z działaniami eterycznych.$B$BWyczuwam z tamtej strony wielki ból.', 0),
(10859, 'plPL', 'Coś tu jest nie tak.$B$BProszę, $N, podaj mi totem. Muszę zbadać te kule!', 0),
(10860, 'plPL', 'Mmm, już czuję ich smak. Szybko, dawaj te kawałki... zaraz je posiekam i wrzucę na ogień!$B$BNa twoje szczęście to jedzenie długo się trzyma – naprawdę długo! Weź więc te porcje, a w nagrodę za to, że $gbyłeś tak miły:byłaś tak miła; i $guzupełniłeś:uzupełniłaś; moją spiżarnię, możesz chyba dostać też przepisy.', 0),
(10865, 'plPL', 'To, co mówisz... czy to w ogóle możliwe? Co ja mówię? Oczywiście, że tak, skoro twierdzą tak przywoływacze duchów.$B$BPamiętasz, jak mówiłem, że możemy jeszcze potrzebować twojej pomocy? Wygląda na to, że potrafię przewidywać przyszłość.', 0),
(10867, 'plPL', 'Dobrze, że ta eteryczna hołota i jej przywódca nie żyją. Oby ich pobratymców spotkało tysiąc plag!$B$BZa to, co $gzrobiłeś:zrobiłaś; w imieniu wszystkich Mok\'Nathalów, należy ci się nagroda, $N! Naprawdę jesteś jednym z naszych bohaterów.$B$BA teraz oddajmy dusze naszych przodków oczyszczającemu ogniowi.', 0),
(10893, 'plPL', 'Skoro Draaca zniknęła ze sceny, powinniśmy móc obrócić sytuację na naszą korzyść. Zaczną się kłócić o to, kto ma przejąć dowodzenie, a to trochę zmniejszy nacisk.$B$BChyba że nadzorca, o którym wspomina notatka, którą mi $gdałeś:dałaś;, przybędzie, by zająć jej miejsce.$B$BZobaczmy, czy zdołasz coś zrobić, żeby do tego nigdy nie doszło!', 0),
(10894, 'plPL', 'Tak jak myślałem, a to niedobrze!$B$BMam pomysł, jak ci pomóc, ale najpierw zastanawiałem się, czy nie $gpomógłbyś:pomogłabyś; nam?$B$BRęka rękę myje.', 0),
(10904, 'plPL', 'Te rzeczy śmierdzą bardziej, niż myślałem!$B$BSzybko, oddaj mi je, a nasycę je siłą Natury tak, że okażą się wyjątkowo zabójcze dla ich spaczonych panów i ich nienaturalnych tworów.', 0),
(10910, 'plPL', 'To ulga, że Władca dziczy Antelarion przysłał cię do nas. Problem jest znacznie poważniejszy, niż początkowo się obawialiśmy!', 0),
(10911, 'plPL', 'Twoja sprawność jest oszałamiająca!$B$BDobrze, skoro bramy wypaczenia zniknęły ze sceny, zostało już tylko jedno do zrobienia.', 0),
(10912, 'plPL', 'Naprawdę jesteś $gniezwykły:niezwykła;! Jeśli wcześniej myślałem, że mamy wobec ciebie dług, to teraz po prostu nie ma sposobu, byśmy kiedykolwiek mogli ci się odwdzięczyć.$B$BAle spróbujemy. Dziękujemy ci, $gbohaterze:bohaterko; Wiecznego Gaju!', 0),
(10927, 'plPL', 'Dobra robota, $N. Ten tunel to nasza linia życia prowadząca na bagna.', 0),
(10928, 'plPL', 'Dobra robota, $N. Ten tunel to nasza linia życia prowadząca na bagna.', 0),
(10974, 'plPL', '<Wizerunek dowódcy Ameera przegląda dowody.>$B$BJest gorzej, niż myślałem... W tych komorach trzymane są dzikie bestie i stworzenia z wielu, wielu różnych światów. Eterium ma nadzieję, że pewnego dnia będzie rozkazywać tym bestiom. Musimy je wszystkie zniszczyć!', 0),
(10975, 'plPL', 'Zawsze jest więcej pracy do wykonania, $N. A teraz odszukaj komorę stazy i zniszcz zło, które się w niej czai!', 0),
(10976, 'plPL', 'Nareszcie!$B$B<Dowódca Ameer odczytuje Znak Króla Nexusa.>$B$BDwa ostatnie więzienia? Drżę na myśl o tym, jakie okropieństwa tam czekają...', 0),
(10977, 'plPL', 'Wieści o twoich bohaterskich czynach dotarły i do nas, $N. Haramad i ja zgadzamy się, że to, czego $gdokonałeś:dokonałaś;, zasługuje na wielką nagrodę.$b$bChoć... Nieważne, $gzrobiłeś:zrobiłaś; już dość. Nie mogę z czystym sumieniem prosić cię o nic więcej.', 0),
(10980, 'plPL', 'Czy to nie zdumiewające, że nawet arakkoa uważali tych kultystów za heretyków? Aż trudno uwierzyć, że tradycyjni kapłani nienawidzili ich tak bardzo, że zniszczyli ich święty tekst! Musimy zdobyć tę księgę, $N.$B$BTo klucz do rozwikłania tajemnicy Boga Kruków i powstrzymania go, zanim przejmie Szmaragdowy Sen.$B$BMoże jeśli nam się uda, Morthis w końcu zgodzi się przyjąć mnie na uczennicę!', 0),
(10981, 'plPL', 'Zgodnie z obietnicą, oto klucz do prywatnej komory stazy Shaffara.', 0),
(10982, 'plPL', 'Wiele $gzrobiłeś:zrobiłaś; dla Protektoratu i Konsorcjum, $N. Słusznie więc pierwszy z naszych nowych kluczy trafia do ciebie. Dzięki niemu w każdej chwili otworzysz prywatną komorę stazy Shaffara, a sam klucz się przy tym nie zużyje.$b$b<Ameer kiwa głową.>$b$bJest trwały i zostanie z tobą na zawsze.', 0),
(10989, 'plPL', 'Nareszcie Chort przysłał mi kogoś, kto wygląda, jakby mógł pomóc. Próbuję ocalić Krwawe Młoty przed zagładą z rąk Klanu Ostrza i wspierających go synów Gruula.$B$BUfam, że to ty wesprzesz nasze tajne stowarzyszenie i wyprowadzisz nas na wolność.', 0),
(10990, 'plPL', '<Arthorn zdaje się wyczuwać moc odzyskanej esencji zmysłami krogulca.>$B$BNawet po tysiącach lat niewoli moc orła wciąż jest wielka. Jeśli pozostałe esencje są równie silne jak esencja orła, Bóg Kruków słusznie będzie się ciebie lękał.', 0),
(10992, 'plPL', 'Teraz, gdy mamy już wszystkie esencje, Morthis Szeptoskrzydły musi znaleźć sposób, by połączyć je w amulet, dzięki któremu zdołasz wyzwać Boga Kruków, wywabić go ze Szmaragdowego Snu i pokonać. Wyślę mu swoje notatki o duchach w nadziei, że dostrzeże wartość moich spostrzeżeń.$B$BKażdy z duchów pobłogosławił talizman, który dla ciebie przygotowałam.', 0),
(10995, 'plPL', 'Istotnie, to musiała być ciężka walka, $N. Czuję wielką ulgę, że nie będzie nam już tu deptał po piętach.$B$BOdeślę tę czaszkę na dół do Chorta, by jej strzegł. Zaczynam myśleć, że z twoją pomocą naprawdę może nam się udać.', 0),
(10996, 'plPL', 'Mówisz, że była pusta? Szkoda, ale $gsam:sama; widzisz, z jak bezmyślną brutalnością mamy do czynienia.$B$BWraz z upadkiem Maggoca jesteśmy o krok bliżej spełnienia mojego marzenia o domu dla ogrów, w którym sami będziemy decydować o swoim losie.', 0),
(10998, 'plPL', 'Waham się nawet dotknąć czegoś tak skażonego złem. A jednak musimy to przeczytać, jeśli mamy wydobyć z tego wiedzę i wywabić Skulloca z kryjówki.', 0),
(11000, 'plPL', 'A więc to koniec. $GUwolniłeś:Uwolniłaś; nas z kajdan niewoli u Synów Gruula. $GDałeś:Dałaś; Klanowi Krwawych Młotów wytchnienie od pewnej zagłady.$B$BSłowa nie opiszą, jak wielki dług mają wobec ciebie WSZYSTKIE ogry z Gór Klingi, zarówno Krwawe Młoty, jak i Klan Ostrza, $N.$B$BSpójrz w dół – już teraz ogry zbierają się, by oddać ci hołd. Niech Gruul i jego marionetka, stary król Maulgar, kulą się w swoim leżu. Zejdź do ogrów na dole jako $gnasz nowy król:nasza nowa królowa;!', 0),
(11009, 'plPL', 'Mog\'dorg przesłał wiadomość, że mam się ciebie spodziewać. Cieszę się, że $gprzybyłeś:przybyłaś;.$B$BSkoro Synowie Gruula zostali zniszczeni, to tylko kwestia czasu – i to krótkiego – nim rozmaici mieszkańcy tego górskiego tarasu i tego na północy postanowią zapolować na naszych ogrzych braci na dole.$B$BUfam, że pomożesz nam temu zapobiec, $B.', 0),
(11010, 'plPL', 'No, no, no, jednak masz w sobie to coś. Dobra robota. Może Stary Keller jednak się co do ciebie mylił.$B$B<Podniebna sierżant Vanderlip uśmiecha się drwiąco.>', 0),
(11022, 'plPL', '$GMój drogi:Moja droga;, cieszę się, że przed odejściem $gpostanowiłeś:postanowiłaś; porozmawiać ze mną raz jeszcze.', 0),
(11023, 'plPL', 'Znakomita robota, $N! Najchętniej od razu posłałabym cię z powrotem w powietrze, żebyś znowu ich $gzbombardował:zbombardowała;, ale tutejsze zasady mówią, że nasi piloci muszą porządnie odpocząć. Wybacz, to nie ja ustalam zasady, ale jak cholera pilnuję, żeby ich przestrzegano!', 0),
(11025, 'plPL', '<Zaczyna mówić lewa głowa Chu\'a\'lora.>$B$BTe się nadadzą.$B$BPamiętaj, $B, że wartość odłamka nie leży w tym, co możesz za niego kupić. Nie leży nawet w tym, co może dla ciebie zrobić, gdy zostanie odpowiednio przekuty, choć co do tego zdania są podzielone.$B$B<Kończy prawa głowa...>$B$BPrawdziwa wartość tkwi w drodze, która prowadzi do zdobycia odłamka.', 0),
(11026, 'plPL', 'To ich nauczy! A teraz, oczywiście, twoja nagroda.$B$BDemony z Obozu Kuźniczego Gniew, na północy, zbudowały na jego południowym skraju specjalny transporter. Te eksperymentalne wrota służą do rozbudowy obozu i chyba nie musimy ci mówić, co nas czeka, jeśli rozrośnie się za bardzo.$B$BGdybyśmy jednak byli tobą, zanieślibyśmy tę mroczną runę Gahkowi i zapytali go, jak możesz pomóc. Tylko obchodź się z nim łagodnie, $N. Tak jak ty, jest tu nowy.', 0),
(11027, 'plPL', 'Haha, dobrze! Gahk lubić mroczne runy! Ty brać mroczna runa z kryształowej kuźni, co Gahk zrobić wcześniej.$B$B$N pamiętać: kontrolować degradator, potem walić młotem w magiczna tarcza na transporter Shartuula. Wypuścić drugi demon i walczyć z nim, żeby jego też kontrolować! Potem walić i kontrolować więcej demonów, aż już żaden nie przychodzić!$B$BWtedy ty ocalić Ogri\'la!', 0),
(11030, 'plPL', 'Ratujesz nam życie, $N. Nasi chłopcy będą zachwyceni, gdy się dowiedzą!$B$BDobra, jedna z głowy, została jeszcze jedna. Mówiliśmy ci o tej drugiej magicznej flaszce, której będą potrzebować, prawda?', 0),
(11036, 'plPL', '<Szef sprawdza zawartość skrzynki.>$B$BWszystko wygląda dobrze. Kolejna rzecz do odhaczenia na liście. Teraz musimy już tylko poderwać rakietę z ziemi!', 0),
(11040, 'plPL', 'Nawet nie wiem, do czego służą niektóre z tych części! Na pewno do czegoś je wykorzystam, ale nigdy bym nie przypuszczał, że będę musiał nauczyć się myśleć jak gnom!', 0),
(11043, 'plPL', '<Twarz Brunna czerwienieje, aż jej kolor staje się nie do odróżnienia od koloru brody.>$B$BOn chce zrobić CO z moimi gryfami?$B$BJeśli ten mały cherlak założy im cokolwiek poza siodłem, osobiście pofatyguję się do Gór Klingi i wepchnę mu tę jego rakietę do gardła!', 0),
(11047, 'plPL', '<Dama wysłuchuje prośby Agadaia.>$B$BNie mogę obiecać, że znajdą się jakieś wolne wiwerny, ale zobaczę, co da się zrobić. Już teraz ledwie nadążamy z zamówieniami innych kupców i posterunków.', 0),
(11051, 'plPL', 'Chcielibyśmy, żeby tworzenie mrocznej runy było niezawodne, $N. Niestety, nie jest. Proszę, weź ten worek i zajrzyj do środka, żeby zobaczyć, co nam dziś wyszło. Sami nie mieliśmy odwagi zajrzeć.$B$BPamiętaj: jeśli dostaniesz mroczną runę, zanieś ją Gahkowi, a wymieni ci ją na mroczną runę z kryształowej kuźni. Wtedy znów zdołasz zniszczyć transporter Shartuula.$B$BA, $N, nie zapomnij wpaść jutro po kryształ wygnania. Zawsze są kolejne demony do wygnania.', 0),
(11057, 'plPL', '$GZostałeś zesłany:Zostałaś zesłana; z wysoka? Moja misja naprawdę jest błogosławiona! Próbuję ocalić Krwawe Młoty przed zagładą z rąk Klanu Ostrza i wspierających go synów Gruula.$B$BUfam, że to ty wesprzesz nasze tajne stowarzyszenie i wyprowadzisz nas na wolność.', 0),
(11058, 'plPL', '<Chu\'a\'lor kiwa do ciebie głowami, zadowolony z twojego osiągnięcia.>$B$BMasz bystry umysł, $N. Nam znacznie dłużej zajęło, zanim zdołaliśmy skorzystać z reliktu.$B$BSkoro już wiesz jak, możesz to robić, ile tylko zechcesz. Pamiętaj tylko, że do ich zasilenia potrzebny jest odłamek apeksisu.', 0),
(11059, 'plPL', '<Chu\'a\'lor promienieje, patrząc na ciebie z wyraźnym szacunkiem.>$B$BNie tylko jesteśmy pod wrażeniem bystrości umysłu twojego i twoich przyjaciół, ale jesteśmy też twoimi dłużnikami – jak całe Ogri\'la i Podniebna Straż – za to, że pomagasz chronić nasz tutejszy sposób życia.$B$BI pamiętaj, $N, że w każdej chwili możesz zebrać innych i wrócić do któregoś z tych większych monumentów apeksisu, by z niego skorzystać – o ile tylko masz dość odłamków apeksisu, by go zasilić.', 0),
(11060, 'plPL', '$r pamiętać: gdy ty kontrolować degradator, ty użyć jego młot, żeby rozwalić tarcza wrót wypaczenia i wypuścić demon ze środka.$B$BPotem ty zgnieść ten demon i kontrolować go. Potem przyjść kolejny demon i ty go kontrolować, aż przyjść eredarski nadzorca.$B$BWtedy ty zgnieść też jego!!!', 0),
(11061, 'plPL', 'Nie wiemy, jak ci dziękować, $N!$B$BTeraz, z tymi dwiema flaszkami, choćby i niestabilnymi, będziemy mogli wysłać jednego z naszych chłopców na północ, do Posterunku Podniebnej Straży.$B$BZaczekaj chwilę, zaraz któregoś zawołamy.$B$B<Prawa głowa Torkusa woła syna niskim warknięciem.>', 0),
(11062, 'plPL', 'Witaj w Posterunku Podniebnej Straży! Zbudowałem go własnymi rękami, wiesz?$B$BTak, całość!$B$B<Podniebny dowódca poważnieje.>$B$BSkoro tu jesteś i ze mną gadasz, to pewnie aż cię nosi do bitki. Miło ze strony starego Chu\'a\'lora, że cię tu przysłał. Świeżego mięsa do mielenia zawsze nam tu trzeba.$B$BJeśli nie masz nic przeciwko, na początek chciałbym, żebyś $gpogadał:pogadała; z moją sierżant, tam naprzeciwko: z Vanderlip. Nie przejmuj się jej językiem, choć jest ostrzejszy niż wielki miecz, który nosi.', 0),
(11065, 'plPL', 'Juhu! Dobra robota, $N! Z tych płaszczek będą świetne wierzchowce!$B$BZostań z nami, dzieciaku... Podniebnej Straży Sha\'tari zawsze przyda się ktoś o tak oczywistych talentach!', 0),
(11066, 'plPL', 'Nie przestajesz mnie zadziwiać! Wiesz co... może wrócisz jutro, a na razie pozwolimy linie ostygnąć?$B$B<Khatie się śmieje.>$B$BDziękuję ci bardzo, $N!', 0),
(11078, 'plPL', 'Tak! Te zęby wyglądają na tak ostre, że przetną prawie wszystko!$B$BZachęcam ciebie i twoich przyjaciół, byście dalej tak dobrze się spisywali! Te smoki to groźne drapieżniki, przez które w przestworzach nigdzie nie jest bezpiecznie.$B$BMoże $gzauważyłeś:zauważyłaś; też smocze łuski. Słyszałem, że dobrze się nadają do robienia potężnych płaszczy, jeśli zdobędziesz po jednej łusce od każdego z nich. A jeśli płaszcz, który dostaniesz, nie przypadnie ci do gustu, chętnie wymienię ci go na kryształ apeksisu.', 0),
(11079, 'plPL', 'Gahk lubić bicz. Może Gahk wziąć bicz i bić nim demony!$B$BJa mówić: $R przyzywać wodzów demonów, kiedy tylko $R mieć przyjaciół i dużo odłamków.', 0),
(11080, 'plPL', 'Nie przestajesz nas zadziwiać swoją biegłością w sprawie reliktów. $B. Czy możemy zasugerować, byś $gćwiczył:ćwiczyła; z reliktami co najmniej raz dziennie, by zachować tak wyostrzony umysł?', 0),
(11091, 'plPL', 'Hej, stary. Super. Słyszymy, że robisz dobre rzeczy. To czadowe. Mamy przeczucie, że wszystko nam tu, w Ogri\'la, naprostujesz, zapewnisz nam bezpieczeństwo i będzie miło i na luzie.$B$BMasz, weź to. To nic wielkiego, tylko paczka, którą skleciliśmy w podziękowaniu za twój wysiłek.$B$BRozejrzyj się śmiało po naszych towarach. Mamy mnóstwo naprawdę odjazdowych rzeczy, które będziesz $gchciał:chciała; mieć.', 0),
(11102, 'plPL', 'No, no, no, jednak masz w sobie to coś. Dobra robota. Może Stary Keller jednak się co do ciebie mylił.$B$B<Podniebna sierżant Vanderlip uśmiecha się drwiąco.>', 0),
(11119, 'plPL', 'Choćby Keller nie wiem jak to nazywał, wolę myśleć o naszych misjach jako o badawczych.$B$BAle owszem, przy okazji zaopatrujemy Podniebną Straż. O ile zdołamy zostać tam wystarczająco długo.$B$BWyglądasz na kogoś, kto chętnie będzie trzymać eteryków z dala od naszych pleców. Jeśli zdołasz to robić dostatecznie długo, sprzedamy ci nadwyżki przedmiotów, które wytworzymy w kuźni kryształów, więc przynieś swoje odłamki i kryształy apeksisu!$B$BWyruszamy za 2 godziny.', 0),
(11513, 'plPL', 'Te ogniwa many są kluczowe dla naszych wysiłków. Portal na Wyspę Słonecznej Studni powstanie w mgnieniu oka!$b$bWróć jutro, a znów wyślę cię po więcej ogniw do naszych „przyjaciół” z Bash\'ira.', 0),
(11514, 'plPL', 'Te ogniwa many nadal będą zasilać portal.$b$bWróć jutro, a wyślę cię po więcej.', 0),
(11736, 'plPL', 'Zbezcześć wielkie ognisko Przymierza w Górach Klingi!', 0),
(11767, 'plPL', 'Zbezcześć wielkie ognisko Hordy w Górach Klingi!', 0),
(11807, 'plPL', 'Uczcij płomień Gór Klingi!', 0),
(11843, 'plPL', 'Uczcij płomień Gór Klingi!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(10455, 'plPL', 'Czy nie mówiłam prawdy? Rysie tropiciele z gaju stały się zagrożeniem nie tylko dla podróżnych na tutejszej ścieżce, ale i dla samego Sylvanaar.$B$BIch śmierć jest godna ubolewania, ale przecież stworzyliśmy Żywy Gaj właśnie po to, by otaczał Sylvanaar obronnym pasem naturalnego piękna i spokoju.', 0),
(10456, 'plPL', 'Nie potrafię dość mocno podkreślić, jak ważne jest, by rozprawić się z tymi srogimi wilkami Władców Gromu. Samo ich istnienie zagraża równowadze Żywego Gaju i całej naszej pracy tutaj.', 0),
(10457, 'plPL', 'Jak idzie wzmacnianie obrony Żywego Gaju?$B$BNie wiemy, co zamierzają arakkoa z Zasłony Lashh, a Horda jest tuż po drugiej stronie parowu. Obawiam się, że jeśli nie będziemy działać szybko, trudno nam będzie obronić nasz nowy dom i naszą pracę w gaju.', 0),
(10486, 'plPL', 'Nasze przetrwanie tutaj zależy od tego, czy zdołamy skupić siły przeciw tym, którzy naprawdę się liczą, a nie przeciw jakimś ostroskrzydłym upuszczaczom krwi.$B$BSkoro znów tu jesteś, to pewnie $gzałatwiłeś:załatwiłaś; sprawę?', 0),
(10487, 'plPL', 'Wygląda na to, że Przymierze postanowiło chodzić za nami krok w krok. Pokażmy im, że ich obecność nas nie zastrasza.$B$BMasz to, o co prosiłem?', 0),
(10488, 'plPL', 'Jak idzie wzmacnianie naszych srogich wilków Władców Gromu?', 0),
(10489, 'plPL', 'Co tam masz? Ale z ciebie siłacz!', 0),
(10502, 'plPL', 'Nasi zwiadowcy donoszą, że ogry Krwawych Młotów zaczęły podkradać się serpentyną, która prowadzi z ich siedziby do Żywego Gaju.$B$BSzkoda, że nie potrafimy znaleźć sposobu, by żyć z ogrami w pokoju, ale kiedy nam się to w ogóle udawało?', 0),
(10503, 'plPL', 'Nasi zwiadowcy donoszą, że ogry Klanu Ostrza rozbiły obóz jeszcze bliżej serpentyny, która prowadzi z ich warowni do nas.$B$BSzkoda, że nie możemy po prostu podporządkować sobie tej ogrzej hołoty, ale jeśli chcą walki, przekonają się, że Horda chętnie im jej dostarczy.', 0),
(10504, 'plPL', 'Krwawe Młoty czy Klan Ostrza – nieważne. Wszystkie klany ogrów walczą ze sobą o dominację, jaką daje łaska Gruula Smokobójcy.$B$BKażdy z nich pozostaje naszym wrogiem, bez względu na to, komu ta łaska przypadła.', 0),
(10505, 'plPL', 'Klan Ostrza czy Krwawe Młoty – nieważne. Wszystkie klany ogrów walczą ze sobą o dominację, jaką daje łaska Gruula Smokobójcy.$B$BKażdy z nich pozostaje naszym wrogiem, bez względu na to, komu ta łaska przypadła, i przegonimy ich wszystkich!', 0),
(10506, 'plPL', 'Udało się? Wiem, że to niebezpieczna robota wśród ogrów Krwawych Młotów, ale jeśli unikniemy zabijania kolejnych zwierząt, będę szczęśliwa.', 0),
(10510, 'plPL', 'Czy to nie ekscytujące? Po całym tym piachu i robactwie Silithusu to miejsce jest jak raj.', 0),
(10511, 'plPL', 'Robi się tu strasznie sucho. Jak mam się cieszyć urlopem, kiedy nie ma czego wypić?', 0),
(10512, 'plPL', 'No i jak? Ogry Klanu Ostrza są równie niewybredne jak Krwawe Młoty, czy to piwo omal ich nie zabiło, tak jak mnie?', 0),
(10516, 'plPL', 'Masz mój miecz i tarczę?$B$BMogę odejść w każdej chwili, ale wstyd byłoby mi wracać do Sylvanaar bez mojego rynsztunku.', 0),
(10517, 'plPL', 'Co to był za hałas? To ty $grozprawiałeś:rozprawiałaś; się z Gorr\'Dimem?', 0),
(10518, 'plPL', 'Co cię do mnie sprowadza? Chyba nie kolejne kłopoty z klanem ogrów Krwawych Młotów?', 0),
(10525, 'plPL', 'Co $gwidziałeś:widziałaś;? Mów, muszę wiedzieć, gdzie to jest!', 0),
(10526, 'plPL', 'Znaczenie tych artefaktów pewnie ci umyka.$B$BGdy będziemy mieć wszystkie pięć, ułagodzimy duchy zmarłych Warowni Władców Gromu, a wtedy nasze prawo do niej będzie pewne.$B$BCzy zaczynasz teraz rozumieć, dlaczego to takie ważne? Rozumiesz, czemu brak mi cierpliwości do uprzejmości?', 0),
(10542, 'plPL', 'Hej, masz już moja fajka i to piwo?', 0),
(10543, 'plPL', 'Myślisz, że T\'chali lubi tak być? Nie!$B$BTo co, $gpomściłeś:pomściłaś; już T\'chalego? Grimnok i Korgaah nie żyją?', 0),
(10544, 'plPL', 'T\'chali nie chce więcej gadać, dopóki $N nie przeklnie fetyszem budynków i wież obu klanów, Klanu Ostrza i Krwawych Młotów!', 0),
(10545, 'plPL', 'Powiedz T\'chalemu... piwo zadziałało? Ogrom z Klanu Ostrza smakowało?', 0),
(10555, 'plPL', 'Z prymitywnych piktogramów na kartach starej księgi wnioskujesz, że do rzucenia zawartych w niej zaklęć potrzeba wielu piór Lashh\'an.', 0),
(10556, 'plPL', 'Ależ to ekscytujące! Nie mogę się doczekać, aż zbadam, jak działa to zaklęcie.', 0),
(10557, 'plPL', 'Nie bój się! To dla nauki, a nauka boli!', 0),
(10565, 'plPL', 'Arakkoa Vekh\'nir przez wiele lat byli niegroźni, ale teraz coś ich poruszyło.', 0),
(10566, 'plPL', 'Z niecierpliwością czekam na twoje wyniki, $N.', 0),
(10567, 'plPL', 'Gdy tylko Zwiastun spostrzeże, że atakujesz jego stado, szybko zareaguje.', 0),
(10584, 'plPL', 'Nasze badania nad elektromentalami są ekscytujące! Pomyśl tylko... inteligentne istoty elektryczne, które możemy tworzyć na zawołanie i które wykonają każde nasze polecenie!', 0),
(10594, 'plPL', 'No i jak, masz pomiary śpiewających kryształów, o które prosiłem?', 0),
(10607, 'plPL', 'Co to znaczy, $N? Co ich zdaniem on zrobi? Dokąd, jak wierzą, ich poprowadzi?', 0),
(10608, 'plPL', '$gOczyściłeś:Oczyściłaś; już Śpiewającą Grań z tych kryształowych oprawców? Nie możemy zacząć moich badań, dopóki tego nie zrobisz.', 0),
(10609, 'plPL', 'Masz je? Masz te trzy esencje smokowców, których tak bardzo potrzebuję, by kontynuować badania?$B$BWiesz, że te jaja smokowców Otchłani były kiedyś jajami czarnych smoków? To fakt! Ale kiedy Draenor rozleciał się na kawałki, Otchłań, która przetoczyła się po tym, co zostało, zmutowała jaja.', 0),
(10617, 'plPL', 'Do zbierania trzeba szybkiej i pewnej ręki. Mam nadzieję, że ci się uda.', 0),
(10618, 'plPL', 'Skrzydła są bardzo delikatne, ale można je wykorzystać jako zdobne inkrustacje w wielu naszych wyrobach.', 0),
(10620, 'plPL', 'Tropiciele już wybici? Kilku naszych, którzy poszli na północ, zaginęło.$B$BJeśli to przez tropicieli, chcę mieć pewność, że to się więcej nie powtórzy.', 0),
(10632, 'plPL', 'Jak idzie zbieranie zębów?$B$BJestem pewien, że świetnie sobie poradzisz. A w tym czasie my utrzymamy tu posterunek.', 0),
(10657, 'plPL', 'Cała sztuka w używaniu przebiegunowanej sfery magnetycznej polega na tym, żeby wiedzieć, kiedy ją wyłączyć, zanim naprawdę się usmażysz.$B$BOczywiście trzeba to wyważyć z tym, z iloma latającymi wężami chcesz się mierzyć.$B$BA skoro o tym mowa, udało ci się naładować sferę?', 0),
(10671, 'plPL', 'Masz mój funt ciała? Co, nie rozbawiło cię to?', 0),
(10674, 'plPL', 'Skoro rozmawiamy, to rozumiem, że masz świetlne kule z Przystani Razaana? Ciekawie będzie im się przyjrzeć i sprawdzić, co knują eteryczni.', 0),
(10675, 'plPL', '$GRozprawiłeś:Rozprawiłaś; się już z tym łajdakiem, złodziejem dusz, Razaanem?', 0),
(10682, 'plPL', 'Wszystko w porządku?', 0),
(10690, 'plPL', 'Co mogę dziś dla ciebie zrobić?', 0),
(10710, 'plPL', 'Nie martw się, $n! Zamartwianie się jeszcze nikogo nigdzie nie zaprowadziło!', 0),
(10711, 'plPL', 'Co? Nie chcesz przeprowadzić eksperymentu? Nie przejmuj się, $n! Jestem z tobą całym sercem!', 0),
(10712, 'plPL', 'Witam, witam! Mój klo... to znaczy mój kuzyn Tally mówił, że wpadniesz. Masz coś dla mnie?', 0),
(10713, 'plPL', '$GOchroniłeś:Ochroniłaś; drzewa? Rębacze wycięci?', 0),
(10714, 'plPL', 'Czego się $gdowiedziałeś:dowiedziałaś;, $N?', 0),
(10715, 'plPL', 'Masz wszystkie gruczoły jadowe? Jeśli nie, precz i nie marnuj więcej mojego czasu, dopóki ich nie zdobędziesz.', 0),
(10717, 'plPL', 'Jak idzie zdobywanie sieci? Z tego, co widziałam, sieci, których używają kłusownicy, powinny być dość mocne do tego zadania.', 0),
(10719, 'plPL', 'Co tam masz? Czy to plama krwi na tej notatce?', 0),
(10721, 'plPL', 'Już z powrotem? $GPrzyszedłeś:Przyszłaś; oddać mi to, co jest mi winien Rexxar?', 0),
(10722, 'plPL', 'Z jakimi wieściami przychodzisz? Wiesz, co knują kultyści Żmija?', 0),
(10723, 'plPL', 'Gdy to zadanie zostanie wykonane, ogry Krwawych Młotów przestaną nas nękać.', 0),
(10724, 'plPL', 'Dobrze będzie znów mieć Leokka u boku.', 0),
(10742, 'plPL', 'Tylko śmierć Goca i Gorgroma Smokożercy uwolni Mok\'Nathalów.', 0),
(10747, 'plPL', '$GMiałeś:Miałaś; dużo kłopotów z łapaniem piskląt? Mam nadzieję, że cię nie przypaliły!', 0),
(10748, 'plPL', '$GRozprawiłeś:Rozprawiłaś; się już z Maxnarem Popielną Paszczą?$B$BMasz kłopot z odnalezieniem go? Z tego, co wiem, jeśli po wejściu do ich jaskiń skręcisz w prawo, droga w końcu zatoczy łuk i zaprowadzi cię do niego.', 0),
(10749, 'plPL', 'Już $gwróciłeś:wróciłaś;? Masz truciznę?', 0),
(10753, 'plPL', 'Czy $gwymierzyłeś:wymierzyłaś; sprawiedliwość?', 0),
(10770, 'plPL', 'Wkrótce zasnę głębokim snem lasu. Zanim zapuszczę głęboko korzenie i na zawsze zamknę te stare oczy, chciałbym wiedzieć, że te nędzne chochliki cierpiały i poginęły.', 0),
(10771, 'plPL', 'Zrobione? $GPrzywróciłeś:Przywróciłaś; trochę życia mojemu pradawnemu domowi?', 0),
(10784, 'plPL', '$GZniszczyłeś:Zniszczyłaś; już Obóz Krwawych Młotów?', 0),
(10785, 'plPL', '$GZdobyłeś:Zdobyłaś; dla Sablemane\'a to, co było w worze tego gronna? Co nam dał?', 0),
(10786, 'plPL', 'W krótkim czasie przeszliśmy razem długą drogę, ty i ja. Śmiem twierdzić, że jesteś $gnajzdolniejszym łowcą ogrów, jakiego:najzdolniejszą łowczynią ogrów, jaką; kiedykolwiek znałem.$B$BUfam więc, że wkrótce rozprawisz się z ogrami z Boulder\'mok?', 0),
(10795, 'plPL', 'Nie potrafię dość mocno podkreślić, jak ważne jest, żebyś jak najszybciej $gzabił:zabiła; Dorgoka.', 0),
(10796, 'plPL', '$GZniszczyłeś:Zniszczyłaś; już Obóz Krwawych Młotów?', 0),
(10797, 'plPL', 'Witaj, $gchłopcze:dziewczyno;. Z jakimi wieściami przychodzisz?', 0),
(10799, 'plPL', 'Masz wszystkie gruczoły jadowe? Jeśli nie, to precz i nie marnuj więcej mojego czasu, dopóki ich nie zdobędziesz!', 0),
(10800, 'plPL', 'Znów stajesz przede mną. To znaczy, że $gzdobyłeś:zdobyłaś; wór sprzed samego nosa Grulloca.', 0),
(10801, 'plPL', 'Czy baron zrobił dla nas pułapkę? Na tyle potężną, by zabić gronna?', 0),
(10802, 'plPL', 'Czy wiadomość została przekazana?', 0),
(10803, 'plPL', 'Śmiem twierdzić, że jesteś $gnajzdolniejszym łowcą ogrów, jakiego:najzdolniejszą łowczynią ogrów, jaką; kiedykolwiek znałam.$B$BUfam więc, że wkrótce rozprawisz się z ogrami z Boulder\'mok?', 0),
(10805, 'plPL', 'Czy $gzdołałeś:zdołałaś; już zdziesiątkować ogry Klanu Ostrza pod Leżem Gruula?$B$BNie przychodź do mnie z wymówkami, $gchłopcze:dziewczyno;! Zrób, co do ciebie należy!', 0),
(10806, 'plPL', 'W swoim czasie wszyscy synowie Gruula zostaną zniszczeni.', 0),
(10810, 'plPL', 'Nie zawracaj mi głowy! Nie widzisz, że próbuję odblokować tajemne moce?', 0),
(10812, 'plPL', 'Nie wierzę własnym oczom.', 0),
(10820, 'plPL', 'Moja cierpliwość się kończy. Czemu jeszcze ich nie $gwykończyłeś:wykończyłaś;?', 0),
(10821, 'plPL', 'Chcesz trafić na moją listę tych, których nie szkoda? Zdobądź klucze i ucisz Głosicielkę zagłady!', 0),
(10825, 'plPL', 'Czujesz to? Wyczuwam w pobliżu coś nienaturalnego i złego.', 0),
(10830, 'plPL', 'Zło, które zamieszkało w drzewach, zaczyna przesączać się do wszystkiego, co żyje w lesie.$B$BMusisz działać szybko, $N, zanim wszystko przepadnie!', 0),
(10843, 'plPL', 'Mok\'Nathalowie nie akceptują porażek ani nie szukają wymówek. Albo pokonasz wroga, albo on zabije ciebie!$B$BSkoro stoisz przede mną, musisz już mieć Gnosha Brognata na sumieniu.', 0),
(10845, 'plPL', 'Choć nie zyskasz w moich oczach, nie ma wstydu w przyznaniu, że nie jesteś w stanie zabić matki smokowców Otchłani ze Śpiewającej Grani.$B$BCzy to właśnie $gprzyszedłeś:przyszłaś; mi powiedzieć?', 0),
(10846, 'plPL', 'Mamy wielu wrogów. Niektórych sami wybraliśmy, innych, jak Vekh\'nir, nie.$B$BTak czy inaczej, będziemy zabijać wszystkich ich wodzów, aż nikt nie stanie nam na drodze.', 0),
(10851, 'plPL', 'Czy $gposzedłeś:poszłaś; do Posterunku Klanu Ostrza i $godebrałeś:odebrałaś; im totemy?', 0),
(10853, 'plPL', 'Smokowce ze Śpiewającej Grani mogą nam zagrażać, ale moim zdaniem to majestatyczne stworzenia.$B$BA przynajmniej kiedyś takie były. Mam nadzieję, że zdołasz ocalić ich duchy.$B$BA jeśli potrzebujesz więcej totemów, mam kilka na zbyciu.', 0),
(10859, 'plPL', 'Czy $gzebrałeś:zebrałaś; wszystkie potrzebne świetlne kule Razaani?', 0),
(10860, 'plPL', 'Masz już wszystkie składniki? Od tego gadania o jedzeniu aż mi ślinka cieknie!', 0),
(10867, 'plPL', 'Udało się? Czy dusze naszych przodków zostały bezpiecznie wyrwane ze szponów złych eterycznych?', 0),
(10893, 'plPL', 'Czy ona nie żyje?$B$B$N, jeśli mamy tu mieć jakiekolwiek szanse, musisz zasiać zamęt w ich szeregach, zabijając Draacę Długi Ogon!', 0),
(10894, 'plPL', 'W czym mogę pomóc? Przynosisz wieści z Wiecznego Gaju?', 0),
(10904, 'plPL', 'Masz już kule armatnie?', 0),
(10911, 'plPL', 'Czy $gzniszczyłeś:zniszczyłaś; już obie bramy wypaczenia?', 0),
(10912, 'plPL', 'A więc to koniec? Czy niebezpieczeństwo u Wrót Śmierci zostało zażegnane?', 0),
(10927, 'plPL', 'Mógłbym przysiąc, że kazałem Strażniczce Szept Księżyca wydać ci wyraźne rozkazy. Nie wykonujesz ich?', 0),
(10928, 'plPL', 'Mógłbym przysiąc, że kazałem Siepaczowi Grahkowi wydać ci wyraźne rozkazy. Nie wykonujesz ich?', 0),
(10974, 'plPL', 'Udało ci się! Masz coś?', 0),
(10975, 'plPL', 'Utknęliśmy w martwym punkcie, $n. Zebrane przez ciebie dane dały nam dość informacji, by ocalić naszych sojuszników przetrzymywanych w mniejszych więzieniach Burzy Otchłani, ale musimy iść dalej i wyplenić większe zagrożenia ze strony Eterium tu, w Przystani Bash\'ira.$b$bDołącz do walki z Eterium! Przynoś mi klucze do więzienia z eterium, a wykuję ci klucze do komory stazy Eterium, których użyjesz na komorach stazy Bash\'ira.', 0),
(10976, 'plPL', 'To będzie twoje najtrudniejsze zadanie, $N.', 0),
(10977, 'plPL', 'Zrozumiem, jeśli nie zechcesz iść dalej, $N.', 0),
(10980, 'plPL', '<Arthorn patrzy na ciebie z nadzieją.>$B$BUdało ci się znaleźć jakieś informacje o tej księdze?', 0),
(10981, 'plPL', 'Na tę propozycję przystaną tylko najwytrwalsi i najbardziej zaprawieni w boju poszukiwacze przygód, $n. Jeśli chcesz stawić czoła okropieństwom drugiej komory stazy w Grobowcach Many, mogę wytworzyć klucz. Przynieś mi znak Króla Nexusa, a tak się stanie.', 0),
(10990, 'plPL', '<Krogulec zdaje się mówić głosem Arthorn.>$B$BCzy udało ci się uwolnić esencję ducha orła?', 0),
(10992, 'plPL', 'Czy $gpokonałeś:pokonałaś; strażnika jastrzębia i $gzdobyłeś:zdobyłaś; jego esencję?', 0),
(10995, 'plPL', 'Czy Grulloc już nie żyje?', 0),
(10996, 'plPL', 'Masz skrzynię?', 0),
(10998, 'plPL', 'Czy $gprzyzwałeś:przyzwałaś; Vim\'gola Plugawego i $gwyrwałeś:wyrwałaś; grimoire z jego martwych szponów?', 0),
(11000, 'plPL', 'Czy $gzdobyłeś:zdobyłaś; już duszę Skulloca?', 0),
(11010, 'plPL', '$GRozwaliłeś:Rozwaliłaś; już ich stosy spaczonych kul armatnich?', 0),
(11023, 'plPL', 'Jak idzie bombardowanie?', 0),
(11025, 'plPL', 'Gdy zrozumiesz odłamki i kryształy, lepiej pomożesz nam chronić siebie i naszych ogrzych braci na dole.$B$BSame odłamki zawdzięczają nazwę starożytnej, dziś już wymarłej cywilizacji arakkoa, która niegdyś żyła tu, na szczytach gór.$B$BCzy masz przy sobie odłamki?', 0),
(11026, 'plPL', 'Ufamy, że $gużyłeś:użyłaś; kryształu wygnania, by przegonić całą chmarę tych stworów Płonącego Legionu?!', 0),
(11027, 'plPL', 'Demony z tamten obóz ciągle naprawiać transporter. Gahk mówić: $n tym razem rozwalić ich lepiej!$b$bAle Gahk potrzebować kolejna mroczna runa, żeby zrobić mroczna runa z kryształowej kuźni.$b$bJak $r nie mieć mroczna runa, ty gadać z Kronk. On próbować zrobić jedna mroczna runa codziennie! Może ty dostać jedna w jego worek niespodzianek?!', 0),
(11030, 'plPL', 'Masz już tę magiczną flaszkę? Dla małego Torkusa juniora będzie znaczyła cały świat.', 0),
(11036, 'plPL', 'Czy to dostawa od Starego Oroka?', 0),
(11040, 'plPL', 'Ta skrzynia wygląda na robotę mistrza gnomiej inżynierii. Przysłała cię Bossi?', 0),
(11051, 'plPL', 'Ktoś tak doświadczony jak ty nie powinien mieć żadnych trudności z wyganianiem demonów. Nie masz żadnych trudności, prawda?', 0),
(11058, 'plPL', 'Czy wiesz już, jak używać reliktu apeksisu? Zarówno my, jak i Podniebna Straż Sha\'tari tuż na północy, jesteśmy ciekawi, czego się o nich dowiesz.', 0),
(11059, 'plPL', 'Brzydzimy się przemocą, ale przynajmniej konstrukt, na który cię wysłaliśmy, nie jest żywą istotą.$B$BSkoro o tym mowa, masz głowę?', 0),
(11060, 'plPL', 'Demony robić Obóz Kuźniczy: Gniew coraz większy. Niedługo one być za duże i zgnieść nas. Ty zgnieść je pierwszy!$b$bTransporter Shartuula to klucz, ale chronić go magiczna tarcza i demon zwany degradator. My być potężni i zrobić specjalna mroczna runa, co dać ci władzę nad degradator. $r dać Gahk mroczna runa, my oddać ci mroczna runa z kryształowej kuźni.$b$bPrzejąć kontrolę nad degradator i opętać ile się da demonów, co przejść przez wrota, żeby je zatrzymać!', 0),
(11061, 'plPL', 'Ta flaszka czarownika na pewno sprawi, że moi chłopcy będą jeszcze mądrzejsi, niż już są, a to bardzo im pomoże w tym, co będą musieli robić w Podniebnej Straży Sha\'tari.', 0),
(11065, 'plPL', '$GZłapałeś:Złapałaś; mi już jakieś płaszczki eteru? Wyglądasz, jakbyś $gumiał:umiała; obchodzić się z liną, więc nie powinno ci to zająć zbyt wiele czasu.', 0),
(11066, 'plPL', 'Świetnie się dla nas spisujesz, $N. Chcę, żebyś $gwiedział:wiedziała;, że naprawdę doceniamy wszystko, co robisz, byśmy mieli zapas świeżych wierzchowców!', 0),
(11078, 'plPL', 'Jak idzie twoja misja, $N? Chyba nie muszę ci mówić, jak ważne jest to dla nas, żebyśmy dalej mogli tu latać.', 0),
(11079, 'plPL', 'Ty mieć bicz?', 0),
(11080, 'plPL', 'Czy masz przy sobie emanację z reliktu apeksisu?', 0),
(11102, 'plPL', '$GRozwaliłeś:Rozwaliłaś; już ich stosy spaczonych kul armatnich?', 0),
(11513, 'plPL', 'Czy $gzdobyłeś:zdobyłaś; ogniwa many?', 0),
(11514, 'plPL', '$n, jak ci dziś idzie zdobywanie dla nas ogniw many?', 0),
(11807, 'plPL', 'Uczcij płomień Gór Klingi!', 0);
