(22534, 'plPL', 'Formuła: zaklęcie karwaszy – moc czarów', 'Uczy trwałego zaklinania karwaszy, co zwiększa moc czarów o 15. Wymaga przedmiotu co najmniej 35. poziomu.', 0),
(22555, 'plPL', 'Formuła: zaklęcie broni – wielka moc czarów', 'Uczy trwałego zaklinania broni do walki wręcz, co zwiększa moc zaklęć o 40. Wymaga przedmiotu co najmniej 35. poziomu.', 0),
