(30415, 'plPL', 'Tarcza obrończyni Vuuleen', 'Na tarczy nie widać ani jednej rysy, jakby jej powierzchnię w jakiś sposób podtrzymywała magia.', 0),
(30416, 'plPL', 'Sztandar Klanu Ostrza', 'Na sztandarze wyraźnie widnieje wizerunek dzika z pazurami.', 0),
