INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(4272, 'plPL', 'Oczywiście!', 'Oczywiście!', 0),
(17844, 'plPL', 'Mmmm, piwo Krwawych Młotów!', '', 0),
(18170, 'plPL', 'Ooo, patrz! Piwo Krwawych Młotów! Mmmm...', '', 0),
(18171, 'plPL', 'Piwo Krwawych Młotów? Ja najbardziej lubić!', '', 0),
(18178, 'plPL', 'Co wiesz o eterykach, istoto z mięsa?$B$BZ pewnością postrzegasz nas wszystkich jednakowo i nie masz pojęcia o konfliktach i zmaganiach między różnymi frakcjami.$B$BMoże pora się przedstawić. Jestem dowódca Ameer z Protektoratu – a zarazem twoja jedyna nadzieja na pozbycie się z tej okolicy plagi zarówno istot Pustki, jak i Eterium.\n', '', 0),
(18183, 'plPL', 'Czym jest Eterium?', 'Czym jest Eterium?', 0),
(18184, 'plPL', 'Eterium było klasą rządzącą eteryków na moim ojczystym świecie, K\'areshu. Niestety, musieliśmy uciekać z K\'areshu na krótko przedtem, nim władca Pustki, Dimensius, rozpętał na tym świecie swoje armie Pustki i doszczętnie zniszczył wszystko, co stanęło mu na drodze. Za ten czyn Eterium poprzysięgło zemstę. Od tamtej pory tropi Dimensiusa...$B$BProtektorat natomiast nie powstał w odpowiedzi na Dimensiusa. Powstaliśmy w odpowiedzi na Eterium.', '', 0),
(18185, 'plPL', 'Nie rozumiem. Co masz na myśli, Ameerze?', 'Nie rozumiem. Co masz na myśli, Ameerze?', 0),
(18186, 'plPL', 'Eterium pogrążyło się w mroku... wypaczyło się. Zemsta stała się dla niego jedyną drogą, a każdy, kto stanie mu na drodze albo nie przyłączy się do jego sprawy, uchodzi za wroga. Wielu widziało, że Eterium popada w obłęd, i odeszło. Kilku książąt Nexusa z rady Eterium porzuciło je, by założyć inne grupy i frakcje o odmiennych celach. Jednym z takich odłamów jest Konsorcjum. Innym – Protektorat...', '', 0),
(18187, 'plPL', 'Jaki jest więc wasz cel?', 'Jaki jest więc wasz cel?', 0),
(18188, 'plPL', 'Uważamy, że Eterium jest dla naszego istnienia równie wielkim zagrożeniem jak Dimensius. Trzeba powstrzymać jedno i drugie...', '', 0),
(18189, 'plPL', 'Chyba teraz rozumiem. Czy mogę w tym jakoś pomóc? Eterium i istoty Pustki zagrażają także naszemu przetrwaniu.', 'Chyba teraz rozumiem. Czy mogę w tym jakoś pomóc? Eterium i istoty Pustki zagrażają także naszemu przetrwaniu.', 0),
(18190, 'plPL', 'Wykryto wrogów. Kończę transmisję.', '', 0),
(18191, 'plPL', 'Transmisja Protektoratu zakończona.', '', 0),
(18197, 'plPL', 'Ugh... Ja źle się czuć.', '', 0),
(18589, 'plPL', '%s zaczyna się przeobrażać...', '', 0),
(18715, 'plPL', '', '%s szepcze cicho pod nosem z nabożną czcią.', 0),
(18718, 'plPL', '', 'Nasza praca w Żywym Gaju nie może zostać zagrożona. Od jego zdrowia i wzrostu zależy samo nasze życie.', 0),
(18727, 'plPL', 'Idź i odpocznij, wędrowcze. Nasze ogniska są twoje.', 'Idź i odpocznij, wędrowcze. Nasze ogniska są twoje.', 0),
(18741, 'plPL', 'Czczę swoich przodków zgodnie z odwieczną tradycją szamańską. Nie wolno nam nigdy zapomnieć o ofiarach, które ponieśli, byśmy mogli tu być.$B$BMy zaś musimy ponieść konieczne ofiary, by nasi potomkowie mieli przyszłość.$B$BCo cię do mnie sprowadza, $N?', '', 0),
(18779, 'plPL', 'Skóra napięta między kośćmi to wezwanie do boju przeciwko głównemu obrońcy Sylvanaar, osady Przymierza, i Żywego Gaju na zachodzie.', '', 0),
(18783, 'plPL', 'Bah! Czy wyglądam, jakbym miał czas na pogaduszki?$B$BCzy wyglądam?$B$BMów szybko, z czym przychodzisz. Trzeba zabijać ogry!', '', 0),
(18788, 'plPL', 'Miło widzieć, że ty, $r, przyczyniasz się do pomyślności Sylvanaar. W bardzo krótkim czasie wiele tu zdziałaliśmy, ale siły, które nas otaczają, zagrażają naszemu sposobowi życia.$B$BWysłucham, co masz do powiedzenia. Mów śmiało, $N.', '', 0),
(18792, 'plPL', 'PALĘ SIĘ!!!', 'PALĘ SIĘ!!!', 0),
(18793, 'plPL', 'PALĘ SIĘ!!! ZNOWU!!', 'PALĘ SIĘ!!! ZNOWU!!', 0),
(18794, 'plPL', 'PARZY!!', 'PARZY!!', 0),
(18795, 'plPL', 'Tylko nie znowu...', 'Tylko nie znowu...', 0),
(18796, 'plPL', 'CZEMU JA!?!', 'CZEMU JA!?!', 0),
(18797, 'plPL', 'Jutro rano będzie bolało.', 'Jutro rano będzie bolało.', 0),
(18798, 'plPL', 'AUUU!!', 'AUUU!!', 0),
(18802, 'plPL', 'Jako przedstawiciele Ligi Odkrywców, Bronwyn i ja jesteśmy tu na prośbę Przymierza, by badać te góry.$B$BAle mówiąc między nami, po długim pobycie w Silithusie po prostu potrzebowaliśmy urlopu. To miejsce wydaje się całkiem niezłe.', '', 0),
(18803, 'plPL', '', 'Może Borgrim ma rację. Może naprawdę potrzebujemy odpoczynku.$B$BAle skoro już tu jesteśmy, nie mogę się doczekać, aż ubrudzę sobie ręce i zbadam, co ta kraina ma do zaoferowania.', 0),
(18816, 'plPL', 'Jasne. Dopiero co urobiliśmy sobie ręce po łokcie, żeby wtaszczyć tu to wszystko, a ty chcesz pracować dalej?', '', 0),
(18830, 'plPL', 'BLEE! Gorszego świństwa w życiu nie próbowałem! Nie dałbym tego pić nawet mojemu baranowi!', '', 0),
(18915, 'plPL', '', 'Hej, nie otwieraj klatki! Dobrze?$B$BTe ogry mają mnie dokładnie tam, gdzie chcę.', 0),
(18948, 'plPL', 'Nie dajcie uciec żadnemu z nich, psy!', '', 0),
(18949, 'plPL', 'Chcę śmierci tych świń z Przymierza i Hordy!', '', 0),
(18951, 'plPL', 'Na górę. Maszerować na Warownię Klanu Ostrza. Chcę ozdobić swoją wieżę głową Gorr\'Dima!', '', 0),
(18952, 'plPL', 'Ty! Widzę cię! Niech któryś z was ich zabije!', '', 0),
(18970, 'plPL', '', 'Przybyłam tu, bo badam zacofaną kulturę dawnego klanu Władców Gromu.$B$BByli słabi i ulegli pokusie mocy, jaka szła w parze z przemianą w spaczonych orków za sprawą krwi Mannorotha.$B$BPrzeczytałam wszystkie ich pisma. Szczególnie zależy mi na odzyskaniu artefaktów – bębna, strzały i tabliczki – które przepadły, gdy zmiażdżyliśmy ogry Klanu Ostrza i zepchnęliśmy je z powrotem do ich warowni.', 0),
(19093, 'plPL', 'Mam tylko jedną zasadę. Wszyscy walczą. Nikt się nie poddaje.', '', 0),
(19095, 'plPL', 'Dalej, małpy. Chcecie żyć wiecznie?', '', 0),
(19096, 'plPL', 'Rozgrzejcie lufy i dajcie im wszystko, co macie.', '', 0),
(19124, 'plPL', 'Stacja Toshleya jest najlepsza! Odosobnienie i zapas dziwnych źródeł energii z Rubieży to idealne warunki do ekstremalnych eksperymentów!', '', 0),
(19125, 'plPL', '$GRozmawiałeś:Rozmawiałaś; już z moim klonem... to znaczy... z moim bliźniakiem?', '', 0),
(19132, 'plPL', 'Nie mogę uwierzyć, że kazali mi wynieść transporter za miasto! Większość gnomów dotkniętych wypadkiem w ciągu kilku tygodni odzyskała jakąś humanoidalną postać, a udział w tak wspaniałym gnomim eksperymencie powinien być zaszczytem!\nPoza tym potrzebowaliśmy jajek!\n', '', 0),
(19133, 'plPL', 'Kiedy już zbudujesz urządzenie, wystarczy je uruchomić, a przeniesie cię do Stacji Toshleya! Kilka osób twierdziło, że zamieniło się w kurczaki, ale jestem pewien, że przesadzały!\nNa twoim miejscu starałbym się nie korzystać z urządzenia w dniu, w którym użył go już ktoś inny, ale nawet jeśli to zrobisz, pewnie wszystko będzie w porządku!', '', 0),
(19136, 'plPL', 'Mam nadzieję, że Ultrabezpieczny transporter nigdy cię nie zawiedzie! Wiem, że nie zawiedzie, ale na wszelki wypadek radzę nosić płaszcz spadochronowy!', '', 0),
(19140, 'plPL', 'Gdzie nasze wsparcie? Mają tu być natychmiast!', '', 0),
(19143, 'plPL', 'JAZDA Z NIMI!!', '', 0),
(19158, 'plPL', '', 'Dobrze, $n, jesteś pod wpływem zaklęcia. Muszę je szybko zbadać, potem porozmawiamy.', 0),
(19282, 'plPL', 'Z pomocą inżyniera Lapforge\'a z Gadżetonu zbudowałem tu, w Stacji Toshleya, potężny gnomi transporter! Chętnie pomogę każdemu gnomiemu inżynierowi, który ma dość umiejętności, by zbudować własną osobistą radiolatarnię transportową.', '', 0),
(19283, 'plPL', 'Czemu jesteś tak daleko od Stacji Toshleya?\n', 'Czemu jesteś tak daleko od Stacji Toshleya?\n', 0),
(19311, 'plPL', 'OSTRZEŻENIE! OSTRZEŻENIE! PRECZ, WROGIE ISTOTY! NIE IDŹCIE GRANIĄ DO STACJI TOSHLEYA!', '', 0),
(19312, 'plPL', 'WŁADAM BIEGLE PONAD DWOMA JĘZYKAMI: KRASNOLUDZKIM, GNOMIM I BARDZO POSPOLITYM WSPÓLNYM JĘZYKIEM LUDZI. ALE NIE MAM POJĘCIA, CO MÓWISZ!$B$BMÓW GŁOŚNIEJ; NIE SŁYSZĘ CIĘ PRZEZ ZGRZYT MOICH TRYBÓW!', '', 0),
(19313, 'plPL', 'Tak, tak... witaj w mojej stacji.$B$BNo i co o tym myślisz? Całkiem zmyślne, co tu zrobiliśmy, prawda?$B$BW każdym razie cieszę się, że pozbyłem się tych nadętych elfów z Sylvanaar.$B$BPrzydaj się tu na coś; jest mnóstwo eksperymentów i innych rzeczy, przy których trzeba pomóc.', '', 0),
(19390, 'plPL', 'Jestem naukowcem, który bada zarówno czas, jak i dźwięk, więc nie bardzo wiem, jak mam myśleć albo znaleźć czas na jakąkolwiek pracę przy całym tym harmidrze?!$B$BCzemu ci głupcy nie mogą wysadzać się gdzie indziej?$B$BAch, cóż, przynajmniej dobrze wyglądam. Powiedz, $gchłopcze:ślicznotko;, czy już cię tu kiedyś widziałem?', '', 0),
(19416, 'plPL', 'Przygotować komory, wkrótce dołączy do nas kolejny sojusznik!', '', 0),
(19417, 'plPL', 'Nasz sojusznik przybył! Oczyścić drogę do komory materializacji!', '', 0),
(19418, 'plPL', 'A teraz udaj się do translokatora. Obóz Kuźniczy Gniew czeka na twoje przybycie!', '', 0),
(19424, 'plPL', 'Witaj w gospodzie Stacji Toshleya. Co mogę dla ciebie zrobić?', '', 0),
(19453, 'plPL', 'Ostatni napór, chłopaki! Dajcie im popalić!', '', 0),
(19454, 'plPL', 'To już ostatni z nich. Tylko bez niedbalstwa!', '', 0),
(19455, 'plPL', 'Dobra robota, żołnierze! To już ostatni z nich!', '', 0),
(19460, 'plPL', '', 'Kiedy jeździsz z Zawadiakami Razaka, uczysz się to i owo o wykonywaniu rozkazów.$B$BPo pierwsze: walczysz, dopóki nie zginiesz. Po drugie: patrz punkt pierwszy.', 0),
(19473, 'plPL', '%s rzuca się do ucieczki w stronę najbliższego kręgu runicznego.', '%s rzuca się do ucieczki w stronę najbliższego kręgu runicznego.', 0),
(19474, 'plPL', '$GSynu:Panienko;, nie będę cię okłamywał; nie jest tu wesoło. Robale bez przerwy nas atakują, a na szali jest nasz sposób życia, nasza wolność!$B$BCzy będziesz $godpowiedzialnym obywatelem:odpowiedzialną obywatelką; i pomożesz?', '', 0),
(19510, 'plPL', 'Głupi, miękki $r. Ta broń teraz moja! Dawać!', '', 0),
(19620, 'plPL', 'Wszelkich rad, które pomogą ci w walce z ogrami, chętnie ci udzielę!', '', 0),
(19627, 'plPL', 'Ogłoszenie wzywa do zabicia ogromnej wilczycy. Podobno ma legowisko na południe od Poszarpanej Grani, w pobliżu twierdzy Hordy.', '', 0),
(19661, 'plPL', 'Góry Klingi to kraina wielkich możliwości. Jaka szkoda, że niektórzy uważają się za lepszych od innych, gdy chodzi o korzystanie z tych możliwości.$B$BZa kogo ma się Ekspedycja Cenariońska, żeby mówić nam, co wolno nam tu robić, a czego nie?', '', 0),
(19662, 'plPL', 'Nadzorco, przybywam, by negocjować w imieniu Ekspedycji Cenariońskiej.', 'Nadzorco, przybywam, by negocjować w imieniu Ekspedycji Cenariońskiej.', 0),
(19663, 'plPL', 'Negocjacje? NEGOCJACJE!$B$BPozwól, że jasno wyłożę nasze stanowisko. Jesteśmy wolnym ludem, możemy robić, co chcemy, oraz przychodzić i odchodzić, kiedy nam się podoba. Ekspedycja Cenariońska nie jest właścicielem tych gór.$B$BŻadnych negocjacji nie będzie! A teraz wracaj do druidów i powiedz im, że dalej będziemy robić, co nam się podoba.', '', 0),
(19664, 'plPL', 'Przybyliśmy do Puszczy Ruuan, by sprawdzić, czy zdołamy przywrócić tym górom równowagę natury.$B$BJednak ingerencja arakkoa i Kultu Żmija bardzo to utrudnia.$B$BNa szczęście są tacy jak ty i Samia, którzy chcą nam pomóc.', '', 0),
(19667, 'plPL', 'Czas na mój lot próbny!', 'Czas na mój lot próbny!', 0),
(19668, 'plPL', 'Wyślij mnie na Przystań Razaana!', 'Wyślij mnie na Przystań Razaana!', 0),
(19669, 'plPL', 'Zabierz mnie do Puszczy Ruuan.', 'Zabierz mnie do Puszczy Ruuan.', 0),
(19671, 'plPL', 'Zabierz mnie na Śpiewającą Grań.', 'Zabierz mnie na Śpiewającą Grań.', 0),
(19673, 'plPL', 'ODPALIĆ DZIAŁA OBRONNE!', '', 0),
(19674, 'plPL', 'Dalej sobie poradzimy. Zawadiacy, rozejść się.', '', 0),
(19677, 'plPL', 'Wykrywam ładunek w twojej okolicy paranarbulatrycznej! $gMusiałeś:Musiałaś; niedawno skorzystać z Kondensatorium zefirium – nie możesz go użyć ponownie, dopóki ładunek nie zaniknie...', '', 0),
(19678, 'plPL', '', 'Jestem tu na polecenie mojego pana, barona Sablemane\'a, by pomóc Ekspedycji Cenariońskiej w kłopotach z Kultem Żmija.$B$BZnam się trochę na tych sprawach.', 0),
(19681, 'plPL', 'Nuaarze, dobrze się czujesz? Wyglądasz dziś jakoś inaczej niż zwykle.', '', 0),
(19682, 'plPL', 'Precz, nadzorco! Już rozmawialiśmy.$B$BPrzestań się ociągać i wykonaj rozkazy w Puszczy Ruuan!', '', 0),
(19683, 'plPL', 'Wszystko dobrze, dziękuję. Wzywałeś mnie?', 'Wszystko dobrze, dziękuję. Wzywałeś mnie?', 0),
(19684, 'plPL', 'Tak, spotkanie. Przejdźmy więc do rzeczy.$B$BFakty są takie, że dostawy drewna i żywego inwentarza z Puszczy Ruuan, za które odpowiadasz, zmalały do ledwie strużki.$B$BPotrzebujemy tych zasobów, a ty pozwoliłeś, żeby druidzi z Ekspedycji Cenariońskiej wchodzili nam w drogę!', '', 0),
(19685, 'plPL', 'Och, to nie moja wina, zapewniam cię.', 'Och, to nie moja wina, zapewniam cię.', 0),
(19686, 'plPL', 'Nie chcę wymówek, żądam wyników!$B$BMyślisz, że to, co tu robimy, to żart? Jeśli nie zrobimy tego jak należy, nie tylko zjawią się ci tak zwani zbawcy świata, ale zostaniemy też uznani za niegodnych awansu w szeregach Czarnoskrzydłych.$B$BTego chcesz?', '', 0),
(19687, 'plPL', 'Eee, nie... nie, wcale tego nie chcę.', 'Eee, nie... nie, wcale tego nie chcę.', 0),
(19688, 'plPL', 'Mógłbyś przynajmniej spróbować brzmieć odrobinę przekonująco.$B$BSłuchaj, Nuaarze, nie zamierzałem ci tego mówić, ale równie dobrze mogę, bo i tak cię to dotyczy. Maxnar planuje zmasowany atak na druidów w Puszczy Ruuan. I zamierza wybić ich do nogi.$B$BJuż i tak źle, że walczymy z ogrami z Boulder\'mok, więc nie stać nas na kolejny front. Zawarłem tymczasowy rozejm z arakkoa.$B$BNo i co o tym sądzisz?', '', 0),
(19689, 'plPL', 'Imponujące. Kiedy atakujemy?', 'Imponujące. Kiedy atakujemy?', 0),
(19690, 'plPL', 'Właśnie w tej chwili kończymy ostatnie przygotowania. Reszta zależy od tego, jak szybko zdołasz zebrać swoje siły w Puszczy Ruuan.$B$BMyślisz, że dasz sobie z tym radę i szybko to załatwisz?', '', 0),
(19691, 'plPL', 'Oczywiście!', 'Oczywiście!', 0),
(19692, 'plPL', 'To rozumiem!$B$BCieszę się, że odbyliśmy to małe spotkanie. Teraz jestem o wiele spokojniejszy o atak. Z takimi dowódcami jak ty na froncie jak możemy przegrać?$B$BDobrze, masz już rozkazy. A teraz wracaj do Puszczy Ruuan i dopilnuj, żeby wszystko się udało!', '', 0),
(19713, 'plPL', 'Witaj, nadzorco. Gotowy do ataku?', 'Witaj, nadzorco. Gotowy do ataku?', 0),
(19714, 'plPL', 'Czegoś potrzebujesz, panie?', 'Czegoś potrzebujesz, panie?', 0),
(19715, 'plPL', 'Nie wyglądasz najlepiej, nadzorco.', 'Nie wyglądasz najlepiej, nadzorco.', 0),
(19716, 'plPL', 'Słyszałem, że Kolphis Mroczna Łuska cię szukał.', 'Słyszałem, że Kolphis Mroczna Łuska cię szukał.', 0),
(19717, 'plPL', 'Samio, wiesz, kim jest Kolphis Mroczna Łuska?', '', 0),
(19718, 'plPL', '', 'Tak, to zastępca przywódcy Kultu Żmija w Sabacie Czarnoskrzydłych, na zachodzie.', 0),
(19719, 'plPL', 'Ci druidzi dotarli do niesamowitego źródła mocy! Potrafią zmieniać się w zwierzęta... ciskać błyskawicami i intensywnym światłem księżyca... Muszę odkryć, jak oni to robią!$B$BMoże noszą pod tymi szatami baterie...', '', 0),
(19727, 'plPL', 'Ten lot zabierze cię na najdalszy kraniec Śpiewającej Grani. Bardzo niebezpieczne!$B$BNa ten będę potrzebował podpisanego zrzeczenia...', '', 0),
(19728, 'plPL', 'Mam podpisane zrzeczenie! Wystrzel mnie na Śpiewającą Grań!', 'Mam podpisane zrzeczenie! Wystrzel mnie na Śpiewającą Grań!', 0),
(19734, 'plPL', 'Zawsze chętnie zbieramy więcej danych z lotów! Dokąd chcesz lecieć?', '', 0),
(19735, 'plPL', 'Chcę polecieć w jedno z dawnych miejsc!', 'Chcę polecieć w jedno z dawnych miejsc!', 0),
(19745, 'plPL', 'Potrzebuję kolejnego zrzeczenia!', 'Potrzebuję kolejnego zrzeczenia!', 0),
(19754, 'plPL', 'Witaj, $n! Jak tam twoje przygody? Moje eksperymenty idą świetnie...$B$BKoniecznie zajrzyj do mnie później! Może będę miał dla ciebie więcej okazji do lotów próbnych!', '', 0),
(19803, 'plPL', 'Witaj. Robisz sobie przerwę, nadzorco? Rzadko cię tu widujemy, odkąd przeniesiono cię do Puszczy Ruuan.$B$BZobacz, co mam do zaoferowania. Może niewiele się zmieniło od naszej ostatniej rozmowy, ale towaru mam sporo.$B$BI nie znikaj nam tak!', '', 0),
(19804, 'plPL', 'Dobrze, pokaż, co masz.', 'Dobrze, pokaż, co masz.', 0),
(19805, 'plPL', 'Moją niechęć do przeszkadzania przewyższa tylko nienawiść do Gruula Smokobójcy i jego siedmiu synów!', '', 0),
(19808, 'plPL', 'Proszę, gotowe.', '', 0),
(19841, 'plPL', 'Grulloc mieć dużo zabawy!', '', 0),
(19842, 'plPL', 'Ja głodny!', '', 0),
(19843, 'plPL', 'Ty być przyjaciel Grulloca!', '', 0),
(19844, 'plPL', 'Mmm, inne białe mięso!', '', 0),
(19845, 'plPL', 'Świnka stać!', '', 0),
(19846, 'plPL', 'Gdzie świnka iść?!', '', 0),
(19857, 'plPL', 'Schabowe!', '', 0),
(19861, 'plPL', 'Fairweather i ja reprezentujemy tu interesy Sylvanaar.$B$BDruidzi są nad wyraz gościnni, ale to, że przepuszczają tędy Hordę, przyprawia mnie o ciarki.', '', 0),
(19882, 'plPL', 'Czy nigdy nie nauczymy się współpracować? A może po prostu wybijemy się nawzajem i odejdziemy w zapomnienie?', '', 0),
(19883, 'plPL', 'Gdyby tylko przywódcy klanów chcieli słuchać. Jedność to jedyna odpowiedź. Wszystkie inne ścieżki prowadzą do naszej zagłady.', '', 0),
(19884, 'plPL', 'Moje przesłanie jedności jest przeznaczone dla klanów ogrów, nie dla takich jak ty!', '', 0),
(19885, 'plPL', 'Nie pozwolę ci zabijać więcej moich pobratymców! Gotuj się na śmierć!', '', 0),
(19886, 'plPL', 'Ogłaszam cię wrogiem klanów ogrów. Karą jest śmierć!', '', 0),
(19892, 'plPL', 'Głupi mały stwór. Ja miażdżyć!', '', 0),
(19893, 'plPL', 'Ja wściekły. Ty dostać w twarz!', '', 0),
(19894, 'plPL', 'Ja zły. Raaah!', '', 0),
(19943, 'plPL', '%s wydaje się bardzo wdzięczny za uwolnienie spod wpływu ducha Koi-Koi.', '', 0),
(19950, 'plPL', 'W lesie dzieje się coś złego. Musimy odkryć, co jest tego źródłem, zanim będzie za późno!', '', 0),
(19991, 'plPL', 'Wkrótce zapuszczę korzenie i zasnę. Zanim odpocznę, trzeba jeszcze coś zrobić.', '', 0),
(20065, 'plPL', 'Wrogowie otaczają nas ze wszystkich stron. Chciałbym dla Mok\'Nathalów lepszego życia, ale siły, z którymi walczymy, zdecydowały za nas inaczej.$B$BJeśli chcesz dowieść Mok\'Nathalom swojej wartości, pomóż nam je wyeliminować.', '', 0),
(20099, 'plPL', 'Dziwi cię to, co widzisz, przybyszu?$B$BOddajemy cześć duchom naszych przodków, podtrzymując płomień pamięci o nich i składając im hołd.', '', 0),
(20101, 'plPL', '%s staje się niesamowicie potężny!', '', 0),
(20148, 'plPL', 'Dobrze jest pospacerować i rozprostować wszystkie cztery kończyny. Czy mogę ci w czymś pomóc, $N?', '', 0),
(20149, 'plPL', 'Maska gazowa zaprzysiężonych Spaczeniu została zniszczona. Masz może drugą?', 'Maska gazowa zaprzysiężonych Spaczeniu została zniszczona. Masz może drugą?', 0),
(20167, 'plPL', 'Poszukiwanie mojego ludu. Nasza walka z Przymierzem. Wojna z ogrami i ich panami, gronnami.$B$BWszystko to ciąży mi na barkach, $N.$B$BNawet mnie przyda się czasem pomoc.', '', 0),
(20209, 'plPL', 'Wiemy, że wyznawcy Kultu Żmija gromadzą się po drugiej stronie tunelu. Tu stawimy im opór.', '', 0),
(20215, 'plPL', 'Dobrze, że zdołałem zrobić duplikaty Maski gazowej zaprzysiężonych Spaczeniu.', '', 0),
(20251, 'plPL', 'Wrota Śmierci to portal otwierający się na świat, w którym Płonący Legion hoduje swoje ogary spaczenia i inne psowate potworności. Ilekroć widzisz któreś z tych stworzeń, wiedz, że stamtąd pochodzi i że najpierw przeszło tędy.$B$BOstatnio dowiedzieliśmy się, że Płonący Legion nasilił przywoływanie tych stworzeń przez portal.$B$BMusisz zamknąć Wrota Śmierci, zanim ta fala stanie się niepowstrzymana i wszystko będzie stracone!', 'Wrota Śmierci to portal otwierający się na świat, w którym Płonący Legion hoduje swoje ogary spaczenia i inne psowate potworności. Ilekroć widzisz któreś z tych stworzeń, wiedz, że stamtąd pochodzi i że najpierw przeszło tędy.$B$BOstatnio dowiedzieliśmy się, że Płonący Legion nasilił przywoływanie tych stworzeń przez portal.$B$BMusisz zamknąć Wrota Śmierci, zanim ta fala stanie się niepowstrzymana i wszystko będzie stracone!', 0),
(20258, 'plPL', 'Ja lubić miękki bekon!', '', 0),
(20259, 'plPL', 'Ja trzymać świnka jako zwierzątko!', '', 0),
(20261, 'plPL', 'Misha ryczy głośno i orze pazurami ołtarz gronna.', '', 0),
(20299, 'plPL', 'Władco dziczy, mój Sygnał druida chyba przepadł.', 'Władco dziczy, mój Sygnał druida chyba przepadł.', 0),
(20317, 'plPL', 'Kto śmie budzić Goca z błogiego snu?', '', 0),
(20321, 'plPL', 'Twoje imię jest dla mnie równie nieistotne jak imiona tysięcy, którzy zginęli pod potęgą Goca. Zmiażdżę ciebie i $n!', '', 0),
(20365, 'plPL', 'CO?! Kto śmie przeszkadzać Płonącemu Legionowi?', '', 0),
(20366, 'plPL', 'Szykuj się na wieczne katusze, śmiertelniku!', '', 0),
(20367, 'plPL', 'Nic nie odwróci twojej zguby!', '', 0),
(20368, 'plPL', 'Z przyjemnością poczuję zapach tłuszczu z twojego szpiku skwierczącego nad ogniem!', '', 0),
(20369, 'plPL', 'ŚMIESZ mnie atakować?!', '', 0),
(20370, 'plPL', 'Za tę zniewagę będziesz cierpieć powoli aż do końca czasu!', '', 0),
(20381, 'plPL', 'Kto śmie tak znieważać ołtarz Goca?', '', 0),
(20631, 'plPL', 'Strzeż się Eterium, które otacza nas ze wszystkich stron.', '', 0),
(20637, 'plPL', '<Duch arakkoa wyciąga ku tobie rękę, jakby próbował cię rozpoznać. Masz wrażenie, że nie widzi cię wyraźnie.>$B$BRokkaramie, czy to ty?', '', 0),
(20638, 'plPL', 'Tak... tak, to ja...', 'Tak... tak, to ja...', 0),
(20639, 'plPL', 'Wybacz, że cię wypytuję, mój synu. Mój wzrok nie jest już taki jak dawniej, ale kruk pobłogosławił mnie długim życiem.$B$BWkrótce nadejdzie czas, byś zajął moje miejsce. Nauczyłem cię wszystkiego, co wiem. Żałuję tylko, że nie okazałem się dość godny, by odzyskać naszą świętą Księgę Kruka.', '', 0),
(20640, 'plPL', 'Tak, starszy. Opowiedz mi więcej o księdze.', 'Tak, starszy. Opowiedz mi więcej o księdze.', 0),
(20641, 'plPL', 'Prawdziwie wierzący żyją w hańbie od dnia, w którym nasi zdradzieccy krewniacy ze Skettis ukradli nam księgę, roztrzaskali jej tablicę i zakopali fragmenty w swoim nędznym mieście!$B$BMódl się, by kruk wybrał ciebie do jej odtworzenia, mój synu. Bądź wierny i pamiętaj zawsze o proroctwie: „Ze snów swych wrogów kruk wyskoczy na świat”.', '', 0),
(20698, 'plPL', 'O czym myślisz, kiedy słyszysz „Dziki Młot”, co? O jeźdźcach gryfów, jeśli masz choć trochę oleju w głowie! Dolina Cienistego Księżyca to nie Orle Gniazdo, ale i tak mamy dla ciebie świetne zwierzęta, o tak, świetne. Obejrzyj moje ślicznotki i zobacz, czy któraś nie wpadnie ci w oko!', '', 0),
(20699, 'plPL', 'Pokaż mi swoje gryfy, Brunnie.', 'Pokaż mi swoje gryfy, Brunnie.', 0),
(20763, 'plPL', '', 'Wspaniałe zwierzęta, prawda? Wiwerny, które tu hodujemy, są szkolone, by radzić sobie w najsroższych i najdziwniejszych warunkach pogodowych, jakie ma do zaoferowania Draenor. Przekonasz się, że są niezawodne i wytrzymałe.', 0),
(20773, 'plPL', 'Śmiesz mnie przyzywać?', '', 0),
(20950, 'plPL', 'Tak, $gkrólu:królowo;?', '', 0),
(20951, 'plPL', 'Ty zabić gronn! Teraz ty walczyć z rzeczy z nieba?', '', 0),
(20952, 'plPL', 'Moje życie dla ciebie, $n!', '', 0),
(20953, 'plPL', 'To picie dobre!', '', 0),
(20954, 'plPL', 'Jak $gkról:królowa; $n tańczyć, ja tańczyć!', '', 0),
(20955, 'plPL', '$GKról:Królowa; nie gniewać się na mnie?', '', 0),
(20956, 'plPL', 'Czemu ty tak na mnie patrzeć? Ty nie chcieć mnie całować, prawda!?', '', 0),
(20957, 'plPL', 'Teraz wszyscy Synowie Gruula martwi! Teraz $gnowy król:nowa królowa; prowadzić wszystkie ogry do Ogri\'la!', '', 0),
(20967, 'plPL', '', 'Lepiej szybko się obudź, żółtodziobie. To nie nasze wygodne podwórko pod Skettis; to Góry Klingi! Jeden fałszywy ruch i rozbijasz się w płomieniach!', 0),
(21024, 'plPL', 'Klany ogrów nie dadzą się podporządkować. Ani gronnom, ani takiemu słabeuszowi jak ty!', '', 0),
(21025, 'plPL', 'Mog\'dorg to głupiec, jeśli myśli, że któraś z mniejszych ras będzie naszym zbawcą.', '', 0),
(21027, 'plPL', 'Nie kłaniajcie się marionetce Mog\'dorga! Chce zastąpić naszych panów gronnów władcą z gorszego rodu. Czemu mielibyśmy zamieniać jednego pana na drugiego?', '', 0),
(21028, 'plPL', 'Nadszedł czas. Zabijcie każde stworzenie, które stoi na drodze klanów!', '', 0),
(21029, 'plPL', 'Nie słuchajcie kłamstw Mog\'dorga! Ogri\'la to mit! Tworzymy tu własny raj krwią wszystkich, którzy chcieliby nas podzielić i podporządkować!', '', 0),
(21032, 'plPL', 'Agh... ja... martwy.', '', 0),
(21033, 'plPL', 'Ja iść do... Ogri\'la.', '', 0),
(21034, 'plPL', 'Ja zaszczycony... $gkról:królowa; mnie zabić.', '', 0),
(21035, 'plPL', '$GKról:Królowa; $n, ja teraz umierać.', '', 0),
(21049, 'plPL', '$GKról:Królowa; myśleć... że naprawdę... jest Ogri\'la?', '', 0),
(21050, 'plPL', 'Mały $r... ty być... $gokropny król:okropna królowa;.', '', 0),
(21166, 'plPL', 'Trzymaj język za zębami, jeśli chodzi o to, co tu słyszysz i widzisz.', '', 0),
(21167, 'plPL', '$GKról:Królowa;! Chort gotowy służyć.', '', 0),
(21264, 'plPL', 'Teraz ja urosnąć i cię zmiażdżyć!', '', 0),
(21279, 'plPL', 'W czym mogę ci pomóc, $N?', '', 0),
(21284, 'plPL', '', 'Jeśli szukasz gadżetów, dyndadełek, wihajstrów, pierdółek, cosiów, dynksów albo ustrojstw, to dobrze $gtrafiłeś:trafiłaś;!', 0),
(21285, 'plPL', 'Pokaż mi swój asortyment, eee... rzeczy.', 'Pokaż mi swój asortyment, eee... rzeczy.', 0),
(21358, 'plPL', 'Och, podoba ci się moja przepaska na oko, co? No to uważaj, żeby tobie nie przyszło takiej nosić, $gchłopaczku:panienko;.', '', 0),
(21359, 'plPL', '', 'Hę? Co? Jestem trochę zajęta, $gprzyjacielu:przyjaciółko;!$B$BOczywiście jeśli chcesz pomóc, to mam dla ciebie cały czas świata.', 0),
(21366, 'plPL', '%s wygląda na gotową do schwytania.', '', 0),
(21370, 'plPL', '', 'Rany! Dzięki, że $gprzyprowadziłeś:przyprowadziłaś; ją aż tutaj. Nie $gmusiałeś:musiałaś; tego robić.', 0),
(21371, 'plPL', '', 'Złoto z ciebie! Dopilnuję, żeby płaszczka miała należytą opiekę.', 0),
(21379, 'plPL', 'Płonące oczy w pryzmacie napełniają twój umysł poczuciem grozy...', '', 0),
(21380, 'plPL', 'Umieść w pryzmacie 35 odłamków apeksisu.', 'Umieść w pryzmacie 35 odłamków apeksisu.', 0),
(21381, 'plPL', 'Spaczona kuźnia kryształów może przemienić twoje odłamki apeksisu w niestabilne flaszki bestii. Flaszki te czynią pijącego zwinniejszym, silniejszym i wytrzymalszym.$B$BDokonaj wyboru poniżej.', '', 0),
(21382, 'plPL', 'Kup 1 Niestabilną flaszkę bestii za 10 odłamków apeksisu', 'Kup 1 Niestabilną flaszkę bestii za 10 odłamków apeksisu', 0),
(21383, 'plPL', '<Gdy wkładasz odłamki apeksisu do spaczonej kuźni kryształów i pociągasz za dźwignię, urządzenie wydaje nieziemski dźwięk, mieląc je na proch. Po chwili z jego „paszczy” wyskakuje twoja flaszka.>', '', 0),
(21384, 'plPL', 'Użyj spaczonej kuźni kryształów, by dokonać kolejnego zakupu.', 'Użyj spaczonej kuźni kryształów, by dokonać kolejnego zakupu.', 0),
(21385, 'plPL', 'Kup 5 Niestabilnych flaszek bestii za 50 odłamków apeksisu', 'Kup 5 Niestabilnych flaszek bestii za 50 odłamków apeksisu', 0),
(21386, 'plPL', '<Gdy wkładasz odłamki apeksisu do spaczonej kuźni kryształów i pociągasz za dźwignię, urządzenie wydaje nieziemski dźwięk, mieląc je na proch. Po chwili z jego „paszczy” wyskakują twoje flaszki.>', '', 0),
(21387, 'plPL', 'Kuźnia kryształów Bash\'ira może przemienić twoje odłamki apeksisu w niestabilne flaszki czarownika. Flaszki te czynią pijącego inteligentniejszym i wytrzymalszym, a także zwiększają skuteczność jego magii zadającej obrażenia i leczącej.$B$BDokonaj wyboru poniżej.', '', 0),
(21388, 'plPL', 'Kup 1 Niestabilną flaszkę czarownika za 10 odłamków apeksisu', 'Kup 1 Niestabilną flaszkę czarownika za 10 odłamków apeksisu', 0),
(21389, 'plPL', 'Użyj kuźni kryształów Bash\'ira, by dokonać kolejnego zakupu.', 'Użyj kuźni kryształów Bash\'ira, by dokonać kolejnego zakupu.', 0),
(21390, 'plPL', '<Gdy umieszczasz odłamki apeksisu we wnęce kuźni kryształów Bash\'ira i pociągasz za dźwignię, urządzenie dosłownie je dezintegruje. Po chwili u twoich stóp pojawia się twoja flaszka.>', '', 0),
(21391, 'plPL', 'Kup 5 Niestabilnych flaszek czarownika za 50 odłamków apeksisu', 'Kup 5 Niestabilnych flaszek czarownika za 50 odłamków apeksisu', 0),
(21392, 'plPL', '<Gdy umieszczasz odłamki apeksisu we wnęce kuźni kryształów Bash\'ira i pociągasz za dźwignię, urządzenie dosłownie je dezintegruje. Po chwili u twoich stóp pojawiają się twoje flaszki.>', '', 0),
(21393, 'plPL', 'Mamy nadzieję, że zdołasz ulżyć naszym bólom głowy. Spróbuj mieć dziesięciu synów, z których każdy chce robić coś, do czego się nie nadaje!$B$BAle cóż, jako ojciec robimy, co musimy.', '', 0),
(21394, 'plPL', 'Masz jakichś synów, $N?$B$BPowiemy ci coś: chyba byliśmy znacznie szczęśliwsi, zanim przybyliśmy do Ogri\'la, a kryształy wyostrzyły nam umysł. Dawniej po prostu walnęlibyśmy ich w łeb, żeby się zamknęli. A teraz tylko męczą nas o Podniebną Straż Sha\'tari.$B$BNiewiedza to błogość!', '', 0),
(21395, 'plPL', 'Chłopak jest jeszcze za głupi, żeby to powiedzieć – za krótko przebywał przy kryształach – ale jest ci wdzięczny za to, że $gzdobyłeś:zdobyłaś; dla niego te flaszki.$B$BZostało już tylko dziewięciu synów. Ech!$B$B<Obie głowy Torkusa wzdychają.>$B$BChcesz nam któregoś zdjąć z głowy? Sprzedamy ci go tanio.', '', 0),
(21396, 'plPL', 'Jesteś w Ogri\'la od niedawna, więc nie przebywasz przy tutejszych kryształach dość długo, by w pełni czerpać z nich korzyści. Poza tym masz tylko jedną głowę.$B$BMy natomiast jesteśmy tu od bardzo dawna. Jak możesz sobie wyobrazić, znamy się więc całkiem nieźle na wielu rzeczach.$B$BOstatnio szczególnie zainteresowały nas demony z obozów kuźniczych. A dokładniej, wymyśliliśmy sposób, by pozbyć się ich na dobre.$B$BPrzynajmniej w teorii.', '', 0),
(21397, 'plPL', 'Chcielibyśmy móc tworzyć więcej niż jedną mroczną runę dziennie, ale szkoda na to czasu. To po prostu fizycznie niemożliwe. Poza tym nawet w takim tempie nie potrafimy ich niezawodnie tworzyć.$B$BI uwierz nam, gdyby był tu ktoś jeszcze dość mądry, by pomóc, zostałby wcielony do roboty, a my mielibyśmy tyle mrocznych run, ile trzeba.', '', 0),
(21398, 'plPL', 'Kuźnia kryształów Bash\'ira może przemienić twoje odłamki apeksisu w niestabilne flaszki czarownika. Flaszki te czynią pijącego inteligentniejszym i wytrzymalszym, a także zwiększają skuteczność jego magii zadającej obrażenia i leczącej.$B$BWygląda jednak na to, że nie masz wymaganych dziesięciu odłamków, by kupić choćby jedną flaszkę.', '', 0),
(21399, 'plPL', 'Spaczona kuźnia kryształów może przemienić twoje odłamki apeksisu w niestabilne flaszki bestii. Flaszki te czynią pijącego zwinniejszym, silniejszym i wytrzymalszym.$B$BWygląda jednak na to, że nie masz dziesięciu odłamków potrzebnych do zakupu choćby jednej flaszki.', '', 0),
(21401, 'plPL', 'Gahk nowy w Ogri\'la jak mały $r. To jak raj, o którym inne ogry na dole zawsze gadać. Ale głowy Gahka boleć od kryształ, co robić Gahk mądrzejszy.$B$B<Obie głowy Gahka kiwają do siebie.>$B$BMy uczyć się robić mroczna runa z kryształowej kuźni. Jak my się nauczyć, my rozwalić brama wypaczenia demonów!', '', 0),
(21402, 'plPL', 'Gahk teraz mądry! My wiedzieć, jak zrobić z mroczna runa mroczna runa z kryształowej kuźni!', '', 0),
(21403, 'plPL', '$n dobrze rozwalić brama wypaczenia, ale demony znowu ją wzmocnić.$B$B$n przynieść Gahk kolejna mroczna runa, a Gahk zrobić specjalna mroczna runa z kryształowej kuźni dla $n!', '', 0),
(21404, 'plPL', 'Witaj w Ogri\'la, $N.$B$BTutejsze ogry dzięki magicznym emanacjom okolicznych kryształów zyskały wielką bystrość umysłu. Choć nie do końca rozumiemy, jak one działają, doceniamy nasz nowy dom i pragniemy tylko żyć w pokoju.$B$BTym bardziej szkoda, że demony i eterycy, a zwłaszcza Czarne Stado, nie chcą zostawić nas w spokoju.', '', 0),
(21405, 'plPL', 'W imieniu całego Ogri\'la dziękujemy ci za twoje starania, $n.$B$B<Lewa głowa Chu\'a\'lora kiwa, a prawa uśmiecha się do ciebie.>$B$BI nie zapominaj, że pomagając nam tutaj, pomagasz też chronić naszych braci na dole, dla których $gstałeś się niczym król:stałaś się niczym królowa;.', '', 0),
(21413, 'plPL', 'Jajo wydaje się wytrzymałe, jak przystało na jajo Czarnego Stada. Może gdyby położyć obok niego mnóstwo odłamków apeksisu, ich wibracje sprawiłyby, że pęknie?', '', 0),
(21414, 'plPL', 'Jajo wydaje się wytrzymałe, jak przystało na jajo Czarnego Stada. Może gdyby położyć obok niego mnóstwo odłamków apeksisu, ich wibracje sprawiłyby, że pęknie?$B$BSzkoda, że nie masz trzydziestu pięciu odłamków apeksisu potrzebnych do tego zadania.', '', 0),
(21415, 'plPL', 'Umieść 35 odłamków apeksisu obok smoczego jaja, by je rozbić.', 'Umieść 35 odłamków apeksisu obok smoczego jaja, by je rozbić.', 0),
(21442, 'plPL', 'Ech, widzę, że pracy ci nie brakowało, co?! Nie wiem, jak ci dziękować za zbombardowanie tych demonów i dostarczenie nam nowych wierzchowców.$B$BBardzo nam ułatwiasz robotę. Tak trzymaj, $gchłopcze:dziewczyno;!', '', 0),
(21474, 'plPL', 'Relikt apeksisu migocze, zdradzając ukrytą w nim inteligencję.', '', 0),
(21475, 'plPL', 'Włóż odłamek apeksisu i zacznij!', 'Włóż odłamek apeksisu i zacznij!', 0),
(21477, 'plPL', 'Monument apeksisu góruje nad tobą.', '', 0),
(21478, 'plPL', 'Włóż 35 odłamków apeksisu i zacznij!', 'Włóż 35 odłamków apeksisu i zacznij!', 0),
(21486, 'plPL', 'Płonące oczy w pryzmacie napełniają twój umysł poczuciem grozy... zwłaszcza że wiesz, iż nie masz trzydziestu pięciu odłamków apeksisu potrzebnych do przyzwania jego demona.', '', 0),
(21533, 'plPL', 'Witaj, $gprzyjacielu:przyjaciółko;! Co chcesz obejrzeć?', '', 0),
(21534, 'plPL', 'Witaj, $gbracie:siostro;. W czym możemy służyć?', '', 0),
(21535, 'plPL', 'Jak możemy ci pomóc?', '', 0),
(21536, 'plPL', '$GPotężny:Potężna;! W czym możemy ci służyć?', '', 0),
(21537, 'plPL', 'Twoja obecność to dla nas zaszczyt, $gprzyjacielu:przyjaciółko;. W czym możemy ci dziś służyć?', '', 0),
(21538, 'plPL', '$GPotężny:Potężna;! Mamy nadzieję, że nasze jedzenie przypadnie ci do gustu.', '', 0),
(21539, 'plPL', 'Nasze jedzenie zaspokoi nawet największy głód.', '', 0),
(21540, 'plPL', 'Wciąż $ggłodny:głodna;, $gbracie:siostro;? Jak możemy pomóc?', '', 0),
(21541, 'plPL', 'Mamy dla ciebie prawdziwą ucztę, $gprzyjacielu:przyjaciółko;.', '', 0),
(21542, 'plPL', 'Jakie smakołyki możemy ci zaproponować?', '', 0),
(21547, 'plPL', '', 'Hej, $gtowarzyszu:towarzyszko;. Jeśli zdobędziesz uznanie Podniebnej Straży, mogę ci zaoferować bezpośredni lot do naszej bazy, Przystani Czarnego Wiatru, w Górach Skethyl.$B$BPodoba ci się moja piękna płaszczka Otchłani? Jest urocza.', 0),
(21549, 'plPL', '', 'Witaj, $n. Chcesz szybko dostać się na Przystań Czarnego Wiatru, naszą bazę w Górach Skethyl? Mam gotową śliczną płaszczkę Otchłani.$B$BChcesz lecieć teraz? Wystarczy słowo, $gsiłaczu:króliczku;!', 0),
(21550, 'plPL', 'Tak, chętnie polecę na Przystań Czarnego Wiatru.', 'Tak, chętnie polecę na Przystań Czarnego Wiatru.', 0),
(21565, 'plPL', 'Zdradzimy ci sekret naszej diety: koktajle i marzenia. W jednym z nich możemy ci pomóc.', '', 0),
(21568, 'plPL', 'Każdy musi pić. Co możemy ci podać?', '', 0),
(21570, 'plPL', 'Witaj, $gbracie:siostro;, jak możemy pomóc?', '', 0),
(21571, 'plPL', 'Nasze napitki ugaszą nawet największe pragnienie.', '', 0),
(21572, 'plPL', 'Nie masz nic lepszego do roboty, $gchłopcze:dziewczyno;, niż mielić ze mną ozorem?$B$BA teraz ruszaj tam i pokaż, co w tobie drzemie!', '', 0),
(21573, 'plPL', 'To rozumiem, $gchłopcze:dziewczyno;! Wszyscy jesteśmy z ciebie dumni za całą robotę, którą wykonujesz!$B$BA wiesz, jeśli chcesz szybko dostać się do naszej drugiej bazy w Górach Skethyl, zejdź na dół i pogadaj z treserką Podniebnej Straży Ireną. Ona wszystko ci ładnie załatwi.', '', 0),
(21574, 'plPL', 'Stajesz się tu postacią wręcz czczoną, $gchłopcze:dziewczyno;! Gdybym nie wiedział lepiej, powiedziałbym, że ostrzysz sobie zęby na moją posadę!!!$B$BTak czy siak, jeśli dalej będziesz się tak sprawiać, to na nią zasłużysz!', '', 0),
(21575, 'plPL', 'Pij albo znikaj!', '', 0),
(21576, 'plPL', 'Co mogę powiedzieć, $n? Jesteś chlubą Podniebnej Straży Sha\'tari!$B$BTylko niech ci to nie uderzy do głowy. Wciąż mogę cię tego i owego nauczyć, $gchłopcze:dziewczyno;!$B$B<Podniebny dowódca Keller uśmiecha się szeroko i puszcza do ciebie oko.>', '', 0),
(21577, 'plPL', '', 'Widzę, że swoje już tu $godsłużyłeś:odsłużyłaś;, $N.$B$BSłuż dalej; demony jeszcze nie zniknęły, żółtodziobie.', 0),
(21578, 'plPL', '', 'Twoje imię jest na ustach wszystkich w posterunku. Nie pozwól, żeby uderzyło ci to do głowy; wiem, że stać cię na więcej!$B$BBędę cię obserwować, żółtodziobie.', 0),
(21579, 'plPL', 'W czym możemy służyć, $gwywyższony:wywyższona;?', '', 0),
(21580, 'plPL', '', 'No dobra, przyznaję: $gdowiodłeś:dowiodłaś; swojej wartości z nawiązką, $n.$B$BJeśli wcześniej byłam dla ciebie surowa, to dlatego, że widziałam w tobie iskrę prawdziwego członka Podniebnej Straży. Śmiem twierdzić, że jesteś naszym najlepszym asem.$B$BJeśli tylko zechcesz pomóc, z największą dumą wręczę ci kolejny zestaw bomb.', 0),
(21581, 'plPL', 'Chętnie zaopatrzymy cię we wszystko, czego trzeba.', '', 0),
(21582, 'plPL', '$GSzanowny bracie:Szanowna siostro;, jak możemy pomóc?', '', 0),
(21583, 'plPL', '', 'Hej, $N!$B$B<Khatie patrzy na ciebie chytrze.>$B$BJeśli tylko zechcesz nałapać nam więcej płaszczek eteru, koniecznie przyjdź do mnie!', 0),
(21584, 'plPL', '$GPrzyjacielu:Przyjaciółko;! Dawno się nie widzieliśmy. Co możemy ci podać?', '', 0),
(21586, 'plPL', '', 'Wiesz, $n, to taki zaszczyt pracować z tobą!$B$BKiedy nie będziesz $gzajęty:zajęta; łapaniem, może moglibyśmy $gwyskoczyć gdzieś na kolację?:urządzić sobie babski wieczór?;$B$BAch, czy wspominałam, że teraz możemy cię szybko przerzucić do naszej bazy w Górach Skethyl? Jeśli chcesz, porozmawiaj o tym z treserką Podniebnej Straży Ireną.', 0),
(21587, 'plPL', '', 'Dużo się tu kręcisz, ale jakoś wciąż nie udaje nam się spotkać po pracy.$B$BTo przeze mnie?$B$B<Khatie celowo się rozpogadza.>$B$BW każdym razie chciałam tylko powiedzieć, że ja... że naprawdę doceniamy wszystko, co robisz dla Podniebnej Straży!', 0),
(21588, 'plPL', '', 'Mam nadzieję, że nie uważasz mnie za jakąś natrętną prześladowczynię, $n.$B$BTo znaczy, wiem, że jesteś teraz $gsławny:sławna; w całej Podniebnej Straży, no i... na pewno nie $gchciałbyś:chciałabyś; spędzać czasu z takim szarym pionkiem jak ja.$B$BAle jeśli kiedyś zechcesz się spotkać, żeby po prostu pobyć razem, albo nałapać więcej płaszczek, wpadnij, kiedy chcesz! Będę tutaj.$B$BTęsknię za tobą...', 0),
(21589, 'plPL', 'Relikty są prawdziwie wielką tajemnicą. Może jeśli będziesz je regularnie badać, lepiej docenisz ich możliwości.', '', 0),
(21590, 'plPL', '<Lewa głowa Chu\'a\'lora mówi:>$B$BTwój zapał do pomocy bardzo nam się podoba...$B$B<Jego prawa głowa kończy:>$B$B...i chcemy, żebyś $gwiedział:wiedziała;, że bardzo doceniamy twoje starania!', '', 0),
(21591, 'plPL', 'Stal nie jest silna, $gwywyższony:wywyższona;, ciało jest silniejsze. Stal czerpie siłę z tego, kto nią włada. Ale dość o tym... W czym możemy ci pomóc, $gwywyższony:wywyższona;?', '', 0),
(21592, 'plPL', 'Twoje imię zaczyna tu być czczone.$B$B<Lewe oko Chu\'a\'lora przeszywa cię kamiennym spojrzeniem.>$B$BTak trzymaj, $n!', '', 0),
(21593, 'plPL', 'Najpierw $gzostałeś królem:zostałaś królową; ogrów na dole, a teraz $gwywyższyłeś:wywyższyłaś; się wśród nas, mieszkańców Ogri\'la.$B$BTo niesłychane jak na kogoś z twojej rasy, a jednak stoisz tu jako żywy dowód. Dziękuję ci, $n; wszyscy mamy wobec ciebie dług, którego nigdy tak naprawdę nie zdołamy spłacić!', '', 0),
(21594, 'plPL', 'Niewielu rzeczom w życiu można ufać. Stali możesz ufać.', '', 0),
(21595, 'plPL', 'To zaszczyt, że pomagasz nam, ogrom. Podtrzymujesz naszą nadzieję na lepszą przyszłość.$B$BGdybyśmy tylko mogli pozbyć się tych bólów głowy. Na pewno nie chcesz któregoś z naszych synów?', '', 0),
(21596, 'plPL', 'Czym jest stal w porównaniu z ręką, która ją kształtuje?', '', 0),
(21597, 'plPL', 'To niesamowite, jak bardzo nam $gpomogłeś:pomogłaś;. Śmiemy twierdzić, że gdyby nie ty, demony już by nas zalały albo Czarne Stado usmażyłoby nas na chrupko!$B$BA tak na marginesie, wspominaliśmy, że sprzedamy ci jednego z naszych synów, tanio, prawda? Nie? Nie jesteś $gzainteresowany:zainteresowana;?', '', 0),
(21598, 'plPL', 'Tu, w Ogri\'la, mamy czas rozważać zagadkę stali. Ale dość o tym, jak możemy pomóc?', '', 0),
(21599, 'plPL', 'Masz stal, którą trzeba ukształtować?', '', 0),
(21600, 'plPL', 'Nie wiemy, jak ci dziękować za wszystko, co $gzrobiłeś:zrobiłaś;, by chronić naszą rodzinę, $n.$B$BI zdajesz sobie sprawę, że wcześniej żartowaliśmy, proponując, że sprzedamy ci jednego z naszych synów? Nie, naprawdę... choć czujemy, że nadciąga kolejna para bólów głowy.$B$BJuniorze, siedźże spokojnie!', '', 0),
(21601, 'plPL', 'My zaczynać lubić mały $n! Ty dobrze tłuc demony!', '', 0),
(21602, 'plPL', 'Gahk lubić mały $r $n. Ty zabić duży demon; wszystkie małe demony się bać!$B$B<Obie głowy Gahka uśmiechają się do ciebie szeroko.>', '', 0),
(21603, 'plPL', 'My ciągle widzieć ty tutaj!$B$BChu\'a\'lor mówić, mały $r to nasz $gbohater:bohaterka;!$B$B$n teraz jak jeden z nas, ogrów. Tylko Gahk nie rozumieć, bo $n do tego musieć być $gwiększy:większa;!', '', 0),
(21604, 'plPL', 'Co możemy ci podać, nasz $gwywyższony bracie:wywyższona siostro;?', '', 0),
(21605, 'plPL', 'Czym możemy służyć?', '', 0),
(21608, 'plPL', '$GSzanowny bracie:Szanowna siostro;, jak możemy pomóc?', '', 0),
(21609, 'plPL', 'Witaj, $gprzyjacielu:przyjaciółko;! Co możemy dla ciebie zrobić?', '', 0),
(21610, 'plPL', 'Jesteśmy tu, by pomóc.', '', 0),
(21611, 'plPL', 'Wyrabiasz sobie tu niezłą sławę, $N. Brawo.$B$BUfamy, że nie pozwolisz, żeby uderzyło ci to do twojej jedynej głowy, i że nadal będziesz pomagać w wypędzaniu demonów?', '', 0),
(21612, 'plPL', 'Twoja bezinteresowność nas zawstydza, $n. Jeśli w przeszłości wydawaliśmy się nieco zarozumiali, wiedz, że to dzięki twojemu przykładowi zdołaliśmy zmienić swoje nastawienie.$B$BDziękujemy ci i mamy nadzieję, że nadal będziesz nas wspierać w walce z obozami kuźniczymi.', '', 0),
(21618, 'plPL', 'Dobrze się bawisz u nas w Ogri\'la?$B$BNasze ogry robią mnóstwo rzeczy, dniem i nocą. Najlepsze zostawiamy na sprzedaż dla najfajniejszych gości, takich jak ty!$B$BWięc kiedy będziesz tam robić swoje i czynić góry bezpieczniejszymi, wpadaj czasem zobaczyć, co mamy.$B$BPowodzenia tam, $gstary:mała;.', '', 0),
(21628, 'plPL', 'Jho\'nassie, pokaż mi, co masz do zaoferowania.', 'Jho\'nassie, pokaż mi, co masz do zaoferowania.', 0),
(21642, 'plPL', 'Chu\'a\'lor dobrze o tobie mówi, $n. Jeśli chcesz, mamy na sprzedaż parę specjalnych ogrzych piw.$B$BSą naprawdę smaczne!', '', 0),
(21643, 'plPL', 'Otacza cię tu coś w rodzaju czci, $gstary:kiciu;. Wygląda na to, że wszyscy o tobie gadają. Czadowo.$B$BZobaczmy, czy mamy na stanie coś, co cię zainteresuje. Mamy mnóstwo fajnych rzeczy.', '', 0),
(21644, 'plPL', 'Co tu dużo mówić, $n? $GZiomalu:Ziomalko;, wszystko, co mamy w sklepie, możesz kupić!$B$BCzad!', '', 0),
(21814, 'plPL', 'Potrzebujesz zaopatrzenia na wyprawę w teren?', '', 0),
(21815, 'plPL', 'Jak mogę cię dziś wyposażyć, $gpanie:pani;?', '', 0),
